"use strict";
const LESSONS = {
 "86": "═\n# पाठ-86: Business Suite, Page, Instagram Pro — एक घर\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड 1-6 में हमारी पूरी दुकान WhatsApp पर बनी। आज से खंड-7 — वही उत्पाद, वही मास्टर-शीट, अब Facebook और Instagram पर भी दिखेंगे। पाठ के बाद आप तीन बातें कर पाएँगे — Meta Business Suite, Facebook Page और Instagram Professional खाते का आपसी रिश्ता बता पाएँगे; तीनों को एक ही \"घर\" से जोड़ पाएँगे; और समझ पाएँगे कि यह खंड कैसे खंड-2 और खंड-6 की मेहनत को दोबारा उपयोग करेगा।\n\n## 2. मुख्य बात\nWhatsApp Business, Facebook Page और Instagram — तीनों अलग-अलग ऐप लगते हैं, पर मालिक एक ही कंपनी — Meta। एक-वाक्य बात — **Meta Business Suite वह एक \"घर\" है जहाँ से Facebook Page, Instagram Professional खाता और WhatsApp Business तीनों को एक साथ, एक ही dashboard से चलाया जा सकता है — अलग-अलग तीन दरवाज़ों की जगह एक बड़ा फाटक।**\n\n## तीन कड़ियाँ — कैसे जुड़ती हैं\n**Facebook Page** — दुकान की सार्वजनिक पहचान, जैसे बोर्ड लगी दुकान। **Instagram Professional खाता** (Business या Creator) — फ़ोटो-वीडियो से बिक्री का मंच, युवा ग्राहकों तक पहुँच। **WhatsApp Business** (खंड 3-6) — सीधी बातचीत का मंच। तीनों को Meta Business Suite/Business Manager में एक \"Business Portfolio\" के भीतर जोड़ने पर — एक कैटलॉग तीनों जगह दिखता है (पाठ-87), एक ही dashboard से संदेश-कमेंट जवाब दिए जा सकते हैं, और विज्ञापन (खंड-93 आगे) तीनों पर एक साथ चलाए जा सकते हैं। यह जुड़ाव अलग-अलग खाते बनाने से नहीं, बल्कि \"Connect\" या \"Link accounts\" जैसे विकल्प से होता है — असली खाते (नंबर, नाम) वही रहते हैं, सिर्फ़ प्रबंधन एक जगह से।\n\n## Instagram Professional खाता — दो तरह\nBusiness खाता — दुकान/ब्रांड के लिए, insights (आँकड़े) पूरे, कैटलॉग-tag (पाठ-91), Ads चलाने की पूरी सुविधा। Creator खाता — व्यक्तिगत रचनाकार के लिए, कुछ सुविधाएँ अलग। दुकान के लिए Business खाता सही चुनाव। सादे व्यक्तिगत Instagram-खाते को \"Professional\" में बदलना मुफ़्त और कुछ मिनट का काम — सेटिंग में \"Switch to Professional Account\" चुनें, श्रेणी (जैसे \"Clothing store\") भरें, Facebook Page से जोड़ें।\n\n## पिछली मेहनत का दोबारा उपयोग\nयहीं इस खंड की सबसे बड़ी बचत है। पाठ-14-17 की उत्पाद-फ़ोटो, पाठ-33 की मास्टर-शीट, पाठ-32 की Business-प्रोफ़ाइल जानकारी (दुकान का नाम, पता, समय) — यह सब Facebook Page और Instagram पर लगभग जस-का-तस उपयोग होता है, नई मेहनत नहीं। सिर्फ़ फ़ोटो-अनुपात Instagram के लिए थोड़ा अलग हो सकता है (पाठ-17 के मंच-वार मानक याद कीजिए — चौकोर या 4:5 अनुपात Instagram पर बेहतर दिखता है, WhatsApp कैटलॉग के मुक़ाबले)।\n\n## तीन घरों की ज़िम्मेदारी-सूची\nBusiness Suite जुड़ने के बाद रोज़ का काम तीन जगह बँटता है — **Page:** समय-समय पर दुकान की सूचना/त्योहार-post, Page-रिव्यू का जवाब। **Instagram:** उत्पाद-फ़ोटो/Reels (पाठ-90), Stories, DM का जवाब (पाठ-91)। **WhatsApp:** वही रोज़ की बातचीत (खंड 3-6)। तीनों एक ही Business Suite inbox में दिख सकते हैं — यानी सुबह एक जगह खोलकर तीनों के अनुत्तरित संदेश देखे जा सकते हैं, तीन अलग ऐप खोलने की झंझट नहीं।\n\n## सेवा-सहायक की आँख\n\"तीनों खाते जोड़ना + Business Suite सेटअप + पहली फ़ोटो-post\" एक सादी शुरुआती सेवा है — दुकानदार को अक्सर पता ही नहीं होता कि उसका WhatsApp और Instagram जोड़े जा सकते हैं। यह पाठ आपकी अगली सेवा का पहला दरवाज़ा खोलता है।\n\n## चित्र — एक घर, तीन खिड़कियाँ\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta Business Suite — एक घर, तीन खिड़कियाँ</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">Page + Instagram + WhatsApp एक dashboard से</text>\n<rect x=\"240\" y=\"115\" width=\"320\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"150\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta Business Suite</text>\n<text x=\"400\" y=\"180\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">एक कैटलॉग · एक inbox · एक विज्ञापन-केंद्र</text>\n<line x1=\"300\" y1=\"205\" x2=\"150\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"400\" y1=\"205\" x2=\"400\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"500\" y1=\"205\" x2=\"650\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<g font-size=\"17\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"270\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"150\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\">Facebook Page</text><text x=\"60\" y=\"340\">सार्वजनिक पहचान</text><text x=\"60\" y=\"368\">post-रिव्यू</text>\n<rect x=\"290\" y=\"270\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"400\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">Instagram Pro</text><text x=\"310\" y=\"340\">फ़ोटो-Reels</text><text x=\"310\" y=\"368\">Stories-DM</text>\n<rect x=\"540\" y=\"270\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"650\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">WhatsApp Business</text><text x=\"560\" y=\"340\">रोज़ की बातचीत</text><text x=\"560\" y=\"368\">खंड 3-6</text>\n</g>\n<rect x=\"60\" y=\"460\" width=\"680\" height=\"160\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"495\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">पिछली मेहनत का दोबारा उपयोग</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"530\">उत्पाद-फ़ोटो (पाठ 14-17) → लगभग जस-की-तस</text>\n<text x=\"90\" y=\"562\">मास्टर-शीट (पाठ-33) → कैटलॉग-आधार</text>\n<text x=\"90\" y=\"594\">प्रोफ़ाइल-जानकारी (पाठ-32) → नाम-पता-समय</text>\n</g>\n<rect x=\"60\" y=\"640\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"675\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">Instagram-अनुपात अलग — चौकोर/4:5, WhatsApp-कैटलॉग से थोड़ा भिन्न</text>\n<text x=\"400\" y=\"708\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">बाक़ी सब — दोहराई मेहनत नहीं</text>\n</svg>\n```\n\n## एक असली दुकान का उदाहरण\nमान लो खगड़िया की एक हस्तशिल्प-दुकान — अब तक सिर्फ़ WhatsApp पर चलती थी, ग्राहक ज़्यादातर आस-पास के गाँवों से। दुकानदार की बेटी, जो पढ़ाई के साथ यह कोर्स कर रही है, तीनों खाते Business Suite में जोड़ती है। पहले हफ़्ते में तीन काम — Facebook Page पर दुकान की तीन पुरानी असली फ़ोटो लगाईं (Google Images से नहीं, अपनी दुकान की), Instagram-खाता Professional में बदला और श्रेणी \"Handicraft store\" चुनी, और WhatsApp की मौजूदा प्रोफ़ाइल-जानकारी (पाठ-32) से Page की \"About\" जानकारी भरी — तीनों जगह एक ही सच। महीने भर बाद देखा तो Facebook से भी दो पूछताछ आईं, जिन्हें Business Suite के साझा inbox से WhatsApp पर आगे बढ़ाया गया। यही छोटा-सा शुरुआती काम आगे के पूरे खंड-7 की बुनियाद बनता है।\n\n## 3. आज का काम «काम-कार्ड»\nअगर आपके पास Facebook Page या Instagram-खाता है (या दुकान का), जाँचिए वह Business Suite में जुड़ा है या नहीं — न जुड़ा हो तो जोड़ने के तीन कदम काग़ज़ पर लिखिए (सादे खाते से Professional में बदलना, Page से जोड़ना, Business Manager में सेटअप)। पाठ-32 की Business-प्रोफ़ाइल और पाठ-17 की फ़ोटो-मानक सूची निकालिए — इनमें से क्या Instagram पर सीधे उपयोग हो सकता है, क्या बदलना पड़ेगा, लिखिए। जाँच-सूची: ☐ जोड़ने के तीन कदम ☐ Business बनाम Creator खाता का फ़र्क़ समझा ☐ पुरानी-सामग्री पुनः-उपयोग सूची ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — तीनों खाते जोड़ते समय एक ही बैठक में सब कुछ करने की कोशिश न करें; पहले Page-Instagram जोड़ें, एक-दो दिन देखें सब ठीक चल रहा है, फिर WhatsApp जोड़ें — छोटे कदम, कम उलझन।\n\n## 4. नाप\nसफल = तीन कदम सही क्रम में; पुनः-उपयोग सूची में कम-से-कम तीन चीज़ें (फ़ोटो, प्रोफ़ाइल, मास्टर-शीट)। समय: 25 मिनट।\n\n## 5. सबूत\nसबूत-खाते में \"Business Suite जोड़ने का पन्ना\"। यह पाठ-87 (कैटलॉग) के लिए सीधी नींव है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"WhatsApp Business, Facebook Page और Instagram Professional खाते को Meta Business Suite में एक साथ जोड़ने के कदम क्या हैं?\" — कदमों की तुलना अपनी सूची से कीजिए।\n\n## छोटे कदम का लंबा फ़ायदा\nएक बार तीनों खाते सही ढंग से जुड़ जाएँ, तो अगले महीनों में हर नई सुविधा (कैटलॉग, विज्ञापन, Reels-बिक्री) बिना दोबारा-जोड़ने की झंझट के अपने-आप उपलब्ध हो जाती है — यही इस पहले पाठ की छोटी मेहनत का बड़ा फ़ायदा है, ठीक वैसे ही जैसे खंड-1 में दस्तावेज़-तैयारी (पाठ-7) पूरे कोर्स में बार-बार काम आई।\n\n## 7. आम ग़लती\nपहली — तीनों के लिए अलग-अलग नई जानकारी टाइप करना, जबकि पुरानी मेहनत (खंड-2/खंड-3) पहले से तैयार है। दूसरी — व्यक्तिगत Instagram-खाते को बिना Professional में बदले सीधे बिक्री शुरू करना — कैटलॉग-tag जैसी सुविधाएँ नहीं मिलतीं। तीसरी — Business या Creator में उलझन — दुकान के लिए हमेशा Business। चौथी — तीनों जोड़ने के बाद कभी एक-साथ inbox न देखना — जोड़ने का फ़ायदा तभी जब उपयोग हो।\n\nअगर दुकान में किसी भी नाबालिग सदस्य को सोशल-मीडिया-प्रबंधन में मदद करनी हो, तो असली खाता-नियंत्रण अभिभावक के नाम पर ही रहे — यह पाठ-8 के नाबालिग-सुरक्षा नियम की सीधी कड़ी है।\n\n## 8. सुरक्षा-पत्रक\nBusiness Manager/Suite का नियंत्रण दुकान-मालिक के नाम व email पर; सेवा-सहायक को सिर्फ़ ज़रूरी भूमिका (Editor/Admin जैसा, पूरा मालिकाना नहीं)। दो-कदम-सत्यापन चालू (पाठ-10)। नाबालिग विद्यार्थी असली दुकान-खाता न बनाएँ, अभ्यास-मोड में समझें।\n\nअगला पाठ-87 इसी जुड़ाव पर सीधे खड़ा है — बिना खाते जुड़े कैटलॉग किसी काम का नहीं, इसलिए इस छोटे-से पाठ को छोड़कर आगे न बढ़ें।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Business Suite/Business Manager सहायता — https://www.facebook.com/business/help/2199267443725583 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=unified-business-account-setup · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Business Suite को एक वाक्य में समझा सकता हूँ।\n- [ ] मैं Business बनाम Creator खाते का फ़र्क़ जानता हूँ।\n- [ ] मैंने जोड़ने के तीन कदम लिखे हैं।\n- [ ] मैंने पुनः-उपयोग की जा सकने वाली सामग्री सूचीबद्ध की है।\n- [ ] मैं जानता हूँ यह पाठ-87 की नींव क्यों है।",
 "87": "═\n# पाठ-87: Commerce Manager कैटलॉग — एक कैटलॉग, तीन जगह\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nBusiness Suite जुड़ गया; अब असली उत्पाद-सूची आती है — Commerce Manager कैटलॉग। पाठ के बाद आप तीन बातें कर पाएँगे — Commerce Manager कैटलॉग का काम समझ पाएँगे; इसे पाठ-33 की WhatsApp-कैटलॉग और पाठ-18 के Product Data Feed से जोड़ पाएँगे; और एक कैटलॉग को WhatsApp, Facebook, Instagram तीनों पर दिखा पाएँगे।\n\n## 2. मुख्य बात\nपाठ-33 में हमने WhatsApp Business ऐप का कैटलॉग बनाया था — वह छोटी दुकान के लिए फ़ोन से सीधे बनता है। एक-वाक्य बात — **Commerce Manager Meta का बड़ा कैटलॉग-इंजन है — यहाँ एक बार उत्पाद-सूची डालने पर वही सूची WhatsApp, Facebook Shop और Instagram Shop तीनों जगह अपने-आप दिखती है, अलग-अलग तीन बार बनाने की ज़रूरत नहीं।**\n\n## दो रास्ते — छोटी दुकान बनाम बढ़ती दुकान\nपाठ-33 का ऐप-कैटलॉग — हाथ से, एक-एक उत्पाद, फ़ोन से; 5-10 उत्पाद वाली दुकान के लिए काफ़ी। Commerce Manager — बड़ी सूची (50, 200, 1,000 उत्पाद) के लिए बना; उत्पाद एक साथ (bulk) जोड़े जा सकते हैं, और सबसे बड़ा फ़ायदा — यही एक कैटलॉग WhatsApp Business Platform (Cloud API से जुड़ी दुकान), Facebook Shop, और Instagram Shop तीनों से जुड़ता है। यानी पाठ-18 के Product Data Feed (जो हमने GST-तकनीकी-नींव में शुरू किया था) का असली उपयोग यहीं शुरू होता है — वही मास्टर-शीट अब एक बड़ी फ़ाइल (CSV/spreadsheet) के रूप में Commerce Manager में upload होती है।\n\n## कैटलॉग बनाने के तीन तरीक़े\n**1. हाथ से (Manual):** Commerce Manager में एक-एक उत्पाद जोड़ें — फ़ोटो, नाम, दाम, विवरण। छोटी सूची के लिए सीधा। **2. डेटा-फ़ीड (Data Feed):** एक spreadsheet (CSV/XML) बनाकर upload करें — हर पंक्ति एक उत्पाद, तय column-नाम (id, title, price, image_link जैसे)। यह पाठ-18 का सीधा अमल — अगर मास्टर-शीट सही ढाँचे में है, तो upload कुछ मिनट का काम। **3. e-commerce platform-जुड़ाव (अगर हो):** अगर दुकान की अपनी website Shopify जैसे platform पर है, तो वहाँ से सीधे स्वचालित जुड़ाव संभव — यह छोटी दुकान के लिए फ़िलहाल कम प्रासंगिक।\n\n## एक कैटलॉग, तीन जगह — कैसे दिखता है\nकैटलॉग तैयार होने पर — WhatsApp पर ग्राहक कैटलॉग-कड़ी खोलेगा तो वही उत्पाद दिखेंगे (पाठ-35 जैसे, पर बड़े पैमाने पर); Facebook Shop बनाने पर (पाठ-88) यही कैटलॉग दुकान का \"पन्ना\" बनेगा; Instagram पर product-tag (पाठ-91) इसी कैटलॉग से जुड़ेगा। एक जगह दाम या स्टॉक बदलने पर तीनों जगह अपने-आप बदल जाता है — यही \"एक चीज़ = एक जगह\" सिद्धांत (Constitution का मूल नियम) का Meta-स्तर पर रूप।\n\n## कैटलॉग-गुणवत्ता — चार जाँच\n1. हर उत्पाद की फ़ोटो साफ़, तय अनुपात में (पाठ-17)। 2. दाम और स्टॉक हमेशा सही — बिका हुआ उत्पाद \"उपलब्ध\" न दिखे, ग्राहक-निराशा से बचाव। 3. श्रेणी (category) सही चुनी गई — Meta ग़लत श्रेणी वाले उत्पाद को खोज में नीचे दिखाता है। 4. विवरण में कोई गढ़ा दावा नहीं (पाठ-16 का नियम यहाँ भी)। कैटलॉग की गुणवत्ता ख़राब होने पर Meta सूचना और checkout दोनों पर असर डालता है, ठीक जैसे Amazon/Flipkart में कमज़ोर लिस्टिंग नीचे दबती है (आगे खंड-9-10 में विस्तार)।\n\n## सेवा-सहायक की आँख\n\"मास्टर-शीट को Commerce Manager-फ़ाइल में बदलना + पहला upload + तीन जगह जाँच\" एक तकनीकी सेवा है जो दुकानदार अकेले शायद ही करे। पाठ-18 की Product Data Feed समझ यहाँ सीधे पैसे में बदलती है।\n\n## चित्र — एक कैटलॉग, तीन खिड़कियों में\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Commerce Manager — एक कैटलॉग, तीन जगह</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">मास्टर-शीट (पाठ-18/33) → डेटा-फ़ीड → तीनों मंच</text>\n<rect x=\"290\" y=\"115\" width=\"220\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"150\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">Commerce Manager</text>\n<text x=\"400\" y=\"180\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">कैटलॉग-इंजन</text>\n<line x1=\"330\" y1=\"205\" x2=\"150\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"400\" y1=\"205\" x2=\"400\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"470\" y1=\"205\" x2=\"650\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"270\" width=\"220\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"150\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">WhatsApp</text><text x=\"60\" y=\"340\">कैटलॉग-कड़ी</text><text x=\"60\" y=\"365\">carousel (पाठ-81)</text>\n<rect x=\"290\" y=\"270\" width=\"220\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"400\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\">Facebook Shop</text><text x=\"310\" y=\"340\">Page पर दुकान</text><text x=\"310\" y=\"365\">(पाठ-88)</text>\n<rect x=\"540\" y=\"270\" width=\"220\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"650\" y=\"305\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">Instagram Shop</text><text x=\"560\" y=\"340\">product-tag</text><text x=\"560\" y=\"365\">(पाठ-91)</text>\n</g>\n<rect x=\"60\" y=\"420\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"455\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">तीन बनाने के तरीक़े</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"490\">1. हाथ से — छोटी सूची, एक-एक उत्पाद</text>\n<text x=\"90\" y=\"522\">2. डेटा-फ़ीड — spreadsheet upload, बड़ी सूची (पाठ-18 का अमल)</text>\n<text x=\"90\" y=\"550\">3. platform-जुड़ाव — अपनी website हो तो स्वचालित</text>\n</g>\n<rect x=\"60\" y=\"590\" width=\"680\" height=\"140\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"625\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">कैटलॉग-गुणवत्ता — चार जाँच</text>\n<text x=\"400\" y=\"658\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">साफ़ फ़ोटो · सही दाम-स्टॉक · सही श्रेणी · कोई गढ़ा दावा नहीं</text>\n<text x=\"400\" y=\"690\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">एक जगह बदलो → तीनों जगह बदले</text>\n</svg>\n```\n\n## data-फ़ीड की एक झलक — असल में कैसा दिखता है\nसमझने के लिए एक छोटी झलक — मान लो मास्टर-शीट में एक साड़ी है। data-फ़ीड की एक पंक्ति ऐसी दिखेगी — id: SD-12, title: \"सूती साड़ी — नीला, हाथ-बुनाई\", price: \"₹800 INR\", image_link: (फ़ोटो की सीधी कड़ी), availability: \"in stock\", category: \"Women's Clothing > Sarees\"। ग़ौर कीजिए — price में मुद्रा-कोड (INR) साथ चाहिए, availability सिर्फ़ तय शब्दों में (\"in stock\" या \"out of stock\", अपने शब्दों में नहीं), category Meta की अपनी सूची से चुनी हुई। यही बारीकियाँ हैं जो \"अपलोड फेल क्यों हुआ\" के सबसे आम कारण बनती हैं — इसलिए पहला upload हमेशा पाँच-दस उत्पादों के छोटे नमूने से करें, पूरी सूची से नहीं, ताकि ग़लती जल्दी पकड़ में आए और सुधार आसान रहे।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी मास्टर-शीट (पाठ-33) के पाँच उत्पाद लीजिए और उन्हें Commerce Manager-style डेटा-फ़ीड के column-ढाँचे में लिखिए (id, title, price, image_link, availability, category — छह column, एक तालिका)। कैटलॉग-गुणवत्ता की चार जाँच अपनी सूची पर लगाइए — कोई कमी मिले तो लिखिए। नीचे लिखिए — यह कैटलॉग किन तीन जगह दिखेगा, इसका क्या फ़ायदा है। जाँच-सूची: ☐ पाँच उत्पादों की छह-column तालिका ☐ चार गुणवत्ता-जाँच लगाई ☐ तीन-जगह फ़ायदा लिखा ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — data-फ़ीड की फ़ाइल का एक नाम रखें और तारीख़ जोड़ते रहें (जैसे feed-अगस्त-2026), ताकि पुरानी-नई फ़ाइल में उलझन न हो और कभी ग़लत पुरानी फ़ाइल दोबारा upload न हो जाए।\n\n## 4. नाप\nसफल = तालिका के सारे column भरे, कोई ख़ाली/गढ़ा data नहीं; गुणवत्ता-जाँच ईमानदार। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में \"Commerce Manager डेटा-फ़ीड नमूना\"। पाठ-88 (Shop बनाना) में यही फ़ीड उपयोग होगा।\n\nएक याद रखने वाली बात — availability का field हमेशा तय अंग्रेज़ी शब्दों में भरा जाता है ('in stock'/'out of stock'), हिंदी अनुवाद या अपने शब्दों में लिखने पर सिस्टम उसे पढ़ नहीं पाता, इसलिए इस एक field में तकनीकी साँचा हूबहू रखना ज़रूरी है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Meta Commerce Manager के लिए product data feed का column-ढाँचा (id, title, price आदि) क्या है?\" — जवाब मिलाइए अपनी छह-column तालिका से; असली column-नाम Meta की मदद-कड़ी से पक्का कीजिए, AI से नहीं।\n\n## छोटी दुकान का असली अनुभव\nएक तीस-उत्पाद वाली किराना-सहायक दुकान का अनुभव — पहले हाथ से 30 बार फ़ोटो-दाम भरने में एक पूरा दिन लगा, फिर उसी दुकान ने डेटा-फ़ीड सीखा और अगली बार 25 नए उत्पाद सिर्फ़ 40 मिनट में जोड़ दिए, क्योंकि spreadsheet में सिर्फ़ नई पंक्तियाँ जोड़नी थीं, पुराना ढाँचा पहले से बना था। यही फ़र्क़ है जो सेवा-सहायक को शुरू में सिखाना चाहिए — पहला दिन धीमा, पर एक बार ढाँचा बन जाए तो हर अगला उत्पाद जोड़ना मिनटों का काम।\n\n## 7. आम ग़लती\nपहली — WhatsApp-कैटलॉग (पाठ-33) और Commerce Manager कैटलॉग को दो अलग चीज़ समझकर दोनों में अलग-अलग data भरना — छोटी दुकान के लिए एक ही काफ़ी। दूसरी — डेटा-फ़ीड में column-नाम ग़लत लिखना, जिससे upload फेल होता है। तीसरी — स्टॉक ख़त्म होने पर कैटलॉग अपडेट न करना — ग्राहक बिका उत्पाद देखकर मँगाता है, निराश होता है। चौथी — बिना श्रेणी सोचे-समझे भरना — ग़लत श्रेणी खोज में उत्पाद दबा देती है।\n\n## 8. सुरक्षा-पत्रक\nकैटलॉग में दाम/उपलब्धता हमेशा असली — नक़ली \"स्टॉक में सिर्फ़ 2 बचे\" जैसा दबाव-दावा न लिखें, यह झूठा-दावा है। कैटलॉग-प्रबंधन का अधिकार सिर्फ़ भरोसेमंद कर्मचारी को, ताकि दाम में ग़लत बदलाव न हो।\n\nआगे पाठ-88 में यही कैटलॉग असली दुकान-पन्ने में बदलेगा, इसलिए इस पाठ का नमूना-अभ्यास पूरी लगन से कीजिए, वरना अगला पाठ अधूरा लगेगा।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Commerce Manager दस्तावेज़ — https://www.facebook.com/business/help/964318664062082 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=multi-channel-catalog-management · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Commerce Manager का काम एक वाक्य में बता सकता हूँ।\n- [ ] मैं तीन बनाने के तरीक़ों में फ़र्क़ जानता हूँ।\n- [ ] मैंने छह-column डेटा-फ़ीड तालिका बनाई है।\n- [ ] मैं चार गुणवत्ता-जाँच बिना देखे गिना सकता हूँ।\n- [ ] मैं जानता हूँ एक कैटलॉग तीन जगह क्यों दिखता है।",
 "88": "═\n# पाठ-88: Shop बनाना व checkout-विकल्प — भारत में क्या चलता\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nकैटलॉग तैयार है; अब असली \"दुकान का पन्ना\" — Facebook/Instagram Shop। पाठ के बाद आप तीन बातें कर पाएँगे — Shop बनाने के कदम बता पाएँगे; भारत में उपलब्ध checkout-विकल्पों (ग्राहक कैसे भुगतान/ऑर्डर पूरा करता है) को पहचान पाएँगे; और सही checkout-रास्ता चुन पाएँगे।\n\n## 2. मुख्य बात\nCommerce Manager (पाठ-87) सिर्फ़ पीछे का इंजन है; Shop वह सामने की दुकान है जो ग्राहक देखता और उससे ख़रीदता है। एक-वाक्य बात — **Shop बनाने के बाद ग्राहक Facebook Page या Instagram Profile पर सीधे \"Shop\" टैब देखकर उत्पाद ब्राउज़ कर सकता है — पर आख़िरी क़दम (checkout) कहाँ होगा, यह देश और सेटिंग से तय होता है, और भारत में यह अक्सर बदलता रहा है।**\n\n## Shop बनाने के कदम\n1. Commerce Manager में कैटलॉग तैयार (पाठ-87)। 2. \"Create Shop\" चुनें, Business Portfolio और Page/Instagram जोड़ें। 3. Shop की दिखावट (theme, रंग, cover) सेट करें — यहाँ पाठ-32 के Business-प्रोफ़ाइल-रंग और लोगो उपयोग कीजिए, दुकान की एक पहचान बनी रहे। 4. checkout-विकल्प चुनें (नीचे विस्तार)। 5. Meta की समीक्षा (review) — कुछ दिन लग सकते हैं; Shop चालू होने पर सूचना आती है।\n\n## checkout-विकल्प — तीन रास्ते, भारत के संदर्भ में\n**1. Website checkout:** ग्राहक Shop से उत्पाद देखकर, \"Buy\" दबाकर, दुकान की अपनी website पर जाकर भुगतान पूरा करता है। यह उन दुकानों के लिए जिनकी अपनी e-commerce website है। **2. Message to buy (चैट से ख़रीद):** ग्राहक \"Buy\" दबाए तो WhatsApp या Instagram DM में चैट खुलती है, वहीं से बातचीत और भुगतान (खंड-3/6 की सारी सीख यहीं काम आती है) — छोटी भारतीय दुकान के लिए यह सबसे व्यावहारिक और आम रास्ता। **3. सीधा in-app checkout:** ग्राहक Facebook/Instagram के भीतर ही पूरा भुगतान करे, बिना कहीं और जाए — यह सुविधा दुनिया के कुछ हिस्सों में उपलब्ध रही है, पर भारत में इसकी उपलब्धता और नियम बार-बार बदले हैं (Δ) — Shop बनाते समय Meta का सहायता-पन्ना ज़रूर जाँचें, यह पाठ पुराना दिख सकता है।\n\n## भारत के लिए ईमानदार सलाह\nजब तक Meta की मदद-कड़ी साफ़ \"in-app checkout भारत में उपलब्ध\" न कहे, छोटी-मंझोली भारतीय दुकान के लिए **\"Message to buy\"** ही सबसे भरोसेमंद रास्ता है — यह हमारे खंड 3-6 के पूरे WhatsApp-ढाँचे का सीधा उपयोग करता है, अलग से कुछ नया सीखना नहीं पड़ता। अगर दुकान के पास अपनी website है, तो Website checkout दूसरा अच्छा विकल्प। in-app checkout को \"भविष्य में देखेंगे\" के डिब्बे में रखिए, जब तक साफ़ पुष्टि न मिले।\n\n## Shop बनाम कैटलॉग-कड़ी — कब कौन\nपाठ-35 की कैटलॉग-कड़ी सिर्फ़ WhatsApp के भीतर काम करती है। Shop व्यापक है — Facebook Page और Instagram Profile दोनों पर एक \"दुकान\" जैसा अनुभव देता है, जिसे कोई भी बिना WhatsApp खोले, सिर्फ़ Page/Profile देखकर ब्राउज़ कर सकता है। दोनों साथ चल सकते हैं — Shop से browse करके checkout WhatsApp पर आ जाए, यही सबसे आम भारतीय रास्ता।\n\n## सेवा-सहायक की आँख\n\"Shop-सेटअप + सही checkout-विकल्प चुनना + दिखावट (theme) सेट करना\" एक अच्छी शुरुआती सेवा है। ईमानदारी से बताइए कि in-app checkout अभी भरोसेमंद नहीं — यह ग़लत उम्मीद देने से बेहतर है।\n\n## चित्र — Shop व तीन checkout-रास्ते\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Shop बनाना — checkout के तीन रास्ते</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">भारत में \"Message to buy\" सबसे भरोसेमंद</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"150\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">Website checkout</text><text x=\"60\" y=\"190\">अपनी website हो तो</text><text x=\"60\" y=\"216\">वहीं भुगतान पूरा</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><text x=\"400\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">Message to buy</text><text x=\"310\" y=\"190\">WhatsApp/DM में</text><text x=\"310\" y=\"216\">चैट से पूरा</text><text x=\"310\" y=\"242\" font-weight=\"bold\">✓ भारत में सबसे भरोसेमंद</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"650\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">in-app checkout</text><text x=\"560\" y=\"190\">app के भीतर ही</text><text x=\"560\" y=\"216\">भारत में Δ — जाँचें</text>\n</g>\n<rect x=\"60\" y=\"310\" width=\"680\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"345\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">Shop बनाने के पाँच कदम</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"380\">1. कैटलॉग तैयार (पाठ-87)</text>\n<text x=\"90\" y=\"410\">2. Create Shop, Page/Instagram जोड़ें</text>\n<text x=\"90\" y=\"440\">3. दिखावट सेट करें (रंग-लोगो, पाठ-32 से)</text>\n<text x=\"90\" y=\"470\">4. checkout-विकल्प चुनें → 5. Meta-समीक्षा</text>\n</g>\n<rect x=\"60\" y=\"510\" width=\"680\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"545\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">Shop बनाम कैटलॉग-कड़ी</text>\n<text x=\"400\" y=\"580\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">कैटलॉग-कड़ी = सिर्फ़ WhatsApp · Shop = Page+Instagram पर व्यापक</text>\n<text x=\"400\" y=\"608\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">दोनों साथ — Shop से browse, WhatsApp पर checkout</text>\n<rect x=\"60\" y=\"650\" width=\"680\" height=\"80\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"695\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta के मदद-पन्ने से भारत की ताज़ा स्थिति जाँचें — यह Δ-पाठ है</text>\n</svg>\n```\n\n## एक निर्णय-कहानी — website है या नहीं\nमान लो दो दुकानें। पहली — पटना की मसाला-कंपनी, जिसकी अपनी website पहले से है (शायद किसी और सेवा के लिए बनवाई गई थी)। इसके लिए Website checkout सही — Shop से ग्राहक सीधे website पर जाकर भुगतान करे, जहाँ पहले से payment-gateway (पाठ-62) जुड़ा है। दूसरी — खगड़िया की हस्तशिल्प-दुकान, जिसकी कोई website नहीं और बनवाने का न बजट है न ज़रूरत। इसके लिए Message to buy सही — Shop सिर्फ़ \"दिखाने की खिड़की\" बने, असली बातचीत-भुगतान वहीं जहाँ पहले से मज़बूत ढाँचा है, यानी WhatsApp। यह फ़ैसला-कहानी दिखाती है कि \"सही checkout\" कोई एक जवाब नहीं — यह हर दुकान की मौजूदा स्थिति से तय होता है, और यही सेवा-सहायक का काम है, दुकानदार को इस फ़ैसले तक पहुँचाना।\n\n## 3. आज का काम «काम-कार्ड»\nMeta की Commerce/Shops मदद-कड़ी (स्रोत में) खोलिए और भारत के लिए checkout-विकल्पों की ताज़ा स्थिति नोट कीजिए (तारीख़ सहित)। अपनी दुकान के लिए तय कीजिए — Website checkout या Message to buy, कारण सहित। Shop की दिखावट के लिए तीन चीज़ें चुनिए (cover-फ़ोटो, रंग, पहला दिखने वाला संदेश)। जाँच-सूची: ☐ भारत की ताज़ा checkout-स्थिति तारीख़ सहित ☐ अपना चुनाव कारण सहित ☐ Shop-दिखावट तीन चीज़ें ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — Shop की मंज़ूरी में कुछ दिन लगने पर घबराएँ नहीं; तब तक WhatsApp-कैटलॉग (पाठ-33) और carousel (पाठ-81) से बिक्री सामान्य रूप से चलती रहे, Shop सिर्फ़ एक अतिरिक्त द्वार है, अकेला सहारा नहीं।\n\n## 4. नाप\nसफल = checkout-चुनाव Meta की असली मदद-कड़ी से पुष्ट, अंदाज़े से नहीं। समय: 25 मिनट।\n\nयह पन्ना दिखाता है कि आपने सिर्फ़ default सेटिंग नहीं छोड़ी, बल्कि हर विकल्प को समझकर एक ठोस फ़ैसला लिया — यही फ़र्क़ एक साधारण सेटअप और एक सोची-समझी सेवा के बीच होता है।\n\n## 5. सबूत\nसबूत-खाते में \"Shop-सेटअप पन्ना व checkout-फ़ैसला\"। पाठ-89 (Marketplace) के लिए यह पन्ना संदर्भ रहेगा।\n\ncheckout-विकल्प की जानकारी ख़ासतौर से जल्दी बासी होती है, इसलिए हर बार Shop बनाने से पहले ताज़ा जाँच अनिवार्य मानिए, भले पहले किसी दूसरी दुकान में यह सेटअप किया हो।\n\n## 6. AI-सहायक\nAI से पूछिए — \"भारत में Facebook/Instagram Shop पर checkout के कौन-से विकल्प उपलब्ध हैं?\" — AI का जवाब पुराना हो सकता है (Δ-विषय); हमेशा Meta के आधिकारिक पन्ने से मिलाइए।\n\n## 7. आम ग़लती\nपहली — in-app checkout को \"पक्का उपलब्ध है\" मानकर सेटअप में समय गँवाना, जबकि भारत में स्थिति अलग हो सकती है। दूसरी — Shop की दिखावट बिना सोचे डिफ़ॉल्ट छोड़ देना — दुकान की पहचान (रंग, लोगो) ग़ायब रहती है। तीसरी — Shop बनाते ही तुरंत उपयोग शुरू करना, बिना Meta की समीक्षा-मंज़ूरी का इंतज़ार किए। चौथी — कैटलॉग (पाठ-87) पुराना/अधूरा होते हुए Shop बना देना — पहले कैटलॉग सही करें।\n\n## एक और सावधानी — पहला महीना धीरे\nShop चालू होने के पहले महीने बहुत ज़्यादा उत्पाद और बहुत ज़्यादा विज्ञापन एक साथ न डालें — दस-पंद्रह भरोसेमंद उत्पाद से शुरू करें, ग्राहक-प्रतिक्रिया देखें, फिर बढ़ाएँ। यह वही \"धीमा-पर-पक्का\" सिद्धांत है जो पाठ-81 में carousel के लिए और पाठ-75 में BSP-चुनाव के लिए दोहराया गया — नई तकनीक को धीरे अपनाना हर बार कम ग़लती लाता है।\n\n## 8. सुरक्षा-पत्रक\ncheckout चाहे कहीं भी हो, भुगतान-पुष्टि की जाँच वही नियम (पाठ-81 का \"रसीद देखकर ही आगे बढ़ें\")। website checkout चुनें तो website असली और सुरक्षित (https) होनी चाहिए, नक़ली-सी दिखने वाली website ग्राहक-भरोसा तोड़ती है।\n\nअगला पाठ-89 इसी दुकान को Facebook Marketplace से जोड़ेगा, जो एक बिल्कुल अलग और मुफ़्त बिक्री-रास्ता है — Shop की मेहनत उधर भी बहुत काम आएगी।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। checkout-विकल्प व उपलब्धता भारत में बार-बार बदली है — यह पाठ पुराना हो सकता है, ताज़ा जानकारी मदद-कड़ी से लें। 📎 मूल-कोर्स-कड़ी: Meta Facebook/Instagram Shops सहायता — https://www.facebook.com/business/help/2531102423779330 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=shop-setup-and-checkout-choice · platform=meta · level=S · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Shop बनाने के पाँच कदम बता सकता हूँ।\n- [ ] मैं तीन checkout-विकल्पों में फ़र्क़ जानता हूँ।\n- [ ] मैं जानता हूँ भारत के लिए कौन-सा रास्ता सबसे भरोसेमंद है।\n- [ ] मैंने अपनी दुकान का checkout-फ़ैसला कारण सहित लिखा है।\n- [ ] मैं जानता हूँ यह Δ-पाठ है, ताज़ा जानकारी ज़रूरी है।",
 "89": "═\n# पाठ-89: Facebook Marketplace — मुफ़्त स्थानीय बिक्री\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nShop (पाठ-88) एक \"स्थायी दुकान\" थी; आज एक बिल्कुल अलग औज़ार — Facebook Marketplace, जहाँ बिना विज्ञापन-ख़र्च के अपने इलाके के ग्राहकों तक पहुँचा जा सकता है। पाठ के बाद आप तीन बातें कर पाएँगे — Marketplace और Shop का फ़र्क़ बता पाएँगे; अपने इलाके के लिए एक असरदार Marketplace-listing बना पाएँगे; और यह समझ पाएँगे कि यह किन उत्पादों के लिए सबसे उपयोगी है।\n\n## 2. मुख्य बात\nShop दुकान का स्थायी पन्ना है, जहाँ ग्राहक ख़ुद ढूँढकर आता है। एक-वाक्य बात — **Marketplace एक स्थानीय बाज़ार-चौक जैसा है — आपकी listing आस-पास के लोगों को अपने-आप, बिना विज्ञापन-ख़र्च के, \"क्या बिक रहा है\" खोजते समय दिखती है, ख़ासकर उन उत्पादों के लिए जो लोग नज़दीक से ख़रीदना पसंद करते हैं।**\n\n## Marketplace किसके लिए सबसे उपयोगी\nभारी/बड़ा सामान जिसे भेजना महँगा हो — फर्नीचर, बड़े बर्तन, साइकिल-मरम्मत जैसी सेवाएँ। दूसरे-हाथ (used) सामान — पुराने कपड़े, किताबें, इलेक्ट्रॉनिक्स। स्थानीय सेवाएँ — टेलरिंग, मरम्मत, ट्यूशन, जिनका ग्राहक हमेशा आस-पास का होता है। यह Amazon/Flipkart जैसे राष्ट्रीय-मंच से अलग सोच है — वहाँ दूर के ग्राहक तक पहुँचना मक़सद, यहाँ नज़दीक के ग्राहक को जल्दी और सस्ते में पाना मक़सद। छोटे उद्यमी के लिए यह अक्सर सबसे पहला मुफ़्त द्वार होता है, क्योंकि इसमें कोई सूची-शुल्क या कमीशन नहीं (सामान्य बिक्री के लिए)।\n\n## listing बनाना — पाँच ज़रूरी हिस्से\n1. **साफ़ फ़ोटो** — असली उत्पाद की, कई कोण से (पाठ-14 के पाँच-कोण नियम यहाँ भी)। 2. **सच्चा शीर्षक** — \"साइकिल, हीरो, एक साल पुरानी, अच्छी हालत\" जैसा साफ़ नाम, बढ़ा-चढ़ाकर नहीं। 3. **सही दाम** — आस-पास के दूसरे विक्रेताओं की listing देखकर तुलनात्मक दाम रखें। 4. **इलाका (location)** — सही पिन-कोड/इलाका ताकि नज़दीक के लोगों को दिखे। 5. **श्रेणी** — सही श्रेणी चुनना ज़रूरी, वरना ग़लत खोज में दबी रहेगी।\n\n## Marketplace पर सुरक्षा — ख़ास सावधानी\nMarketplace पर मिलना-जुलना अक्सर आमने-सामने होता है (सामान देने-लेने), इसलिए सुरक्षा-नियम थोड़े अलग। सार्वजनिक, दिन के उजाले वाली जगह चुनें — दुकान, बाज़ार, या भीड़-भाड़ वाला इलाका, कभी सुनसान जगह नहीं। भुगतान पहले या मिलते ही, नक़द या UPI से तुरंत लें — \"बाद में भेज दूँगा\" वाले वादों से बचें (यह पाठ-70 के COD-धोखे जैसा ही जोखिम है)। नाबालिग विद्यार्थी अकेले किसी अजनबी से मिलने न जाएँ — यह हमेशा किसी बड़े/अभिभावक के साथ हो।\n\n## Marketplace से WhatsApp की ओर\nजैसे Shop से checkout WhatsApp पर जा सकता है (पाठ-88), Marketplace की बातचीत भी अक्सर Facebook Messenger में शुरू होकर WhatsApp पर बढ़ती है — अपनी listing में \"WhatsApp पर बात करें\" जैसा एक-पंक्ति निर्देश दे सकते हैं (अपना नंबर सीधे listing में न लिखें, यह नीति-भंग हो सकता है — सिर्फ़ Messenger में पूछे जाने पर सादगी से दें)।\n\n## सेवा-सहायक की आँख\n\"पाँच Marketplace-listing बनाना, हर हफ़्ते ताज़ा करना\" एक सादी, कम-तकनीकी सेवा है — नए सेवा-सहायकों के लिए एक अच्छा शुरुआती काम, क्योंकि इसमें BSP या Commerce Manager जैसी जटिलता नहीं।\n\n## चित्र — Shop बनाम Marketplace\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Facebook Marketplace — स्थानीय बाज़ार-चौक</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बिना विज्ञापन-ख़र्च, नज़दीक के ग्राहक तक</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"115\" width=\"330\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"205\" y=\"150\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">Shop (पाठ-88)</text>\n<text x=\"60\" y=\"185\">स्थायी दुकान-पन्ना</text><text x=\"60\" y=\"212\">दूर के ग्राहक भी</text><text x=\"60\" y=\"239\">कैटलॉग-आधारित</text>\n<rect x=\"430\" y=\"115\" width=\"330\" height=\"150\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"595\" y=\"150\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">Marketplace</text>\n<text x=\"450\" y=\"185\">स्थानीय बाज़ार-चौक</text><text x=\"450\" y=\"212\">नज़दीक का ग्राहक</text><text x=\"450\" y=\"239\">भारी/used सामान बेहतर</text>\n</g>\n<rect x=\"60\" y=\"300\" width=\"680\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"335\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">listing के पाँच ज़रूरी हिस्से</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"370\">साफ़ फ़ोटो · सच्चा शीर्षक · तुलनात्मक दाम</text>\n<text x=\"90\" y=\"400\">सही इलाका (पिन-कोड) · सही श्रेणी</text>\n</g>\n<rect x=\"60\" y=\"500\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"535\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">सुरक्षा — आमने-सामने मिलना</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"568\">सार्वजनिक, दिन के उजाले वाली जगह</text>\n<text x=\"90\" y=\"596\">भुगतान पहले/मिलते ही, नक़द या UPI</text>\n<text x=\"90\" y=\"624\">नाबालिग अकेले न मिलें — बड़े के साथ</text>\n</g>\n<rect x=\"60\" y=\"670\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"713\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"bold\" fill=\"#0B1F3A\">Messenger-बातचीत WhatsApp पर बढ़ सकती है — नंबर listing में सीधे नहीं</text>\n</svg>\n```\n\n## एक असली उदाहरण — पुराने फर्नीचर की बिक्री\nमान लो खगड़िया के एक बढ़ई-सहायक के पास कुछ हल्का इस्तेमाल किया लकड़ी का पलंग बिक्री के लिए है — इसे Amazon या Flipkart पर भेजना नामुमकिन-सा है, भाड़ा ही सामान से ज़्यादा लगेगा। यहीं Marketplace सबसे उपयुक्त है — साफ़ चार फ़ोटो (सामने, बग़ल, कोई ख़राबी हो तो वह भी ईमानदारी से दिखाई), शीर्षक \"लकड़ी का पलंग, सागौन, दो साल पुराना, हल्की खरोंच\", दाम आस-पास के दो-तीन similar listing देखकर तय किया, इलाका अपने मोहल्ले का नाम। पहले तीन दिन में पाँच पूछताछ आईं, जिनमें से दो ने Messenger पर पूछा तो जवाब में सादगी से WhatsApp-नंबर साझा किया गया — वहीं आगे बात बढ़ी और सौदा तय हुआ। इस पूरे लेन-देन में एक रुपया भी विज्ञापन पर ख़र्च नहीं हुआ — यही Marketplace की असली ताक़त है, ख़ासकर उस सामान के लिए जो दूर भेजने लायक़ नहीं।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी दुकान (या इलाके) के लिए दो Marketplace-योग्य उत्पाद चुनिए (भारी सामान, used सामान, या स्थानीय सेवा में से)। हर एक का पूरा listing-मसौदा लिखिए — शीर्षक, दाम (तुलना करके), इलाका, श्रेणी। सुरक्षा-नियमों की एक-पंक्ति सूची भी साथ लिखिए जो आप ग्राहक-मिलन में अपनाएँगे। जाँच-सूची: ☐ दो listing-मसौदे पाँचों हिस्सों सहित ☐ तुलनात्मक दाम-जाँच ☐ सुरक्षा-नियम सूची ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — पहली listing डालने के बाद हफ़्ते में एक बार खोलकर देखें कि कहीं किसी ने 'मार्क अस सोल्ड' (बिक गया चिह्न) लगाना भूल तो नहीं गए — बिका हुआ सामान लंबे समय listing में दिखते रहना नए पूछताछ-संदेशों की बर्बादी है।\n\n## 4. नाप\nसफल = शीर्षक सच्चे व साफ़, दाम आस-पास के अनुरूप, कोई बढ़ा-चढ़ाया दावा नहीं। समय: 25 मिनट।\n\nअगर कुछ हफ़्तों बाद इन दो listing के नतीजे (कितनी पूछताछ, कितनी बिकीं) भी दर्ज करें, तो यह पन्ना पोर्टफ़ोलियो में एक सिद्ध-नतीजे वाली सेवा बन जाएगा, सिर्फ़ मसौदा नहीं।\n\n## 5. सबूत\nसबूत-खाते में \"Marketplace-listing मसौदा\"। यह पोर्टफ़ोलियो में एक सादी शुरुआती सेवा के नमूने के रूप में जा सकता है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Facebook Marketplace पर (उत्पाद) की listing के लिए एक अच्छा, सच्चा शीर्षक और छोटा विवरण लिखो।\" — दाम AI से न लें, आस-पास की असली listing से तुलना करें।\n\n## Marketplace और दुकान की छवि\nकुछ विक्रेता Marketplace को \"सस्ते-में-निबटाने\" की जगह मानकर वहाँ ख़राब फ़ोटो और लापरवाह भाषा उपयोग करते हैं, यह सोचकर कि \"यहाँ कोई ज़्यादा ध्यान नहीं देता\"। असल में कई ग्राहक पहली बार आपकी दुकान से Marketplace के ज़रिए ही मिलते हैं, इसलिए यहाँ भी वही सफ़ाई और ईमानदारी चाहिए जो Shop या WhatsApp-कैटलॉग में रखी जाती है। एक अच्छा Marketplace-अनुभव अक्सर ग्राहक को आपके WhatsApp या Instagram तक ले आता है, जहाँ वह नियमित ग्राहक बन सकता है — यानी यह सिर्फ़ एक बार की बिक्री का औज़ार नहीं, नए रिश्तों की शुरुआत भी है।\n\n## 7. आम ग़लती\nपहली — पुरानी/धुंधली फ़ोटो लगाना — Marketplace पर फ़ोटो ही पहला भरोसा है। दूसरी — दाम बहुत ज़्यादा रखकर फिर मोल-भाव में बहुत नीचे आना — शुरू से ईमानदार दाम बेहतर। तीसरी — ग़लत/दूर का इलाका डालना — नज़दीक का ग्राहक ही नहीं दिखेगा। चौथी — सुनसान जगह पर मिलने जाना या भुगतान से पहले सामान दे देना।\n\nबड़े या भारी सामान के लिए मिलन-स्थल दुकान या कोई पुलिस-चौकी के नज़दीक की जगह चुनना अतिरिक्त सुरक्षा देता है, ख़ासकर अगर पहली बार किसी अनजान ग्राहक से मिल रहे हों।\n\n## 8. सुरक्षा-पत्रक\nअपना घर का पूरा पता कभी सार्वजनिक listing में न लिखें — सिर्फ़ इलाका/मोहल्ला काफ़ी है, मिलने की जगह बातचीत में तय करें। पहली मुलाक़ात हमेशा सार्वजनिक जगह। नाबालिग विद्यार्थी बिना अभिभावक के कभी सामान देने-लेने न जाएँ।\n\nआगे पाठ-90 में हम Reel के ज़रिए और गहराई से बिक्री-प्रचार सीखेंगे, जो Marketplace-listing के साथ मिलकर पहुँच को और बड़ा बनाएगा।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Facebook Marketplace सहायता — https://www.facebook.com/help/889075504467874 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=local-marketplace-listing · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Marketplace और Shop का फ़र्क़ बता सकता हूँ।\n- [ ] मैं जानता हूँ किन उत्पादों के लिए यह सबसे उपयोगी है।\n- [ ] मैंने दो listing-मसौदे पाँचों हिस्सों सहित बनाए हैं।\n- [ ] मैं आमने-सामने मिलन की सुरक्षा-सावधानियाँ जानता हूँ।\n- [ ] मैं जानता हूँ नंबर सीधे listing में क्यों नहीं लिखना।",
 "90": "═\n# पाठ-90: Reels-पहले बिक्री — 30-सेकंड उत्पाद-वीडियो\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\n2026 में Instagram-Facebook पर सबसे ज़्यादा देखा जाने वाला रूप वीडियो है, फ़ोटो नहीं। पाठ के बाद आप तीन बातें कर पाएँगे — Reels क्या है और यह क्यों ज़्यादा लोगों तक पहुँचता है, समझ पाएँगे; मोबाइल से एक सादा 30-सेकंड उत्पाद-Reel बना पाएँगे; और Reels को बिक्री से जोड़ने का तरीक़ा सीख पाएँगे।\n\n## 2. मुख्य बात\nपाठ-14-17 में हमने उत्पाद की स्थिर (still) फ़ोटो बनाई थी। एक-वाक्य बात — **Reel एक छोटा, 15-60 सेकंड का वीडियो है जिसे Instagram-Facebook का एल्गोरिद्म फ़ॉलोअर्स से बाहर भी नए लोगों तक फैलाता है — यानी बिना विज्ञापन-ख़र्च के भी सही Reel हज़ारों नए लोगों तक पहुँच सकता है, जो स्थिर फ़ोटो के साथ आमतौर पर नहीं होता।**\n\n## Reel क्यों फ़ोटो से अलग असर करता है\nInstagram-Facebook का \"Explore/Reels\" पन्ना नए लोगों को नई चीज़ें दिखाने के लिए बना है — वहाँ आपकी दुकान के फ़ॉलोअर्स न होने पर भी Reel दिखाया जा सकता है, अगर वह दिलचस्प हो। यह \"मुफ़्त पहुँच\" की सबसे बड़ी खिड़की है जो 2026 में किसी छोटी दुकान के पास है — बशर्ते Reel सही ढंग से बनाया जाए। स्थिर फ़ोटो अक्सर सिर्फ़ मौजूदा फ़ॉलोअर्स तक सीमित रहती है।\n\n## 30-सेकंड उत्पाद-Reel — सादा ढाँचा\n**पहले 3 सेकंड (सबसे ज़रूरी) —** कुछ ऐसा दिखे जो देखने वाले को रोक दे — उत्पाद बनते हुए, या \"पहले-बाद\" जैसा दृश्य, या एक साफ़ सवाल-वाक्य टेक्स्ट में (\"यह साड़ी सिर्फ़ ₹800 में?\")। **बीच के 15-20 सेकंड —** उत्पाद का असली उपयोग/फ़ायदा दिखाएँ — कपड़ा पहनकर घूमना, खाना बनते हुए, यंत्र चलते हुए। कोई लंबा भाषण नहीं, ज़्यादातर दृश्य ही बोलें। **आख़िरी 5-10 सेकंड —** साफ़ बुलावा (call-to-action) — \"WhatsApp पर पूछें\", \"कैटलॉग देखें\", दाम टेक्स्ट में साफ़ दिखे।\n\n## मोबाइल से बनाना — कोई महँगा उपकरण नहीं चाहिए\nअच्छी रोशनी (खिड़की के पास, दिन का समय — पाठ-14 वाली ही सलाह), फ़ोन को स्थिर रखना (हाथ से या सस्ते stand से), और Instagram/Reels के अंदर के मुफ़्त औज़ार — background music, टेक्स्ट, थोड़ा गति-तेज़/धीमा करना। महँगा कैमरा या editing-software ज़रूरी नहीं; असली, साफ़, ईमानदार वीडियो सबसे ज़्यादा भरोसा जीतता है, चमक-दमक नहीं।\n\n## Reels को बिक्री से जोड़ना\nReel के caption (नीचे लिखा टेक्स्ट) में उत्पाद-नाम, दाम, और \"WhatsApp पर पूछें (कड़ी)\" जोड़ें। Reel में उत्पाद को tag भी किया जा सकता है अगर कैटलॉग (पाठ-87) तैयार हो — तब देखने वाला सीधे उत्पाद-पन्ने पर जा सकता है (पाठ-91 में इसका विस्तार)। सप्ताह में दो-तीन Reel से ज़्यादा पहले महीने में न बनाएँ — गुणवत्ता मात्रा से बेहतर, ख़ासकर शुरुआत में जब सीख रहे हों।\n\n## सेवा-सहायक की आँख\n\"महीने में आठ Reel बनाना, caption व दाम सहित\" एक बढ़िया दोहराई सेवा है, ख़ासकर उन दुकानदारों के लिए जिन्हें वीडियो बनाना अजीब लगता है। पहला Reel साथ बैठकर बनाइए, दिखाइए कि यह उतना मुश्किल नहीं जितना लगता है।\n\n## चित्र — 30-सेकंड Reel का ढाँचा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">30-सेकंड उत्पाद-Reel — सादा ढाँचा</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बिना विज्ञापन-ख़र्च, नए लोगों तक फैलने की खिड़की</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\">0-3 सेकंड</text>\n<text x=\"150\" y=\"185\" text-anchor=\"middle\">रोकने वाला दृश्य</text>\n<text x=\"150\" y=\"215\" text-anchor=\"middle\">या साफ़ सवाल-टेक्स्ट</text>\n<text x=\"150\" y=\"260\" text-anchor=\"middle\" font-weight=\"bold\">सबसे ज़रूरी!</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#1565C0\">3-20 सेकंड</text>\n<text x=\"400\" y=\"185\" text-anchor=\"middle\">असली उपयोग/फ़ायदा</text>\n<text x=\"400\" y=\"215\" text-anchor=\"middle\">दृश्य बोलें, भाषण नहीं</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"650\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#2E7D32\">20-30 सेकंड</text>\n<text x=\"650\" y=\"185\" text-anchor=\"middle\">साफ़ बुलावा</text>\n<text x=\"650\" y=\"215\" text-anchor=\"middle\">\"WhatsApp पर पूछें\"</text>\n<text x=\"650\" y=\"245\" text-anchor=\"middle\">दाम टेक्स्ट में साफ़</text>\n</g>\n<rect x=\"60\" y=\"330\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"365\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">कोई महँगा उपकरण नहीं चाहिए</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"400\">खिड़की के पास, दिन का समय (पाठ-14 जैसे)</text>\n<text x=\"90\" y=\"430\">फ़ोन स्थिर, ऐप के मुफ़्त औज़ार (music, टेक्स्ट)</text>\n<text x=\"90\" y=\"458\">असली-साफ़-ईमानदार सबसे ज़्यादा भरोसा जीतता है</text>\n</g>\n<rect x=\"60\" y=\"500\" width=\"680\" height=\"120\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"540\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">हफ़्ते में दो-तीन Reel — गुणवत्ता, मात्रा नहीं</text>\n<text x=\"400\" y=\"575\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">caption में दाम + WhatsApp-कड़ी + उत्पाद-tag (पाठ-91)</text>\n</svg>\n```\n\n## एक कमज़ोर बनाम मज़बूत Reel — फ़र्क़ समझिए\nकमज़ोर Reel — दुकानदार सीधे कैमरे के सामने खड़ा होकर एक मिनट तक साड़ी के बारे में बोलता रहता है, कोई दृश्य-बदलाव नहीं, पहले 3 सेकंड में सिर्फ़ \"नमस्ते\" — देखने वाला तुरंत आगे स्क्रॉल कर देता है। मज़बूत Reel — पहले सेकंड में साड़ी की चमकीली बुनाई का क़रीबी दृश्य, फिर एक मॉडल या ग्राहक साड़ी पहनकर घूमती दिखे, हल्का संगीत, नीचे बड़े टेक्स्ट में \"₹800 — आज ही मँगाएँ\", आख़िर में WhatsApp-आइकन के साथ \"यहाँ पूछें\"। दोनों Reel एक ही उत्पाद के, एक ही फ़ोन से बने, पर एक रुका हुआ ध्यान खींचता है, दूसरा नहीं। फ़र्क़ महँगे उपकरण का नहीं, ढाँचे को समझने का है — यही इस पाठ की सबसे बड़ी सीख।\n\n## 3. आज का काम «काम-कार्ड»\nअपने किसी एक उत्पाद के लिए 30-सेकंड Reel की पूरी पटकथा (script) लिखिए — 0-3 सेकंड में क्या दिखेगा, 3-20 में क्या, 20-30 में कौन-सा बुलावा-वाक्य। संभव हो तो असली मोबाइल से यह Reel बनाइए (न बन सके तो सिर्फ़ पटकथा काफ़ी)। caption का पूरा टेक्स्ट लिखिए — उत्पाद-नाम, दाम, WhatsApp-कड़ी। जाँच-सूची: ☐ तीन-हिस्सों की पटकथा ☐ बुलावा-वाक्य साफ़ ☐ caption पूरा लिखा ☐ फ़ोटो/वीडियो सबूत-खाते में।\n\nव्यावहारिक टिप — पहला Reel बनाने के बाद उसे ख़ुद देखिए, बिना आवाज़ के — अगर सिर्फ़ दृश्य देखकर भी समझ आ जाए कि उत्पाद क्या है और दाम क्या है, तो Reel सफल माना जा सकता है, क्योंकि बहुत-से लोग बिना आवाज़ चालू किए वीडियो देखते हैं।\n\n## 4. नाप\nसफल = पहले 3 सेकंड में सचमुच कुछ रोकने वाला हो; बुलावा साफ़, दाम छुपा न हो। समय: 30 मिनट (शूट अलग समय)।\n\nअगर असली Reel बना और post किया, तो एक हफ़्ते बाद उसकी views/reach (कितने लोगों तक पहुँचा) की संख्या भी नोट करें — यही आगे पाठ-99 के 'नतीजा पढ़ना' पाठ में तुलना के काम आएगी।\n\n## 5. सबूत\nसबूत-खाते में \"Reel-पटकथा व caption\"। यह पाठ-98 (AI से विज्ञापन-रचना) में एक साँचे के रूप में फिर काम आएगा।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरे (उत्पाद) के लिए 30-सेकंड Reel की पटकथा लिखो — पहले 3 सेकंड में ध्यान खींचने वाला दृश्य हो।\" — मसौदा लीजिए, पर हर दावा अपने असली उत्पाद से जाँचें, गढ़ा हुआ फ़ायदा न लिखें।\n\n## शुरुआती डर पर एक बात\nबहुत-से दुकानदार कैमरे के सामने आने से हिचकते हैं — यह स्वाभाविक है। अच्छी बात यह है कि Reel में दुकानदार का चेहरा दिखना ज़रूरी नहीं; उत्पाद, हाथ, या दुकान का माहौल भी बहुत असरदार हो सकता है। मान लो चूड़ी बनाने वाला कारीगर सिर्फ़ अपने हाथों से चूड़ी बनते हुए दिखाए, कोई चेहरा नहीं, फिर भी यह वीडियो बहुत असली और भरोसेमंद लगता है। सेवा-सहायक को शुरुआत में यही सुझाव देना चाहिए — पहले उत्पाद-केंद्रित Reel से शुरू करें, दुकानदार का आत्मविश्वास बढ़े तो धीरे-धीरे चेहरा भी जोड़ें, जल्दबाज़ी की ज़रूरत नहीं।\n\n## 7. आम ग़लती\nपहली — पहले 3 सेकंड को साधारण रखना (\"नमस्ते दोस्तों\") — देखने वाला वहीं आगे बढ़ जाता है (स्क्रॉल कर देता है)। दूसरी — पूरा वीडियो सिर्फ़ भाषण, कोई असली दृश्य नहीं। तीसरी — दाम कहीं न लिखना — ग्राहक पूछने की मेहनत नहीं करता। चौथी — रोज़ Reel बनाने की जल्दी में गुणवत्ता गिरा देना।\n\nवीडियो शूट करते समय आस-पास किसी और की निजी संपत्ति या चेहरा बिना अनुमति न दिखाएँ, चाहे वह गली का दृश्य ही क्यों न हो — सार्वजनिक जगह पर भी सम्मान का ध्यान रखें।\n\n## 8. सुरक्षा-पत्रक\nReel में कोई नाबालिग चेहरा बिना अभिभावक-सहमति न दिखाएँ (पाठ-8 का नियम)। संगीत सिर्फ़ ऐप के मुफ़्त/लाइसेंस-प्राप्त औज़ार से — कॉपीराइट-गाने से समस्या हो सकती है। कोई भी दावा जो उत्पाद सच में नहीं करता, वीडियो में न दिखाएँ।\n\nअगला पाठ-91 इसी Reel को product-tag से जोड़कर सीधी बिक्री में बदलने का तरीक़ा सिखाएगा — दोनों पाठ मिलकर पूरा असर बनाते हैं।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। Reels-एल्गोरिद्म की प्राथमिकताएँ बदलती रहती हैं। 📎 मूल-कोर्स-कड़ी: Instagram/Facebook Reels के लिए Business गाइड — https://business.instagram.com/getting-started — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=short-video-product-marketing · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Reel और स्थिर फ़ोटो में फ़र्क़ बता सकता हूँ।\n- [ ] मैं 30-सेकंड ढाँचे के तीन हिस्से जानता हूँ।\n- [ ] मैंने एक Reel की पटकथा व caption लिखा है।\n- [ ] मैं जानता हूँ पहले 3 सेकंड सबसे ज़रूरी क्यों हैं।\n- [ ] मैं जानता हूँ हफ़्ते में कितने Reel बनाने चाहिए।\n\n══════════════════════════════════════════════════यह पूरा खंड-7 का सफ़र यहीं मज़बूत होता है — Reel-Instagram-DM की ज़ंजीर तैयार होते ही, अगले पाठ में हम उसी दिशा में Meta Ads की भुगतान-दुनिया में क़दम रखेंगे।",
 "91": "═\n# पाठ-91: Product-tag व Instagram DM बिक्री\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nReel (पाठ-90) ने ध्यान खींचा; अब उस ध्यान को असली बिक्री में बदलने के दो औज़ार — product-tag और Instagram DM। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी Instagram-post/Reel पर उत्पाद-tag जोड़ पाएँगे; DM (सीधा संदेश) से आने वाली पूछताछ को सही तरीक़े से सँभाल पाएँगे; और Instagram-बिक्री को WhatsApp-प्रवाह से जोड़ पाएँगे।\n\n## 2. मुख्य बात\nपाठ-87 का कैटलॉग सिर्फ़ Shop-पन्ने पर बैठा रह जाए तो अधूरा फ़ायदा है। एक-वाक्य बात — **product-tag से आप किसी भी फ़ोटो या Reel पर सीधे कैटलॉग के उत्पाद को \"चिपका\" सकते हैं — देखने वाला उस दाग़ (छोटे बिंदु) पर टैप करे तो सीधे उत्पाद-जानकारी और \"पूछें\" का रास्ता खुल जाता है।**\n\n## product-tag कैसे लगाएँ\npost या Reel डालते समय \"Tag Products\" विकल्प चुनें, कैटलॉग (पाठ-87) से वह उत्पाद खोजें, फ़ोटो पर सही जगह टैप करें (जहाँ उत्पाद दिख रहा हो)। एक post में कई उत्पाद भी tag किए जा सकते हैं (जैसे पूरी शेल्फ़ की फ़ोटो में हर वस्तु अलग-अलग tag)। यह पाठ-81 के carousel जैसा ही सोच है, पर WhatsApp की जगह Instagram पर।\n\n## Instagram DM — बिक्री की दूसरी शुरुआत\nReel/post देखकर बहुत से ग्राहक कमेंट की जगह सीधे DM (Direct Message) करते हैं — \"यह कितने का है?\", \"साइज़ उपलब्ध है?\"। यहीं वही सोच काम आती है जो हमने WhatsApp के लिए सीखी — साफ़ स्वागत, जल्दी जवाब, कैटलॉग-कड़ी भेजना। कुछ फ़र्क़ हैं — Instagram DM में opt-in/24-घंटे-खिड़की जैसी सख़्ती फ़िलहाल WhatsApp जितनी नहीं, पर शालीनता और स्पष्टता वही नियम। पाठ-57 में हमने Instagram DM Agent की झलक देखी थी — यहाँ हम मानवीय/हाथ से जवाब देने की बात कर रहे हैं, अगर अभी तक Agent चालू न किया हो।\n\n## Instagram से WhatsApp की ओर — पुल बनाना\nकई ग्राहक Instagram पर देखकर, पर ख़रीदने के लिए WhatsApp पर बात करना पसंद करते हैं (ज़्यादा भरोसे और पुराने ढंग की बातचीत के लिए)। Instagram Bio (प्रोफ़ाइल के ऊपर का छोटा विवरण) में WhatsApp-कड़ी डालें, और DM के जवाब में भी \"पूरी बात WhatsApp पर करें (कड़ी)\" का विकल्प दें, ताकि पूरा ऑर्डर-प्रवाह (carousel, Flows, भुगतान — खंड-6) दोहराने की ज़रूरत न पड़े। यानी Instagram \"आकर्षण\" का काम करे, WhatsApp \"लेन-देन\" का — यही सबसे व्यावहारिक बँटवारा।\n\n## comment बनाम DM — कब क्या\nकोई सार्वजनिक comment में \"दाम?\" पूछे तो सार्वजनिक जवाब में सीधे दाम मत लिखें (कई विक्रेता ऐसा करते हैं और नक़ली प्रतिस्पर्धियों/धोखेबाज़ों को मौक़ा मिल जाता है) — बेहतर तरीक़ा \"DM किया, वहाँ जवाब दिया\" जैसा सार्वजनिक उत्तर, और असली दाम DM में। इससे privacy और सुरक्षा दोनों बचते हैं।\n\n## सेवा-सहायक की आँख\n\"हर post/Reel पर सही product-tag लगाना + DM का जवाब-समय हफ़्ते में जाँचना\" एक निरंतर, दिखने वाला काम है — DM-जवाब में देरी सीधे बिक्री गँवाती है, इसलिए यह सेवा आसानी से नाप में आती है (\"औसत जवाब-समय X घंटे से Y घंटे हुआ\")।\n\n## चित्र — post से DM से WhatsApp तक\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">product-tag व Instagram DM — बिक्री का पुल</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">Instagram = आकर्षण · WhatsApp = लेन-देन</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"115\" width=\"220\" height=\"130\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><text x=\"150\" y=\"150\" text-anchor=\"middle\" font-weight=\"bold\">post/Reel</text><text x=\"60\" y=\"185\">product-tag लगा</text><text x=\"60\" y=\"210\">कैटलॉग से जुड़ा</text>\n<rect x=\"290\" y=\"115\" width=\"220\" height=\"130\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"400\" y=\"150\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">टैप → DM</text><text x=\"310\" y=\"185\">\"दाम? साइज़?\"</text><text x=\"310\" y=\"210\">जल्दी-शालीन जवाब</text>\n<rect x=\"540\" y=\"115\" width=\"220\" height=\"130\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"650\" y=\"150\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">WhatsApp</text><text x=\"560\" y=\"185\">पूरी बात/भुगतान</text><text x=\"560\" y=\"210\">खंड 3-6 का प्रवाह</text>\n</g>\n<line x1=\"260\" y1=\"180\" x2=\"290\" y2=\"180\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"510\" y1=\"180\" x2=\"540\" y2=\"180\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<rect x=\"60\" y=\"290\" width=\"680\" height=\"140\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"325\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">comment बनाम DM</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"360\">सार्वजनिक comment में सीधे दाम न लिखें</text>\n<text x=\"90\" y=\"390\">\"DM किया, वहाँ जवाब दिया\" — असली दाम DM में</text>\n</g>\n<rect x=\"60\" y=\"450\" width=\"680\" height=\"120\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"485\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">Bio में WhatsApp-कड़ी + DM-जवाब में WhatsApp-विकल्प</text>\n<text x=\"400\" y=\"520\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">ऑर्डर-प्रवाह दोहराने की ज़रूरत नहीं</text>\n<rect x=\"60\" y=\"590\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"633\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"bold\" fill=\"#2E7D32\">DM-जवाब-समय नापने योग्य सेवा — बिक्री सीधे इससे जुड़ी</text>\n</svg>\n```\n\n## एक पूरी बातचीत का नमूना\nकल्पना कीजिए — किसी ने Reel देखकर comment किया \"दाम?\"। सार्वजनिक जवाब सादा — \"नमस्ते! DM में जानकारी भेज दी है 🙂\"। फिर DM में असली जवाब — \"नमस्ते, यह साड़ी ₹800 की है, नीला रंग उपलब्ध है, चाहें तो और रंग भी दिखा सकते हैं। पूरी बातचीत WhatsApp पर करना चाहेंगे, जहाँ मैं फ़ोटो-कैटलॉग भी भेज सकती हूँ? (WhatsApp-कड़ी)\"। ग्राहक कड़ी दबाए तो सीधे WhatsApp चैट खुले, जहाँ carousel (पाठ-81), Flow (पाठ-80), भुगतान (खंड-5-6) का पूरा प्रवाह पहले से तैयार। इस तरह Instagram सिर्फ़ पहला परिचय देता है, असली दुकान का पूरा तंत्र WhatsApp पर टिका रहता है — कहीं भी दोहरी मेहनत नहीं।\n\n## 3. आज का काम «काम-कार्ड»\nअपने किसी post/Reel (या काल्पनिक नमूना) पर product-tag लगाने के कदम लिखिए। एक सार्वजनिक comment-सवाल (\"दाम बताइए\") का सही सार्वजनिक-जवाब और उसके बाद का असली DM-जवाब — दोनों लिखिए। अपना Instagram Bio का मसौदा लिखिए जिसमें WhatsApp-कड़ी शामिल हो। जाँच-सूची: ☐ tag लगाने के कदम ☐ comment व DM दोनों जवाब ☐ Bio-मसौदा WhatsApp-कड़ी सहित ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — DM-जवाब का एक साँचा (टेम्पलेट) पहले से तैयार रखें और सिर्फ़ उत्पाद-नाम-दाम बदलें, ताकि हर बार शुरू से टाइप न करना पड़े — यह वही सोच है जो पाठ-36 की Quick-reply में सीखी थी।\n\n## 4. नाप\nसफल = सार्वजनिक जवाब में दाम नहीं, DM में पूरा जवाब; Bio छोटा और साफ़। समय: 20 मिनट।\n\nयह नमूना दिखाता है कि सार्वजनिक-निजी जवाब का यह छोटा अनुशासन कितना असर करता है — इसे बार-बार अभ्यास में लाना ही इसे आदत बनाता है।\n\n## 5. सबूत\nसबूत-खाते में \"product-tag कदम व DM-जवाब नमूना\"। मासिक रख-रखाव (पाठ-102) में DM-जवाब-समय की जाँच जुड़ेगी।\n\nएक अतिरिक्त सुझाव — शुरुआत में हर DM को हाथ से पढ़कर जवाब दें, स्वचालित उत्तर (auto-reply) से बचें; ग्राहक को असली इंसान से बात करने का अहसास शुरुआती भरोसे में बहुत मायने रखता है, ख़ासकर छोटी दुकान के लिए जहाँ यह इंसानी जुड़ाव ही सबसे बड़ी ताक़त है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Instagram DM पर ग्राहक की पूछताछ का शालीन, जल्दी जवाब कैसे लिखूँ जो WhatsApp की ओर भी ले जाए?\" — जवाब को अपनी असली दुकान-भाषा में ढालिए।\n\nपाँचवीं — यह सोचना कि Instagram-बिक्री WhatsApp-बिक्री से अलग नियम चाहती है — असल में दोनों में ईमानदारी, स्पष्टता और सम्मान के मूल सिद्धांत एक जैसे रहते हैं, सिर्फ़ मंच का रूप बदलता है।\n\n## 7. आम ग़लती\nपहली — सार्वजनिक comment में सीधे दाम-फ़ोन-नंबर लिख देना — privacy और सुरक्षा का जोखिम। दूसरी — DM का जवाब देर से देना — ग्राहक तब तक दूसरी दुकान देख चुका होता है। तीसरी — product-tag बिल्कुल न लगाना — देखने वाले को पता ही नहीं चलता कि यह बिकाऊ है। चौथी — Bio में कड़ी बहुत लंबी/जटिल रखना — छोटी, साफ़ कड़ी बेहतर काम करती है।\n\nDM में कभी भी OTP, पासवर्ड, बैंक-विवरण न माँगें और न कभी दें — भले ग्राहक 'जल्दी भुगतान करना है' कहे, भुगतान हमेशा असली UPI/gateway से लें, DM में नंबर पूछकर नहीं।\n\nअगर कोई ग्राहक बार-बार अनुचित/अभद्र संदेश भेजे, तो उसे block करना और ज़रूरत हो तो Instagram को report करना पूरी तरह ठीक है — दुकान की गरिमा बनाए रखना भी सेवा-सहायक की ज़िम्मेदारी है।\n\n## 8. सुरक्षा-पत्रक\nDM में ग्राहक की निजी जानकारी (पता, फ़ोन) उतनी ही माँगें जितनी ऑर्डर-पूर्ति के लिए ज़रूरी। किसी अनजान DM में भेजी गई कड़ी पर ख़ुद न क्लिक करें — यह धोखे का आम तरीक़ा है (आपके ही खाते पर हमला हो सकता है)।\n\nआगे पाठ-92 में हम Broadcast Channel व Stories से नियमित ग्राहकों को जोड़े रखने का तरीक़ा सीखेंगे, जो DM-बातचीत के अलावा एक और भरोसे का पुल बनाता है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Instagram Shopping/Product Tags सहायता — https://help.instagram.com/1187859591568724 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=product-tagging-and-dm-conversion · platform=instagram · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं product-tag लगाने के कदम बता सकता हूँ।\n- [ ] मैं comment बनाम DM में जवाब का फ़र्क़ जानता हूँ।\n- [ ] मैंने Bio-मसौदा WhatsApp-कड़ी सहित बनाया है।\n- [ ] मैं जानता हूँ Instagram-WhatsApp का सही बँटवारा क्या है।\n- [ ] मैं DM-सुरक्षा (अनजान कड़ी न खोलना) समझता हूँ।",
 "92": "═\n# पाठ-92: Instagram Broadcast Channel व Stories-offer\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nअब तक हमने post, Reel, DM देखे — यह सब \"एक से एक\" या \"सार्वजनिक\" बातचीत थी। आज दो और औज़ार जो नियमित ग्राहकों को सीधे सूचना देते हैं। पाठ के बाद आप तीन बातें कर पाएँगे — Instagram Broadcast Channel का उपयोग समझ पाएँगे; Stories पर offer डालने का सही तरीक़ा सीख पाएँगे; और दोनों को WhatsApp Broadcast (पाठ-38) से जोड़कर देख पाएँगे।\n\n## 2. मुख्य बात\nपाठ-38 में हमने WhatsApp Broadcast देखा था — फ़ॉलोअर्स को एक साथ सूचना। एक-वाक्य बात — **Instagram Broadcast Channel भी वैसा ही है — एक-तरफ़ा सूचना-चैनल जहाँ आप फ़ॉलो करने वालों को नए उत्पाद, offer, या पीछे की झलक भेज सकते हैं, और Stories एक 24-घंटे की झलकी है जो त्योहार-offer के लिए एकदम सही है।**\n\n## Broadcast Channel — कैसे उपयोग करें\nChannel बनाने के बाद इसे follow करने वाले लोग आपके संदेश (text, फ़ोटो, poll) देखते हैं, पर वे सीधे जवाब नहीं दे सकते (सिर्फ़ emoji-प्रतिक्रिया) — यानी यह पूरी तरह \"सूचना\" के लिए है, बातचीत के लिए नहीं। इसका सबसे अच्छा उपयोग — नए उत्पाद की पहली झलक, स्टॉक-अपडेट (\"कल सुबह 10 बजे नई खेप\"), पीछे की कहानी (कैसे बनता है) — जो दुकान को इंसानी और भरोसेमंद बनाती है। ग्राहक अगर पूछना चाहे तो वह DM (पाठ-91) या WhatsApp से करेगा, Channel से नहीं।\n\n## Stories-offer — 24-घंटे की झलकी\nStories एक फ़ोटो/छोटा वीडियो है जो 24 घंटे बाद अपने-आप ग़ायब हो जाता है (जब तक \"Highlight\" में सुरक्षित न रखें)। यह अस्थायी-अहसास offer के लिए एकदम सही — \"आज ही, सिर्फ़ आज — 20% छूट\" जैसा संदेश Stories में स्वाभाविक लगता है, जबकि स्थायी post में यह अजीब लगेगा (post हमेशा दिखता रहता है, \"आज ही\" कहना बेमानी हो जाता है)। Stories में \"Link sticker\" या \"पूछें\" जैसे interactive औज़ार भी लगाए जा सकते हैं, जो सीधे DM या कड़ी की ओर ले जाते हैं।\n\n## Broadcast Channel बनाम Stories — कब कौन\nChannel — लंबे समय तक टिकने वाली सूचना, दस्तावेज़ीकृत रहती है, फ़ॉलोअर बाद में भी देख सकता है। Stories — तुरंत, अस्थायी, \"अभी\" की भावना वाला offer। दोनों साथ भी चल सकते हैं — Stories में offer की झलक, Channel में offer की पूरी जानकारी और अवधि। दोनों ही WhatsApp Broadcast की तरह — सिर्फ़ उन्हें भेजें जो सचमुच रुचि रखते हैं (Channel में follow करना ही एक तरह का opt-in है, इसलिए यह WhatsApp marketing-template जितना सख़्त नहीं, फिर भी बार-बार भेजने से लोग unfollow कर सकते हैं)।\n\n## तीनों मंच की सूचना-सीढ़ी — एक साथ देखना\nपूरे खंड-3 से खंड-7 तक हमने सूचना-भेजने के कई औज़ार देखे — WhatsApp Broadcast/Status (पाठ-38), Instagram Broadcast Channel व Stories (यह पाठ), और आगे Meta Ads (खंड-93 आगे) पूरी तरह भुगतान-आधारित पहुँच। यह एक सीढ़ी है — मुफ़्त-सूचना (Channel/Stories/Broadcast) → भुगतान-प्रचार (Ads)। छोटी दुकान को हमेशा मुफ़्त सीढ़ी पहले ठीक से भरनी चाहिए, तभी विज्ञापन का पैसा सार्थक होगा।\n\n## सेवा-सहायक की आँख\n\"हफ़्ते में एक Channel-संदेश + दो Stories-offer, त्योहार-कैलेंडर के साथ\" — यह छोटी, पर लगातार दिखने वाली सेवा है। एक साझा \"content-कैलेंडर\" (कौन-सा दिन क्या जाएगा) बनाकर दुकानदार को दिखाना आपकी योजना-क्षमता साबित करता है।\n\n## चित्र — Channel बनाम Stories, दो अलग काम\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Broadcast Channel व Stories-offer</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">एक-तरफ़ा सूचना — बातचीत के लिए DM/WhatsApp</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"200\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"205\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#1565C0\">Broadcast Channel</text>\n<text x=\"60\" y=\"190\">लंबे समय टिकने वाला</text><text x=\"60\" y=\"216\">नई-खेप, पीछे की कहानी</text><text x=\"60\" y=\"242\">फ़ॉलोअर बाद में भी देखे</text><text x=\"60\" y=\"280\" font-weight=\"bold\">= दस्तावेज़ीकृत सूचना</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"200\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"595\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">Stories-offer</text>\n<text x=\"450\" y=\"190\">24 घंटे में ग़ायब</text><text x=\"450\" y=\"216\">\"आज ही\" वाला offer</text><text x=\"450\" y=\"242\">Link sticker से पूछें</text>\n<text x=\"450\" y=\"280\" font-weight=\"bold\">= अस्थायी-अहसास</text>\n</g>\n<rect x=\"60\" y=\"360\" width=\"680\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"395\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">सूचना की सीढ़ी</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"430\">WhatsApp Broadcast/Status (पाठ-38)</text>\n<text x=\"90\" y=\"460\">+ Instagram Channel/Stories (यह पाठ)</text>\n<text x=\"90\" y=\"490\">= मुफ़्त सीढ़ी — पहले इसे भरें, फिर Ads (खंड आगे)</text>\n</g>\n<rect x=\"60\" y=\"570\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"605\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">follow करना ही एक तरह का opt-in है</text>\n<text x=\"400\" y=\"638\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">फिर भी बार-बार भेजने से लोग unfollow कर सकते हैं</text>\n<rect x=\"60\" y=\"680\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"723\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"bold\" fill=\"#0B1F3A\">content-कैलेंडर से हफ़्ते की योजना साफ़ रहती है</text>\n</svg>\n```\n\n## एक व्यावहारिक नमूना — त्योहार से पहले का हफ़्ता\nमान लो दीपावली से पहले का हफ़्ता। सोमवार — Stories में \"इस हफ़्ते नई खेप आ रही है, तैयार रहें!\" (जिज्ञासा जगाना)। बुधवार — Channel-संदेश, पूरी नई खेप की तीन फ़ोटो और दाम-सूची, साथ में \"पहले 20 ग्राहकों को विशेष दाम\" जैसी ईमानदार सूचना। शुक्रवार — Stories में \"आज शाम 6 बजे तक विशेष दाम, फिर सामान्य दाम\" (यह सच होना चाहिए, झूठा दबाव नहीं)। यह तीन-दिन का सादा कैलेंडर बिना किसी विज्ञापन-ख़र्च के त्योहार-सीज़न में ग्राहकों को व्यस्त और जागरूक रखता है — और यही आधार अगले खंड में Meta Ads से जुड़कर और बड़ा हो सकता है।\n\n## 3. आज का काम «काम-कार्ड»\nअगले हफ़्ते के लिए एक छोटा content-कैलेंडर बनाइए — कौन से दिन Channel-संदेश, कौन से दिन Stories-offer (कम-से-कम एक-एक)। हर एक का पूरा टेक्स्ट/विवरण लिखिए। नीचे लिखिए — Channel और Stories में क्या फ़र्क़ रखेंगे (एक ही बात दोनों जगह अलग ढंग से)। जाँच-सूची: ☐ हफ़्ते का content-कैलेंडर ☐ Channel-संदेश पूरा टेक्स्ट ☐ Stories-offer पूरा विवरण ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — content-कैलेंडर को महीने की शुरुआत में एक बार बना लें, फिर हर दिन सिर्फ़ उसे देखकर काम करें — रोज़ नए सिरे से सोचने में लगने वाला समय बहुत बचता है।\n\n## 4. नाप\nसफल = कैलेंडर व्यावहारिक (ज़्यादा नहीं, हफ़्ते में 2-3 संदेश); दोनों औज़ार अलग-अलग ढंग से उपयोग किए गए। समय: 25 मिनट।\n\nकैलेंडर को अगले महीने के लिए दोबारा बनाते समय पुराने महीने के नतीजे (कौन-सा संदेश ज़्यादा असर करता) देखकर सुधार जोड़ें — यही निरंतर बेहतरी का तरीक़ा है।\n\ncontent-कैलेंडर पन्ना पोर्टफ़ोलियो (खंड-24) में एक व्यवस्थित, दिखने वाली योजना-क्षमता के सबूत के रूप में शामिल किया जा सकता है।\n\n## 5. सबूत\nसबूत-खाते में \"Instagram content-कैलेंडर नमूना\"। यह मासिक रख-रखाव (पाठ-102) में दोहराया जाएगा।\n\nएक अतिरिक्त सुझाव — Channel-सदस्यों की संख्या हफ़्ते में एक बार देखें; अगर बहुत कम बढ़ रही है, तो अपने post/Reel के caption में Channel जुड़ने का निमंत्रण जोड़ें, यह एक सादा और मुफ़्त तरीक़ा है सदस्य बढ़ाने का।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Instagram Broadcast Channel और Stories का उपयोग एक छोटी दुकान के लिए कैसे अलग-अलग करना चाहिए?\" — जवाब अपने कैलेंडर से मिलाइए।\n\nपाँचवीं — Stories/Channel को दुकान की मुख्य बिक्री-रणनीति समझ लेना — यह सिर्फ़ सहायक औज़ार हैं, असली भारी काम अब भी कैटलॉग, WhatsApp और अच्छे उत्पाद से होता है।\n\n## 7. आम ग़लती\nपहली — Channel और Stories में एक ही तरह का संदेश भेजना, दोनों का अलग-अलग फ़ायदा न उठाना। दूसरी — रोज़ कई-कई Channel-संदेश भेजना — लोग unfollow कर देते हैं। तीसरी — Stories का \"आज ही\" वाला दबाव झूठा बनाना (offer असल में हफ़्तों चले) — भरोसा टूटता है। चौथी — Stories में offer डालकर Link sticker/पूछने का रास्ता न देना — ग्राहक अटक जाता है।\n\nStories/Channel में किसी और दुकान या प्रतियोगी की आलोचना न करें — यह न सिर्फ़ अनपेशेवर लगता है, बल्कि Meta की सामुदायिक-नीति के भी विरुद्ध हो सकता है।\n\nमासिक-रख-रखाव (पाठ-102) में Channel व Stories दोनों की समीक्षा का एक खाना जोड़ना चाहिए, ताकि यह मुफ़्त-सीढ़ी कभी अनदेखी न रहे।\n\n## 8. सुरक्षा-पत्रक\nStories/Channel में कोई ऐसा दावा न करें जो सच न हो — \"सिर्फ़ आज\" कहकर हफ़्तों चलाना धोखा है। ग्राहक की निजी जानकारी (जो DM में मिली हो) कभी Story/Channel में साझा न करें।\n\nखंड-7 का अगला हिस्सा (पाठ 93 से आगे) अब भुगतान-आधारित Meta Ads की दुनिया में प्रवेश करेगा, जहाँ यहाँ सीखी मुफ़्त-सूचना की समझ विज्ञापन-बजट को समझदारी से ख़र्च करने में मदद करेगी।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Instagram Broadcast Channels व Stories सहायता — https://help.instagram.com/700774627502426 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=broadcast-and-stories-engagement · platform=instagram · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Broadcast Channel व Stories में फ़र्क़ बता सकता हूँ।\n- [ ] मैं जानता हूँ \"आज ही\" वाला offer कहाँ सही बैठता है।\n- [ ] मैंने हफ़्ते का content-कैलेंडर बनाया है।\n- [ ] मैं मुफ़्त-सूचना-सीढ़ी और भुगतान-विज्ञापन का फ़र्क़ समझता हूँ।\n- [ ] मैं जानता हूँ ज़्यादा संदेश से unfollow क्यों होता है।",
 "93": "═\n# पाठ-93: Meta Ads मूल — उद्देश्य, बजट, दर्शक\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nमुफ़्त-सूचना की पूरी सीढ़ी (पाठ 86-92) अब तैयार है; आज से भुगतान-आधारित प्रचार — Meta Ads। पाठ के बाद आप तीन बातें कर पाएँगे — Meta Ads Manager के तीन बुनियादी हिस्सों (उद्देश्य, बजट, दर्शक) को समझ पाएँगे; अपनी दुकान के लिए पहला सादा विज्ञापन-ढाँचा बना पाएँगे; और यह तय कर पाएँगे कि विज्ञापन कब शुरू करना सही समय है।\n\n## 2. मुख्य बात\nपाठ-82 में विज्ञापन-से-चैट का पहला परिचय मिला था। एक-वाक्य बात — **हर Meta विज्ञापन तीन चीज़ों पर टिका है — उद्देश्य (आप क्या चाहते हैं), बजट (कितना ख़र्च करेंगे), और दर्शक (किसे दिखेगा) — तीनों सही मिलें तभी पैसा सार्थक ख़र्च होता है, अकेला एक भी सही न हो तो पैसा बर्बाद।**\n\n## उद्देश्य (Objective) — क्या चाहिए\nMeta Ads Manager सबसे पहले पूछता है \"आपका लक्ष्य क्या है\" — कुछ आम उद्देश्य: **पहुँच/जागरूकता** (ज़्यादा लोगों तक दुकान का नाम पहुँचे), **ट्रैफ़िक** (Shop/website पर लोग आएँ), **engagement** (post पर like-comment बढ़े), **लीड/संदेश** (WhatsApp/DM पर बातचीत शुरू हो — पाठ-82 का Click-to-WhatsApp यहीं आता है), **बिक्री/conversion** (कैटलॉग से सीधे ख़रीद)। छोटी दुकान के लिए अक्सर **लीड/संदेश** सबसे व्यावहारिक शुरुआत — क्योंकि इसका सीधा नतीजा (चैट शुरू हुई या नहीं) आसानी से गिना जा सकता है (पाठ-82 का attribution)।\n\n## बजट — दो तरीक़े, एक सिद्धांत\n**दैनिक बजट (Daily budget):** हर दिन एक तय राशि ख़र्च होगी, विज्ञापन लगातार चलता रहे। **कुल बजट (Lifetime budget):** पूरी अवधि के लिए एक तय राशि, Meta ख़ुद बाँटकर ख़र्च करता है — त्योहार जैसे तय-अवधि के campaign के लिए उपयुक्त। सिद्धांत एक ही — **कभी भी उतना बजट न डालें जिसका नुक़सान झेलने की स्थिति न हो।** पहला विज्ञापन हमेशा छोटे बजट से (मान लो ₹50-100 प्रतिदिन, कुछ दिन) — नतीजा देखकर बढ़ाएँ, यह पाठ-72 के Decision Lab वाली सतर्कता है।\n\n## दर्शक (Audience) — किसे दिखे\nतीन बुनियादी तरीक़े — **स्थान-आधारित** (अपने शहर/ज़िले के 10-20 किमी के दायरे में — छोटी स्थानीय दुकान के लिए अक्सर सबसे सही), **रुचि-आधारित** (जो लोग \"साड़ी\", \"हस्तशिल्प\" जैसी चीज़ों में रुचि दिखाते हैं — Meta के डेटा से), **उम्र-लिंग** (अगर उत्पाद किसी ख़ास समूह के लिए हो)। शुरुआत में दर्शक बहुत संकरा (5,000 से कम) या बहुत चौड़ा (पूरा देश) दोनों नुक़सानदेह — एक शहर/ज़िले के आकार का दर्शक (लाखों के आस-पास) आमतौर पर संतुलित शुरुआत।\n\n## विज्ञापन कब शुरू करना सही है — तीन शर्तें\n1. पाठ-86-92 का मुफ़्त-आधार तैयार हो (कैटलॉग, Business Suite, कुछ Reel/post) — विज्ञापन ख़ाली दुकान की ओर नहीं भेजना चाहिए। 2. unit-economics (पाठ-67) पता हो — यह जानना ज़रूरी है कि एक बिक्री पर कितना मुनाफ़ा बचता है, तभी विज्ञापन-बजट का सही अंदाज़ा लगेगा (पाठ-101 में विस्तार)। 3. attribution-रजिस्टर (पाठ-82) तैयार हो — बिना नापे विज्ञापन चलाना पैसा फेंकने जैसा है। तीनों शर्तें पूरी हों तभी पहला विज्ञापन बनाएँ।\n\n## सेवा-सहायक की आँख\n\"पहला Meta Ads campaign — उद्देश्य, बजट, दर्शक तीनों सोच-समझकर, छोटे बजट से शुरू\" एक बड़ी ज़िम्मेदारी वाली सेवा है, क्योंकि इसमें दुकानदार का असली पैसा लगता है। यहाँ आपकी ईमानदार सतर्कता (बड़ा बजट न डालना, नतीजा जाँचकर बढ़ाना) ही सबसे बड़ा भरोसा बनाती है।\n\n## चित्र — तीन खंभे, एक विज्ञापन\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta Ads — तीन खंभे</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">उद्देश्य + बजट + दर्शक — तीनों सही मिलें तभी असर</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">उद्देश्य</text>\n<text x=\"60\" y=\"190\">पहुँच · ट्रैफ़िक</text><text x=\"60\" y=\"216\">लीड/संदेश ✓</text><text x=\"60\" y=\"242\">बिक्री/conversion</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#1565C0\">बजट</text>\n<text x=\"310\" y=\"190\">दैनिक बनाम कुल</text><text x=\"310\" y=\"216\">छोटे से शुरू</text><text x=\"310\" y=\"242\">₹50-100/दिन</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"650\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">दर्शक</text>\n<text x=\"560\" y=\"190\">स्थान · रुचि</text><text x=\"560\" y=\"216\">उम्र-लिंग</text><text x=\"560\" y=\"242\">न संकरा, न चौड़ा</text>\n</g>\n<rect x=\"60\" y=\"330\" width=\"680\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"365\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">विज्ञापन-पूर्व तीन शर्तें</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"400\">1. मुफ़्त-आधार तैयार (पाठ 86-92)</text>\n<text x=\"90\" y=\"430\">2. unit-economics पता (पाठ-67)</text>\n<text x=\"90\" y=\"460\">3. attribution-रजिस्टर तैयार (पाठ-82)</text>\n</g>\n<rect x=\"60\" y=\"540\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"580\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">कभी इतना बजट नहीं जिसका नुक़सान न झेल सकें</text>\n<text x=\"400\" y=\"612\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">पाठ-72 के Decision Lab जैसी ही सतर्कता</text>\n</svg>\n```\n\n## एक असली शुरुआत — पहला ₹500 का प्रयोग\nमान लो खगड़िया की हस्तशिल्प-दुकान (पाठ-86 से) अपना पहला विज्ञापन आज़माती है। उद्देश्य — \"लीड/संदेश\" (क्योंकि WhatsApp पर बातचीत ही असली लक्ष्य)। बजट — दैनिक ₹70, पाँच दिन, यानी कुल ₹350 का जोखिम, जो नुक़सान होने पर भी दुकान को बड़ी चोट नहीं देता। दर्शक — अपने ज़िले के 15 किलोमीटर के दायरे में, \"हस्तशिल्प\" व \"गिफ़्ट\" में रुचि रखने वाले। पाँच दिन बाद attribution-रजिस्टर (पाठ-82) देखा — 12 चैट शुरू हुईं, तीन ऑर्डर बने। यह पहला छोटा प्रयोग बताता है कि रास्ता सही दिशा में है — अब अगले महीने थोड़ा बढ़ाकर फिर आज़माया जा सकता है, यही धीरे-धीरे सीखने का तरीक़ा है जो बड़ा नुक़सान होने से बचाता है।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी दुकान के लिए एक सादा विज्ञापन-ढाँचा भरिए — उद्देश्य (पाँच में से चुनिए, कारण सहित), बजट (दैनिक/कुल, राशि सहित — छोटी रखिए), दर्शक (स्थान का दायरा किमी में, रुचि के दो-तीन शब्द)। नीचे तीन शर्तों की जाँच कीजिए — तीनों \"हाँ\" हैं या नहीं, न हों तो पहले क्या पूरा करना है। जाँच-सूची: ☐ उद्देश्य कारण सहित ☐ छोटा बजट राशि सहित ☐ दर्शक-ढाँचा ☐ तीन-शर्त जाँच ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — विज्ञापन-ढाँचा भरते समय कल्पना कीजिए कि यह सचमुच अभी publish होने वाला है, टालमटोल वाली भाषा (जैसे 'शायद', 'सोच रहे हैं') की जगह पक्के फ़ैसले लिखें, ताकि असली सेटअप के दिन कोई दुविधा न रहे।\n\n## 4. नाप\nसफल = उद्देश्य दुकान की असली ज़रूरत से मेल खाए; बजट सचमुच छोटा (अनुभव-योग्य नुक़सान से कम)। समय: 25 मिनट।\n\nअगले पाठों में जैसे-जैसे नए विज्ञापन-प्रकार सीखेंगे, यही पहला ढाँचा-पन्ना आधार बना रहेगा — हर नया सीखा हुआ औज़ार इसी बुनियादी सोच पर जुड़ता जाएगा।\n\n## 5. सबूत\nसबूत-खाते में \"पहला Ads-ढाँचा पन्ना\"। पाठ-94 (Pixel-CAPI) में नापने की तैयारी इसी पन्ने से जुड़ेगी।\n\nएक याद रखने वाली बात — Meta के dashboard में उद्देश्यों के नाम कभी-कभी बदल जाते हैं (जैसे 'Leads' कभी 'Messages' कहलाया), इसलिए अपने असली मक़सद (WhatsApp पर बातचीत शुरू हो) को याद रखें और dashboard में जो नाम सबसे क़रीब लगे, वही चुनें।\n\n## 6. AI-सहायक\nAI से पूछिए — \"छोटी भारतीय दुकान के लिए Meta Ads का पहला campaign किस उद्देश्य से शुरू करना चाहिए और क्यों?\" — जवाब मिलाइए अपनी दुकान की स्थिति से, हर दुकान का सही जवाब अलग हो सकता है।\n\n## अंत में — विज्ञापन कोई एकबारगी काम नहीं\nकई नए सेवा-सहायक सोचते हैं कि एक विज्ञापन बनाकर सेट कर देना काफ़ी है। असल में विज्ञापन एक चक्र है — बनाओ, चलाओ, नापो, सीखो, फिर सुधारकर दोबारा बनाओ। पहला विज्ञापन शायद ही कभी सबसे अच्छा होता है; असली कौशल दूसरे-तीसरे प्रयास में सुधार लाने में है, न कि पहले ही प्रयास में पूर्णता खोजने में।\n\n## 7. आम ग़लती\nपहली — बिना कैटलॉग/Reel तैयार किए सीधे विज्ञापन चलाना — पैसा ख़ाली दुकान की ओर जाता है। दूसरी — पहले ही दिन बड़ा बजट डालना — ग़लती हुई तो बड़ा नुक़सान। तीसरी — बहुत चौड़ा दर्शक (पूरा भारत) चुनना — पैसा फैल जाता है, कोई असर नहीं दिखता। चौथी — बिना unit-economics समझे विज्ञापन चलाना — मुनाफ़ा है या नुक़सान, पता ही नहीं चलता।\n\nविज्ञापन-दावे में कभी नक़ली-अत्यावश्यकता ('अभी नहीं तो कभी नहीं') पैदा न करें, जब तक वह सचमुच सच न हो — यह भरोसा तोड़ने वाली तकनीक है, जिससे Meta भी विज्ञापन नामंज़ूर कर सकता है (पाठ-100 में विस्तार)।\n\n## 8. सुरक्षा-पत्रक\nविज्ञापन-बजट का भुगतान-कार्ड/UPI दुकान-मालिक के नाम व नियंत्रण में; सेवा-सहायक को खर्च-सीमा (spending limit) सेट करके ही पहुँच दें, ताकि ग़लती से बजट न बढ़ जाए। नाबालिग विद्यार्थी सिर्फ़ अभ्यास-मोड में विज्ञापन-ढाँचा बनाएँ, असली पैसा न लगाएँ।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Ads Manager सहायता — https://www.facebook.com/business/help/ads-manager — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=paid-ads-fundamentals · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं तीन खंभे (उद्देश्य-बजट-दर्शक) बिना देखे बता सकता हूँ।\n- [ ] मैंने अपनी दुकान का पहला Ads-ढाँचा बनाया है।\n- [ ] मैं जानता हूँ विज्ञापन शुरू करने की तीन शर्तें क्या हैं।\n- [ ] मैं जानता हूँ छोटे बजट से क्यों शुरू करना है।\n- [ ] मैं जानता हूँ बजट किसके नियंत्रण में रहना चाहिए।",
 "94": "═\n# पाठ-94: Pixel और CAPI — नतीजा नापने की तैयारी\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nविज्ञापन चलाने से पहले नापने का औज़ार तैयार होना चाहिए, वरना पाठ-93 की तीसरी शर्त अधूरी रह जाती है। पाठ के बाद आप तीन बातें कर पाएँगे — Pixel और CAPI का सादा अर्थ बता पाएँगे; इन्हें अपनी website/Shop पर लगाने की ज़रूरत समझ पाएँगे; और बिना website वाली दुकान के लिए विकल्प जान पाएँगे।\n\n## 2. मुख्य बात\nपाठ-82 में हमने हाथ से attribution (कौन-सा विज्ञापन कितनी बिक्री लाया) करना सीखा था — यह छोटी दुकान के लिए काफ़ी है। एक-वाक्य बात — **Pixel और CAPI दो तकनीकी औज़ार हैं जो यह स्वचालित रूप से Meta को बताते हैं कि किस विज्ञापन से वेबसाइट पर क्या हुआ (देखा, cart में डाला, ख़रीदा) — यह बड़ी दुकान के लिए ज़रूरी है, जिनकी अपनी website हो।**\n\n## Pixel — website का जासूस (अच्छे अर्थ में)\nPixel एक छोटा कोड-टुकड़ा है जो website में लगाया जाता है। जब कोई विज्ञापन से आकर website पर कुछ करे (पन्ना देखे, cart में डाले, ख़रीदे), Pixel यह जानकारी Meta को भेजता है। इससे Meta ख़ुद सीखता है कि किस तरह के लोग असल में ख़रीद रहे हैं, और भविष्य में विज्ञापन उन्हीं जैसे लोगों को ज़्यादा दिखाता है — यही \"Advantage+\" (पाठ-95) का आधार है। Pixel सिर्फ़ website के लिए है — जिनकी कोई website नहीं (ज़्यादातर छोटी भारतीय दुकानें), उनके लिए यह सीधे लागू नहीं होता।\n\n## CAPI — भरोसेमंद पिछला रास्ता\nPixel browser पर निर्भर करता है, और browser अब निजता-सुरक्षा के कारण कई बार Pixel का data रोक देते हैं (ad-blocker, cookie-सीमाएँ)। CAPI (Conversions API) एक और रास्ता है — website का अपना server सीधे Meta को data भेजता है, browser की रुकावट के बिना। यह ज़्यादा तकनीकी सेटअप माँगता है (developer या e-commerce platform की मदद), और बड़ी दुकानों/agency के लिए ज़्यादा प्रासंगिक। छोटी भारतीय दुकान के लिए, जो WhatsApp/Instagram पर टिकी है, CAPI की गहराई में जाना फ़िलहाल ज़रूरी नहीं।\n\n## website-रहित दुकान के लिए विकल्प\nअच्छी ख़बर — अगर आपकी दुकान WhatsApp/Instagram पर टिकी है (जैसे इस कोर्स की ज़्यादातर दुकानें), Pixel-CAPI का पूरा तकनीकी बोझ नहीं चाहिए। इसके बदले — **WhatsApp Business Platform का अपना conversion-tracking** (जब Click-to-WhatsApp विज्ञापन से चैट शुरू होकर template तक पहुँचती है, Meta Ads Manager में ही यह गिनती दिखती है) और **पाठ-82 का हाथ से attribution** (आइस-ब्रेकर-कोड) — यह दोनों मिलकर छोटी दुकान के लिए काफ़ी नापने की शक्ति देते हैं, बिना किसी कोड के।\n\n## कब Pixel-CAPI की तरफ़ बढ़ें\nअगर दुकान बड़ी हो जाए, अपनी website बने (पाठ-88 के Website checkout वाले रास्ते पर), और ऑर्डर की संख्या सैकड़ों प्रति महीने पहुँचे — तभी Pixel और आगे CAPI लगाने का समय आता है। यह निवेश तब सार्थक है जब बिना उसके भी सटीक नापना मुश्किल हो जाए — छोटी शुरुआत में यह ज़रूरत से ज़्यादा तकनीकी है, हाथ का attribution ही ठीक।\n\n## सेवा-सहायक की आँख\nइस पाठ में सबसे बड़ी सेवा है — दुकानदार को ईमानदारी से बताना \"आपको अभी Pixel-CAPI की ज़रूरत नहीं, हाथ का हिसाब काफ़ी है\" — कुछ agency बेवजह जटिल तकनीक बेचकर पैसा कमाती हैं; सही सलाह देना आपको उनसे अलग बनाता है।\n\n## चित्र — नापने के दो रास्ते, कौन कब\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Pixel, CAPI व हाथ का attribution</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">नापने की ताक़त — दुकान के आकार से तय</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"200\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"205\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">छोटी WhatsApp-दुकान</text>\n<text x=\"60\" y=\"190\">WhatsApp Ads-tracking</text><text x=\"60\" y=\"216\">हाथ का attribution (पाठ-82)</text><text x=\"60\" y=\"242\">कोई कोड नहीं चाहिए</text>\n<text x=\"60\" y=\"280\" font-weight=\"bold\">✓ ज़्यादातर के लिए काफ़ी</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"200\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"595\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#1565C0\">बड़ी website-दुकान</text>\n<text x=\"450\" y=\"190\">Pixel — browser-आधारित</text><text x=\"450\" y=\"216\">CAPI — server-आधारित</text><text x=\"450\" y=\"242\">तकनीकी सेटअप चाहिए</text>\n<text x=\"450\" y=\"280\" font-weight=\"bold\">बड़े पैमाने पर सार्थक</text>\n</g>\n<rect x=\"60\" y=\"360\" width=\"680\" height=\"140\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"395\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">कब बढ़ें</text>\n<text x=\"400\" y=\"430\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">अपनी website + सैकड़ों ऑर्डर/महीना → तभी Pixel-CAPI सार्थक</text>\n<text x=\"400\" y=\"462\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">छोटी शुरुआत में हाथ का हिसाब पर्याप्त और सरल</text>\n<rect x=\"60\" y=\"520\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"560\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">ईमानदार सलाह — बेवजह जटिल तकनीक न बेचें</text>\n<text x=\"400\" y=\"592\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">यही आपकी सेवा को भरोसेमंद बनाता है</text>\n</svg>\n```\n\n## एक सादा उदाहरण — क्या हुआ, क्या नहीं\nमान लो पटना की मसाला-कंपनी की एक website है। बिना Pixel के, दुकानदार सिर्फ़ इतना जानता है कि \"इस महीने website पर 500 विज़िट आईं और 20 ऑर्डर मिले\" — पर कौन-सा विज्ञापन उन विज़िट को लाया, यह अस्पष्ट रहता है। Pixel लगाने के बाद वही जानकारी विज्ञापन-वार दिखने लगती है — \"विज्ञापन-अ से 300 विज़िट, 15 ऑर्डर; विज्ञापन-ब से 200 विज़िट, 5 ऑर्डर\" — अब साफ़ पता चलता है कहाँ पैसा बेहतर काम कर रहा है। यह ठीक वही फ़ायदा है जो पाठ-82 में हाथ के attribution ने WhatsApp के लिए दिया था, बस यहाँ website के लिए एक तकनीकी औज़ार यह काम करता है। छोटी दुकान के लिए हाथ का तरीक़ा अक्सर उतना ही असरदार और बहुत सरल रहता है।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी दुकान के लिए तय कीजिए — क्या आपको Pixel-CAPI चाहिए, या हाथ का attribution काफ़ी है? कारण तीन-चार पंक्तियों में लिखिए (website है/नहीं, ऑर्डर-संख्या, तकनीकी सहारा उपलब्ध है/नहीं)। अगर website है, तो Pixel लगाने के तीन कदम स्रोत-कड़ी से नोट कीजिए। जाँच-सूची: ☐ Pixel-CAPI ज़रूरी/नहीं का फ़ैसला कारण सहित ☐ (अगर लागू) तीन कदम नोट ☐ अपने हाथ के attribution की स्थिति दोहराई ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — फ़ैसला-पन्ने पर आज की तारीख़ लिखें, क्योंकि दुकान बढ़ने पर यही फ़ैसला महीनों बाद बदल सकता है, और तब पुरानी तारीख़ देखकर याद आएगा कि आख़िरी बार कब यह सोचा गया था।\n\n## 4. नाप\nसफल = फ़ैसला दुकान की असली स्थिति से निकला, \"सब लगा लेते हैं\" जैसा अंदाज़ा नहीं। समय: 20 मिनट।\n\nआगे पाठ-101 (Meta का unit-economics) में यह फ़ैसला-पन्ना बताएगा कि विज्ञापन-ख़र्च कितनी सटीकता से नापा जा सकता है, जो मुनाफ़े के सही हिसाब के लिए ज़रूरी है।\n\n## 5. सबूत\nसबूत-खाते में \"Pixel-CAPI फ़ैसला-पन्ना\"। यह पाठ-101 (unit-economics) में विज्ञापन-नापने की पूरी तस्वीर का हिस्सा बनेगा।\n\nMeta के मदद-पन्ने पर Pixel-सेटअप के लिए e-commerce platform के अनुसार अलग-अलग निर्देश मिलते हैं (जैसे Shopify, WordPress) — अगर website किसी ऐसे platform पर है, वहीं के विशेष निर्देश खोजें।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Facebook Pixel और Conversions API (CAPI) में क्या फ़र्क़ है, और एक छोटी दुकान को इनकी कब ज़रूरत पड़ती है?\" — जवाब मिलाइए अपने फ़ैसले-पन्ने से।\n\n## पाँचवीं ग़लती और सुधार\nपाँचवीं आम ग़लती — किसी बाहरी agency से \"हम Pixel-CAPI लगा देंगे\" सुनकर बिना पूछे यह मान लेना कि इससे बिक्री बढ़ेगी। असल में Pixel-CAPI सिर्फ़ नापने का औज़ार है, ख़ुद बिक्री नहीं बढ़ाता — यह विज्ञापन को बेहतर लक्षित करने में मदद करता है, पर उत्पाद, दाम, और सेवा की गुणवत्ता वही रहती है जो पहले से है। इसे \"जादुई बिक्री-बढ़ाने वाला यंत्र\" समझना एक आम और महँगी ग़लतफ़हमी है।\n\n## 7. आम ग़लती\nपहली — बिना website के भी Pixel लगाने की कोशिश करना — यह website के लिए बना है, WhatsApp/Instagram के लिए नहीं। दूसरी — किसी agency के दबाव में महँगा CAPI-सेटअप ख़रीदना जब हाथ का हिसाब काफ़ी होता। तीसरी — Pixel लगाकर फिर कभी उसकी रिपोर्ट न देखना — लगाना काफ़ी नहीं, उपयोग करना ज़रूरी। चौथी — नापने के औज़ार को नज़रअंदाज़ करके सिर्फ़ \"लगता है बिक्री बढ़ी\" पर भरोसा करना।\n\nPixel/CAPI से इकट्ठा data का उपयोग सिर्फ़ बेहतर विज्ञापन दिखाने तक सीमित रहे, ग्राहक-निगरानी या किसी और मक़सद से न हो — यह DPDP-सिद्धांत का ही विस्तार है।\n\n## 8. सुरक्षा-पत्रक\nPixel/CAPI डेटा में ग्राहक-व्यवहार की जानकारी जाती है — DPDP-निजता नियम (पाठ-58) यहाँ भी लागू; website पर privacy-policy का उल्लेख ज़रूरी अगर Pixel लगा हो।\n\nअगला पाठ-95 इसी तकनीकी नींव को Advantage+ के साथ जोड़ेगा, जहाँ Pixel-डेटा की मौजूदगी सीधे विज्ञापन की गुणवत्ता तय करती है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Pixel व Conversions API दस्तावेज़ — https://www.facebook.com/business/help/952192354843755 — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=conversion-tracking-basics · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Pixel और CAPI का सादा फ़र्क़ बता सकता हूँ।\n- [ ] मैं जानता हूँ कब यह छोटी दुकान के लिए ज़रूरी नहीं।\n- [ ] मैंने अपनी दुकान का फ़ैसला कारण सहित लिखा है।\n- [ ] मैं जानता हूँ website-रहित दुकान के लिए क्या विकल्प है।\n- [ ] मैं जानता हूँ बेवजह जटिल तकनीक क्यों नहीं बेचनी।",
 "95": "═\n# पाठ-95: Advantage+ — कब असरदार, कब पैसा बर्बाद\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nMeta ने विज्ञापन-सेटिंग को AI से स्वचालित करने के लिए Advantage+ नाम की सुविधा दी है। पाठ के बाद आप तीन बातें कर पाएँगे — Advantage+ का सादा अर्थ बता पाएँगे; यह कब असरदार होता है और कब पैसा बर्बाद करता है, पहचान पाएँगे; और अपनी दुकान के लिए सही फ़ैसला ले पाएँगे।\n\n## 2. मुख्य बात\nपाठ-93 में हमने दर्शक ख़ुद चुनना सीखा। एक-वाक्य बात — **Advantage+ एक AI-चालित सुविधा है जो दर्शक-चुनाव, बजट-बँटवारा, या पूरा campaign अपने-आप, Meta के अनुभव से, तय कर देती है — यह तभी अच्छा काम करता है जब Pixel/CAPI (पाठ-94) से या पुराने विज्ञापनों से Meta के पास पर्याप्त \"सीखने का डेटा\" हो, नए/छोटे खाते के लिए यह अक्सर पैसा बर्बाद करता है।**\n\n## Advantage+ कैसे काम करता है\nसामान्य विज्ञापन में आप ख़ुद दर्शक चुनते हैं (पाठ-93)। Advantage+ Audience में आप सिर्फ़ एक शुरुआती इशारा (जैसे उम्र-सीमा या स्थान) देते हैं, बाक़ी Meta का AI ख़ुद तय करता है — किसे दिखाना है, यह देखकर कि \"पहले किन लोगों ने ख़रीदा\"। Advantage+ Shopping Campaigns (कैटलॉग-आधारित) पूरा campaign — उत्पाद-चुनाव, दर्शक, creative — सब स्वचालित कर सकता है।\n\n## कब असरदार — तीन शर्तें\n1. **पिछला डेटा हो।** अगर आपने पहले कई विज्ञापन चलाए हैं और Meta के पास \"किसने ख़रीदा\" का इतिहास है, Advantage+ उसी से सीखकर बेहतर दर्शक ढूँढता है। 2. **कैटलॉग बड़ा व साफ़ हो।** Shopping Campaigns तभी अच्छा काम करते हैं जब कैटलॉग (पाठ-87) में दर्जनों-सैकड़ों साफ़ उत्पाद हों, ताकि AI के पास चुनने के लिए विकल्प हों। 3. **बजट पर्याप्त हो।** AI को \"सीखने\" के लिए कुछ न्यूनतम ख़र्च और समय चाहिए — बहुत छोटा एक-दिन का बजट सीखने का मौक़ा ही नहीं देता।\n\n## कब पैसा बर्बाद — तीन चेतावनी\n1. **नया खाता, कोई पुराना डेटा नहीं** — AI के पास सीखने को कुछ नहीं, अंदाज़े से दर्शक चुनता है, जो ग़लत भी हो सकता है। 2. **छोटा कैटलॉग (एक-दो उत्पाद)** — Shopping Campaigns के लिए बहुत सीमित विकल्प। 3. **बहुत छोटा/एक-दिन का बजट** — \"सीखने के दौर\" में ही बजट ख़त्म हो जाता है, नतीजा कभी साफ़ नहीं दिखता।\n\n## छोटी दुकान के लिए ईमानदार सलाह\nपहले दो-तीन Meta Ads campaign (पाठ-93 जैसे, ख़ुद-चुने दर्शक से) चलाकर देखिए, हाथ का attribution (पाठ-82) से नतीजा नापिए। इसके बाद अगर लगे कि दर्शक-चुनाव में सुधार चाहिए, तभी Advantage+ आज़माइए, वह भी थोड़े बजट से — यह \"पहले से बेहतर\" जैसा प्रयोग हो, \"जादू की छड़ी\" जैसा भरोसा नहीं। Meta ख़ुद भी अक्सर इसे सुझाता है (dashboard में default), पर सुझाव मतलब गारंटी नहीं।\n\n## सेवा-सहायक की आँख\n\"Advantage+ कब आज़माना है, इसका सही समय पहचानना\" एक सूक्ष्म पर क़ीमती सलाह-सेवा है। नए दुकानदार को इसमें जल्दी न धकेलें — पहले बुनियाद (मैनुअल दर्शक, पाठ-93) मज़बूत कराइए, फिर आगे बढ़ाइए।\n\n## चित्र — Advantage+ कब सही, कब ग़लत\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Advantage+ — AI-चालित विज्ञापन</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">पर्याप्त डेटा + बड़ा कैटलॉग + पर्याप्त बजट तभी असरदार</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"205\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">कब असरदार</text>\n<text x=\"60\" y=\"190\">पिछला ख़रीद-डेटा मौजूद</text><text x=\"60\" y=\"220\">बड़ा साफ़ कैटलॉग</text><text x=\"60\" y=\"250\">पर्याप्त बजट (सीखने का समय)</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"595\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">कब पैसा बर्बाद</text>\n<text x=\"450\" y=\"190\">नया खाता, कोई इतिहास नहीं</text><text x=\"450\" y=\"220\">छोटा कैटलॉग (1-2 उत्पाद)</text><text x=\"450\" y=\"250\">बहुत छोटा/एक-दिन बजट</text>\n</g>\n<rect x=\"60\" y=\"370\" width=\"680\" height=\"160\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"405\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">छोटी दुकान के लिए क्रम</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"440\">पहले 2-3 campaign ख़ुद-चुने दर्शक से (पाठ-93)</text>\n<text x=\"90\" y=\"470\">हाथ के attribution से नतीजा नापें (पाठ-82)</text>\n<text x=\"90\" y=\"500\">तभी थोड़े बजट से Advantage+ आज़माएँ</text>\n</g>\n<rect x=\"60\" y=\"550\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"590\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta का सुझाव = सुझाव, गारंटी नहीं</text>\n<text x=\"400\" y=\"618\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">\"जादू की छड़ी\" जैसा भरोसा न करें</text>\n</svg>\n```\n\n## एक तुलना-कहानी — जल्दबाज़ी बनाम धैर्य\nमान लो दो दुकानें एक ही दिन विज्ञापन शुरू करती हैं। दुकान-अ तुरंत Advantage+ चुनती है, बिना किसी पुराने डेटा के, ₹200 प्रतिदिन का बजट डालती है — पहले हफ़्ते में AI बेतरतीब दर्शकों को दिखाता रहता है, नतीजा कमज़ोर, पैसा काफ़ी हद तक बेकार जाता है। दुकान-ब पहले दो हफ़्ते साधारण, ख़ुद-चुने दर्शक से (पाठ-93 जैसे) छोटे बजट में विज्ञापन चलाती है, नतीजा नापती है, फिर तीसरे हफ़्ते उसी सीखे हुए दर्शक-अंदाज़े के साथ Advantage+ आज़माती है — वहाँ नतीजा काफ़ी बेहतर आता है, क्योंकि अब कुछ शुरुआती डेटा भी मौजूद है। यह कहानी दिखाती है कि धैर्य से चला गया रास्ता अक्सर जल्दबाज़ी से बेहतर पैसा बचाता और कमाता है।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी दुकान की स्थिति तीन शर्तों पर परखिए — क्या पिछला विज्ञापन-डेटा है? कैटलॉग कितना बड़ा है? बजट कितना रखने की सोच है? हर एक का जवाब लिखकर तय कीजिए — अभी Advantage+ आज़माना सही है या पहले साधारण campaign चलाना। कारण सहित लिखिए। जाँच-सूची: ☐ तीन शर्तों का जवाब ☐ फ़ैसला कारण सहित ☐ अगर \"अभी नहीं\" तो कब दोबारा सोचेंगे लिखा ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — यह फ़ैसला-पन्ना हर महीने दोबारा जाँचना अच्छी आदत है, क्योंकि जैसे-जैसे विज्ञापन-डेटा जमा होता है, 'अभी नहीं' का जवाब कभी 'अब हाँ' में बदल सकता है।\n\n## 4. नाप\nसफल = फ़ैसला तीनों शर्तों से निकला, अंदाज़े से नहीं। समय: 20 मिनट।\n\nअगर कभी बाद में Advantage+ आज़माएँ, तो इसी पन्ने पर नतीजे जोड़ते जाएँ — यह एक जीवित दस्तावेज़ बनेगा जो समय के साथ दुकान की विज्ञापन-समझ को दिखाएगा।\n\n## 5. सबूत\nसबूत-खाते में \"Advantage+ फ़ैसला-पन्ना\"। पाठ-101 में unit-economics के साथ इसकी दोबारा समीक्षा होगी।\n\nएक याद रखने वाली बात — Advantage+ के भीतर भी कई उप-सुविधाएँ हैं (जैसे सिर्फ़ दर्शक स्वचालित, या पूरा creative भी स्वचालित) — शुरुआत हमेशा सबसे कम स्वचालन वाले विकल्प से करें, धीरे-धीरे बढ़ाएँ।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Meta Advantage+ विज्ञापन एक नए, छोटे विज्ञापन-खाते के लिए कब अच्छा काम करता है और कब नहीं?\" — जवाब मिलाइए अपनी तीन-शर्त सूची से।\n\n## पाँचवीं ग़लती और सुधार\nपाँचवीं आम ग़लती — Advantage+ चालू करने के बाद उसे \"अब हमेशा के लिए ठीक है\" मान लेना और महीनों तक न देखना। AI-चालित सुविधाएँ भी समय के साथ अपना रुख़ बदल सकती हैं — बाज़ार बदलता है, प्रतियोगी बदलते हैं, ग्राहक-रुचि बदलती है। इसलिए Advantage+ campaign की भी वही मासिक निगरानी चाहिए जो साधारण campaign की — \"AI ने सँभाल लिया\" सोचकर पूरी तरह छोड़ देना जोखिम भरा है।\n\n## 7. आम ग़लती\nपहली — पहले ही दिन, बिना किसी डेटा के, \"AI सब कर देगा\" सोचकर Advantage+ पर पूरा बजट डालना। दूसरी — Meta के डिफ़ॉल्ट-सुझाव को बिना सोचे स्वीकार करना। तीसरी — Advantage+ आज़माने के बाद नतीजा न देखना, \"AI ने कर दिया होगा\" मान लेना। चौथी — बुनियाद (कैटलॉग, मुफ़्त-सूचना) कमज़ोर होते हुए भी advanced सुविधा में कूदना।\n\nAdvantage+ campaign में भी कभी ऐसी दर्शक-श्रेणी न चुनें जो भेदभावपूर्ण लगे (जैसे किसी समुदाय को जान-बूझकर छोड़ना) — Meta की नीति और नैतिकता दोनों इसे अस्वीकार करते हैं।\n\nकिसी भी AI-चालित campaign में भी बजट-सीमा हमेशा हाथ से तय रखें, चाहे 'स्वचालित' नाम कितना भी भरोसेमंद क्यों न लगे — नियंत्रण कभी पूरी तरह मशीन को न सौंपें, चाहे परिणाम कितने भी अच्छे क्यों न दिखें।\n\n## 8. सुरक्षा-पत्रक\nAdvantage+ campaign में भी बजट-सीमा तय करके ही चालू करें — \"AI ख़ुद बेहतर तय करेगा\" के भरोसे बजट-नियंत्रण न छोड़ें। हर हफ़्ते खर्च की जाँच अनिवार्य, चाहे campaign साधारण हो या Advantage+।\n\nआगे पाठ-96 में हम इसी सतर्कता को दो ख़ास विज्ञापन-प्रकारों (Click-to-WhatsApp व Catalog-ads) पर लागू करते हुए देखेंगे।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। Advantage+ की सुविधाएँ व नाम Meta बार-बार बदलता है (Δ) — ताज़ा जानकारी मदद-कड़ी से लें। 📎 मूल-कोर्स-कड़ी: Meta Advantage+ सहायता — https://www.facebook.com/business/help/advantage-plus — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-automated-ad-targeting · platform=meta · level=S · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\nनिष्कर्ष यह है कि Advantage+ न कोई शॉर्टकट है, न कोई जाल — यह सिर्फ़ एक और औज़ार है, जिसे सही समय और सही तैयारी के साथ उपयोग करने पर ही फ़ायदा मिलता है, जल्दबाज़ी में नहीं।\n\n## 10. योग्यता-जाँच\n- [ ] मैं Advantage+ को एक वाक्य में समझा सकता हूँ।\n- [ ] मैं जानता हूँ यह कब असरदार, कब बर्बाद होता है।\n- [ ] मैंने अपनी दुकान के लिए तीन-शर्त परख की है।\n- [ ] मैं जानता हूँ Meta का सुझाव गारंटी नहीं है।\n- [ ] मैं जानता हूँ बजट-नियंत्रण AI को सौंपना नहीं है।",
 "96": "═\n# पाठ-96: Click-to-WhatsApp व Catalog-ads\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nअब तक विज्ञापन की बुनियादी समझ बनी; आज दो ख़ास प्रकार जो छोटी भारतीय दुकान के लिए सबसे उपयोगी हैं। पाठ के बाद आप तीन बातें कर पाएँगे — Click-to-WhatsApp विज्ञापन को Ads Manager से बना पाएँगे (पाठ-82 का तकनीकी विस्तार); Catalog-ads का काम समझ पाएँगे; और दोनों में से अपनी दुकान के लिए सही चुनाव कर पाएँगे।\n\n## 2. मुख्य बात\nपाठ-82 में हमने Click-to-WhatsApp विज्ञापन को ग्राहक के नज़रिए से देखा था। एक-वाक्य बात — **Click-to-WhatsApp विज्ञापन Ads Manager में उद्देश्य \"Leads\" या \"Engagement\" चुनकर, destination WhatsApp सेट करके बनता है; Catalog-ads (Dynamic Ads) कैटलॉग (पाठ-87) से जुड़कर हर ग्राहक को उसकी रुचि के अनुसार अलग-अलग उत्पाद स्वचालित रूप से दिखाता है।**\n\n## Click-to-WhatsApp विज्ञापन बनाना — कदम\n1. Ads Manager में \"Create\" → उद्देश्य में \"Leads\" या \"Engagement\" चुनें (Meta समय-समय पर नाम बदलता है)। 2. destination में \"WhatsApp\" चुनें, अपना Business नंबर जोड़ें। 3. फ़ोटो/वीडियो (Reel जैसा, पाठ-90) और caption डालें। 4. आइस-ब्रेकर संदेश सेट करें (पाठ-82 का वही तरीक़ा, पर अब dashboard से सीधे) — हर विज्ञापन का अलग आइस-ब्रेकर रखें ताकि attribution आसान रहे। 5. दर्शक-बजट (पाठ-93) भरकर publish करें।\n\n## Catalog-ads (Dynamic Ads) — क्या और कैसे\nसामान्य विज्ञापन में एक ही फ़ोटो/उत्पाद सबको दिखता है। Catalog-ads में आप पूरा कैटलॉग जोड़ते हैं, और Meta का सिस्टम हर देखने वाले को उसकी पिछली गतिविधि के अनुसार अलग-अलग उत्पाद दिखाता है — जैसे जिसने आपकी website पर एक साड़ी देखी थी (Pixel से, पाठ-94), उसे अब वही साड़ी या मिलती-जुलती साड़ी विज्ञापन में दिखे। यह \"retargeting\" (दोबारा-लक्षित करना) कहलाता है — पहले से रुचि दिखाने वाले को याद दिलाना, जो अक्सर नए दर्शक से बेहतर परिणाम देता है। ध्यान — Catalog-ads का यह पूरा retargeting-फ़ायदा Pixel/CAPI (पाठ-94) पर निर्भर करता है; बिना website वाली दुकान के लिए यह सुविधा सीमित रहती है, फिर भी कैटलॉग सिर्फ़ दिखाने के लिए (बिना retargeting) उपयोग हो सकता है।\n\n## दोनों में से कौन — छोटी दुकान के लिए\n**Click-to-WhatsApp** — website-रहित, WhatsApp-केंद्रित छोटी दुकान के लिए पहला और सबसे व्यावहारिक विज्ञापन-प्रकार; सीधा, समझने में आसान, attribution हाथ से आसान (पाठ-82)। **Catalog-ads** — तब उपयोगी जब कैटलॉग बड़ा हो, website/Pixel हो, और दुकान retargeting का फ़ायदा उठाने लायक़ ट्रैफ़िक पा चुकी हो। ज़्यादातर इस कोर्स की दुकानों के लिए शुरुआती चरण में Click-to-WhatsApp ही सही जवाब है।\n\n## दोनों को त्योहार में मिलाना\nआगे पाठ-97 में हम त्योहार-मूल्य-चक्र देखेंगे — वहाँ अक्सर दोनों प्रकार साथ चलते हैं: Click-to-WhatsApp नए ग्राहकों के लिए, Catalog-ads (अगर उपलब्ध हो) पुराने-रुचि-दिखाने वालों को याद दिलाने के लिए। यह समझ आगे के पाठ की नींव है।\n\n## सेवा-सहायक की आँख\n\"पहला Click-to-WhatsApp विज्ञापन, अलग-अलग आइस-ब्रेकर के साथ, dashboard से सेटअप\" एक सीधी शुरुआती सेवा है जो पाठ-82 की समझ को असली Ads Manager में उतारती है। Catalog-ads सिर्फ़ उन्हीं दुकानों को सुझाइए जिनकी website/Pixel तैयार हो (पाठ-94 का फ़ैसला)।\n\n## चित्र — दो विज्ञापन-प्रकार, दो ज़रूरतें\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Click-to-WhatsApp बनाम Catalog-ads</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">छोटी दुकान का पहला रास्ता बनाम retargeting-रास्ता</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"230\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"205\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">Click-to-WhatsApp</text>\n<text x=\"60\" y=\"190\">website-रहित के लिए</text><text x=\"60\" y=\"216\">सीधा, आइस-ब्रेकर सेट</text><text x=\"60\" y=\"242\">हाथ का attribution आसान</text>\n<text x=\"60\" y=\"280\" font-weight=\"bold\">✓ ज़्यादातर दुकानों का पहला रास्ता</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"230\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"595\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#1565C0\">Catalog-ads</text>\n<text x=\"450\" y=\"190\">retargeting — याद दिलाना</text><text x=\"450\" y=\"216\">कैटलॉग+Pixel पर निर्भर</text><text x=\"450\" y=\"242\">बड़ा कैटलॉग+website चाहिए</text>\n<text x=\"450\" y=\"280\" font-weight=\"bold\">बड़ी दुकान के लिए बेहतर</text>\n</g>\n<rect x=\"60\" y=\"380\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"415\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">Click-to-WhatsApp बनाने के पाँच कदम</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"450\">उद्देश्य चुनें → destination=WhatsApp → फ़ोटो-caption</text>\n<text x=\"90\" y=\"480\">आइस-ब्रेकर सेट (हर विज्ञापन अलग) → दर्शक-बजट → publish</text>\n</g>\n<rect x=\"60\" y=\"550\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"590\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">त्योहार में दोनों साथ चल सकते हैं (पाठ-97)</text>\n<text x=\"400\" y=\"618\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">नए ग्राहक = WhatsApp · पुराने-रुचि वाले = Catalog-retargeting</text>\n</svg>\n```\n\n## दोनों प्रकारों की एक साथ-साथ तुलना\nमान लो एक ही दुकान दोनों प्रकार आज़माती है। Click-to-WhatsApp विज्ञापन पर ₹50/दिन — पाँच दिन में 15 नई चैट, 4 ऑर्डर। इसी दौरान अगर कैटलॉग-ads भी चलाया गया हो (मान लो website-Pixel तैयार थी) — वहाँ 8 लोग जो पहले website पर उत्पाद देख चुके थे, उन्हें फिर दिखाया गया, जिनमें से 3 ने ख़रीदा। यह दिखाता है कि दोनों प्रकार अलग-अलग काम करते हैं — एक नए लोगों को लाता है, दूसरा पहले से रुचि दिखाने वालों को वापस खींचता है। छोटी दुकान के लिए अक्सर सिर्फ़ पहला ही उपलब्ध और ज़रूरी होता है, पर बड़ी होती दुकान के लिए दोनों साथ मिलकर एक पूरा चक्र बनाते हैं।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी दुकान के लिए एक Click-to-WhatsApp विज्ञापन का पूरा मसौदा लिखिए — फ़ोटो/वीडियो-विषय, caption, आइस-ब्रेकर संदेश (पाठ-82 जैसा, पर नया)। तय कीजिए — Catalog-ads अभी आपके लिए सही है या नहीं (पाठ-94 के फ़ैसले से जोड़कर)। जाँच-सूची: ☐ Click-to-WhatsApp पूरा मसौदा ☐ Catalog-ads फ़ैसला कारण सहित ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — Catalog-ads के फ़ैसले में सिर्फ़ 'हाँ चाहिए' या 'नहीं चाहिए' न लिखें, बल्कि 'कब चाहिए होगा' का एक अनुमानित समय भी जोड़ें (जैसे 'website बनने के बाद'), ताकि यह फ़ैसला भविष्य के लिए एक योजना भी बने।\n\n## 4. नाप\nसफल = आइस-ब्रेकर पहले से लिखे विज्ञापनों से अलग (attribution के लिए); Catalog-ads फ़ैसला पाठ-94 से मेल खाए। समय: 25 मिनट।\n\nयह मसौदा-पन्ना पाठ-98 (AI से विज्ञापन-रचना) में एक तुलना के लिए काम आएगा — वहाँ हम देखेंगे कि AI-सहायता से बनाया मसौदा इससे कितना अलग या बेहतर हो सकता है।\n\n## 5. सबूत\nसबूत-खाते में \"Click-to-WhatsApp विज्ञापन-मसौदा\"। यह पोर्टफ़ोलियो में असली Ads-सेवा के नमूने के रूप में जाएगा।\n\nAI से पूछते समय हमेशा साफ़ बताएँ कि 'यह Click-to-WhatsApp विज्ञापन के लिए है' या 'Catalog-ads के लिए', क्योंकि दोनों की भाषा-शैली अलग होनी चाहिए — पहले में बातचीत का न्योता, दूसरे में उत्पाद-याद-दिलाना।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरे (उत्पाद) के लिए Click-to-WhatsApp विज्ञापन का caption और आइस-ब्रेकर संदेश लिखो, सादी हिंदी में, कोई गढ़ा दावा नहीं।\"\n\n## 7. आम ग़लती\nपहली — सभी विज्ञापनों में एक ही आइस-ब्रेकर रखना (पाठ-82 की चौथी ग़लती फिर) — attribution टूट जाता है। दूसरी — बिना website/Pixel के Catalog-ads की उम्मीद करना कि वह retargeting करेगा। तीसरी — WhatsApp-नंबर विज्ञापन में ग़लत/पुराना जोड़ना — जाँच ज़रूरी। चौथी — caption में उत्पाद की सच्चाई से हटकर बढ़ा-चढ़ाकर दावा करना।\n\nअंतिम याद-दिलाना — दोनों विज्ञापन-प्रकारों में ग्राहक की निजी बातचीत की स्क्रीनशॉट कभी सार्वजनिक विज्ञापन-सामग्री में उपयोग न करें, बिना उसकी साफ़ सहमति के — यह उतना ही ज़रूरी है जितना बाक़ी सब निजता-नियम।\n\n## 8. सुरक्षा-पत्रक\nविज्ञापन में जोड़ा WhatsApp नंबर वही हो जो असली दुकान-खाता चलाता है, कोई अस्थायी/परीक्षण-नंबर नहीं — ग्राहक भरोसे से चैट करेगा। विज्ञापन-दावे उतने ही सच्चे जितना उत्पाद असल में है (पाठ-16 का नियम)।\n\nखंड-7 के आगे के पाठों (97-103) में यही दोनों विज्ञापन-प्रकार त्योहार-रणनीति, AI-रचना और नतीजा-पढ़ने के साथ और गहराई से जुड़ेंगे।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Click-to-Message Ads व Dynamic/Catalog Ads दस्तावेज़ — https://www.facebook.com/business/help/dynamic-ads — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=whatsapp-and-catalog-ad-formats · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\nनिष्कर्ष यह है कि दोनों विज्ञापन-प्रकार अपनी-अपनी जगह सही हैं — पहचान यह है कि कौन-सा प्रकार आपकी दुकान की मौजूदा स्थिति (website है या नहीं, कैटलॉग कितना बड़ा) से मेल खाता है।\n\nपोर्टफ़ोलियो के लिए यह विज्ञापन-मसौदा एक अच्छा नमूना है जो दिखाता है कि आपने सिर्फ़ तकनीक नहीं, बल्कि सही-प्रकार-चुनने की समझ भी हासिल की है।\n\n## 10. योग्यता-जाँच\n- [ ] मैं Click-to-WhatsApp विज्ञापन के पाँच कदम बता सकता हूँ।\n- [ ] मैं Catalog-ads (retargeting) का सादा अर्थ जानता हूँ।\n- [ ] मैंने अपनी दुकान के लिए सही विज्ञापन-प्रकार चुना है।\n- [ ] मैंने एक पूरा विज्ञापन-मसौदा आइस-ब्रेकर सहित बनाया है।\n- [ ] मैं जानता हूँ Catalog-ads Pixel पर क्यों निर्भर करता है।",
 "97": "═\n# पाठ-97: त्योहार-मूल्य-चक्र, COD/UPI-वर्ग, रचना-ताज़गी\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nभारत में त्योहार बिक्री का सबसे बड़ा मौक़ा हैं — पर बिना योजना के विज्ञापन-बजट त्योहार में ही सबसे तेज़ी से बर्बाद भी होता है। पाठ के बाद आप तीन बातें कर पाएँगे — त्योहार-मूल्य-चक्र (दाम कब बढ़ता-घटता है, विज्ञापन-लागत कब महँगी होती है) समझ पाएँगे; COD और UPI ग्राहकों के अलग व्यवहार को पहचान पाएँगे; और अपनी विज्ञापन-सामग्री को ताज़ा रखने का तरीक़ा सीख पाएँगे।\n\n## 2. मुख्य बात\nपाठ-93-96 तक हमने विज्ञापन का सामान्य ढाँचा सीखा। एक-वाक्य बात — **त्योहार के दौरान सभी दुकानें एक साथ विज्ञापन बढ़ाती हैं, इसलिए विज्ञापन दिखाने की लागत (CPM, आगे पाठ-99) अपने-आप बढ़ जाती है — जो दुकान इस चक्र को समझकर पहले से योजना बनाती है, वही सस्ते में ज़्यादा फ़ायदा उठा पाती है।**\n\n## त्योहार-मूल्य-चक्र — तीन चरण\n**चरण-1 तैयारी (त्योहार से 3-4 हफ़्ते पहले):** विज्ञापन-लागत अभी सामान्य होती है — यही समय है कैटलॉग तैयार करने, Reels बनाने, और छोटे बजट से परीक्षण-विज्ञापन चलाने का, ताकि असली त्योहार-भीड़ से पहले \"क्या असर करता है\" पता चल जाए। **चरण-2 भीड़ (त्योहार से 1-2 हफ़्ते पहले से त्योहार तक):** सभी दुकानें विज्ञापन बढ़ाती हैं, CPM (हज़ार दिखावे की लागत) बढ़ जाता है — यहीं चरण-1 में सीखा हुआ सबसे बेहतर विज्ञापन (सबसे अच्छा दर्शक, सबसे असरदार creative) पूरे बजट के साथ चलाया जाए, नया प्रयोग करने का समय नहीं। **चरण-3 बाद (त्योहार के तुरंत बाद):** बहुत-सी दुकानें विज्ञापन बंद कर देती हैं, लागत फिर गिरती है — यह \"बचा हुआ स्टॉक साफ़ करने\" या अगले छोटे त्योहार की तैयारी का सस्ता मौक़ा हो सकता है।\n\n## COD बनाम UPI-ग्राहक — अलग व्यवहार\nCash on Delivery (COD) से ऑर्डर करने वाले ग्राहक अक्सर जल्दी में फ़ैसला लेते हैं (पैसा तुरंत नहीं देना, इसलिए जोखिम कम लगता है), पर रद्द-दर (cancel/return) भी ज़्यादा होती है (पाठ-70 का COD-धोखा जोखिम)। UPI/पहले-भुगतान वाले ग्राहक थोड़ा सोच-समझकर फ़ैसला लेते हैं, पर एक बार भुगतान करने के बाद रद्द-दर बहुत कम होती है — यह असली, पक्का ग्राहक है। त्योहार-विज्ञापन में दोनों वर्गों को थोड़ा अलग सोच से देखें — COD-listing पर rd दर का हिसाब unit-economics में शामिल करें (पाठ-69, पाठ-101), UPI-सूचना/छूट को थोड़ा प्राथमिकता दें अगर मुनाफ़ा-मार्जिन पहले से पतला हो।\n\n## रचना-ताज़गी — पुराना विज्ञापन थक जाता है\n\"Ad fatigue\" (विज्ञापन-थकान) — एक ही फ़ोटो/वीडियो बार-बार दिखने से लोग उसे नज़रअंदाज़ करने लगते हैं, नतीजा गिरता है। त्योहार के लंबे चक्र (2-3 हफ़्ते) में एक ही Reel/creative पूरे समय मत चलाइए — हर हफ़्ते नया कोण (नई फ़ोटो, नया caption, अलग आइस-ब्रेकर) डालें। पाठ-90 के कई Reel-नमूने और पाठ-98 (AI से रचना) यहीं काम आएँगे — कई विकल्प तैयार रखना त्योहार से पहले की सबसे बड़ी तैयारी है।\n\n## एक व्यावहारिक त्योहार-योजना — चार हफ़्ते\nहफ़्ता-1 (चरण-1): कैटलॉग-सफ़ाई, दो-तीन Reel तैयार, छोटा परीक्षण-विज्ञापन। हफ़्ता-2 (चरण-1 का अंत): परीक्षण के नतीजे देखकर सबसे अच्छा creative चुनें। हफ़्ता-3 (चरण-2 शुरू): पूरा बजट, चुना हुआ creative, हर 3-4 दिन में हल्का बदलाव (नई फ़ोटो-caption) ताकि थकान न हो। हफ़्ता-4 (चरण-3): त्योहार के बाद, बचे स्टॉक पर छोटा offer, अगले त्योहार की तैयारी शुरू।\n\n## सेवा-सहायक की आँख\n\"चार-हफ़्ते का त्योहार-कैलेंडर + रचना-ताज़गी की योजना\" एक उच्च-मूल्य वाली मौसमी सेवा है — यही वह समय है जब दुकानदार सबसे ज़्यादा आपकी विशेषज्ञता की क़द्र करता है, क्योंकि इसी दौर में सबसे ज़्यादा बिक्री दांव पर होती है।\n\n## चित्र — त्योहार-मूल्य-चक्र, चार हफ़्ते\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">त्योहार-मूल्य-चक्र — तीन चरण</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सब दुकानें एक साथ बढ़ाएँ → विज्ञापन-लागत बढ़ती है</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"160\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"150\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">चरण-1 तैयारी</text><text x=\"60\" y=\"190\">3-4 हफ़्ते पहले</text><text x=\"60\" y=\"216\">लागत सामान्य</text><text x=\"60\" y=\"242\">परीक्षण-विज्ञापन</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"160\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><text x=\"400\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">चरण-2 भीड़</text><text x=\"310\" y=\"190\">1-2 हफ़्ते + त्योहार</text><text x=\"310\" y=\"216\">लागत बढ़ी</text><text x=\"310\" y=\"242\">सबसे अच्छा creative चले</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"160\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"650\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">चरण-3 बाद</text><text x=\"560\" y=\"190\">त्योहार के बाद</text><text x=\"560\" y=\"216\">लागत फिर गिरती है</text><text x=\"560\" y=\"242\">स्टॉक-साफ़ी मौक़ा</text>\n</g>\n<rect x=\"60\" y=\"310\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"345\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">COD बनाम UPI-ग्राहक</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"380\">COD — जल्दी फ़ैसला, ज़्यादा रद्द-दर</text>\n<text x=\"90\" y=\"410\">UPI — सोच-समझकर, कम रद्द-दर, पक्का ग्राहक</text>\n</g>\n<rect x=\"60\" y=\"480\" width=\"680\" height=\"130\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"515\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">रचना-ताज़गी — Ad fatigue से बचें</text>\n<text x=\"400\" y=\"550\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">एक ही creative लंबे समय न चलाएँ</text>\n<text x=\"400\" y=\"580\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">हर 3-4 दिन हल्का बदलाव — नई फ़ोटो/caption</text>\n<rect x=\"60\" y=\"630\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"670\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#2E7D32\">चार-हफ़्ते योजना: तैयारी→चुनाव→पूरा-बजट→बाद-में-सफ़ाई</text>\n<text x=\"400\" y=\"698\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">सेवा-सहायक की सबसे मूल्यवान मौसमी सेवा</text>\n</svg>\n```\n\n## एक असली दिवाली-कहानी\nमान लो पटना की मसाला-कंपनी दिवाली की तैयारी करती है। हफ़्ता-1 में तीन Reel बनाए (मिठाई-मसाला, गिफ़्ट-पैक, त्योहार-थाली) और ₹40/दिन के छोटे परीक्षण-विज्ञापन से देखा कौन-सा सबसे ज़्यादा चैट लाता है — गिफ़्ट-पैक वाला जीता। हफ़्ता-3 (त्योहार-भीड़) में पूरा बजट (₹200/दिन) गिफ़्ट-पैक-Reel पर, पर हर तीन दिन में फ़ोटो का कोण बदला ताकि थकान न आए। परिणाम — पिछले साल के मुक़ाबले 40% ज़्यादा चैट, और CPM बढ़ने के बावजूद, क्योंकि पहले से तैयार सबसे-असरदार creative के साथ भीड़ के समय में उतरे। यह चार-हफ़्ते की योजना का असली फ़ायदा है — बिना योजना के त्योहार में कूदने वाली दुकानों के मुक़ाबले काफ़ी बेहतर नतीजा।\n\n## 3. आज का काम «काम-कार्ड»\nआगे आने वाले किसी त्योहार के लिए चार-हफ़्ते की योजना बनाइए — हर हफ़्ते क्या काम, कौन-सा creative, बजट कैसे बदलेगा। COD/UPI ग्राहकों के लिए अपनी दुकान की सोच लिखिए — किसे कितनी प्राथमिकता देंगे। रचना-ताज़गी के लिए कम-से-कम तीन अलग creative-विचार (फ़ोटो/caption के मोटे विषय) सूचीबद्ध कीजिए। जाँच-सूची: ☐ चार-हफ़्ते योजना ☐ COD/UPI सोच ☐ तीन creative-विचार ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — पिछले साल के त्योहार का कोई भी पुराना data (चाहे हाथ से लिखा हो) अगर हो, तो इस साल की योजना बनाते समय ज़रूर देखें — पिछले नतीजे इस साल की उम्मीदों को यथार्थवादी बनाते हैं।\n\n## 4. नाप\nसफल = योजना व्यावहारिक (हर हफ़्ते ठोस काम, टालमटोल नहीं); creative-विचार असली उत्पाद से जुड़े। समय: 30 मिनट।\n\nअगली बार त्योहार आने पर यह पन्ना अपडेट होकर एक बढ़ता हुआ अनुभव-भंडार बनेगा, हर साल पिछले साल से बेहतर योजना संभव होगी।\n\n## 5. सबूत\nसबूत-खाते में \"त्योहार-योजना पन्ना\"। यह पोर्टफ़ोलियो में एक मौसमी-रणनीति सेवा के नमूने के रूप में जाएगा।\n\nAI से यह भी पूछा जा सकता है — 'इस साल (त्योहार-नाम) कब है और आम तौर पर इससे कितने हफ़्ते पहले लोग ख़रीदारी शुरू करते हैं' — यह योजना की समय-सीमा तय करने में मदद करता है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"भारतीय त्योहार-सीज़न में छोटी दुकान के लिए Meta Ads की चार-हफ़्ते की योजना बनाओ, ताकि विज्ञापन-लागत में बढ़त से बचा जा सके।\" — जवाब मिलाइए अपनी योजना से।\n\n## 7. आम ग़लती\nपहली — त्योहार के बीच में नया प्रयोग शुरू करना, जब लागत पहले से ज़्यादा है और ग़लती की क़ीमत भी ज़्यादा। दूसरी — एक ही creative पूरे त्योहार-चक्र में चलाना — थकान से नतीजा गिरता है। तीसरी — COD की ज़्यादा रद्द-दर को unit-economics में न जोड़ना — मुनाफ़ा-हिसाब ग़लत निकलता है। चौथी — त्योहार के तुरंत बाद सब कुछ अचानक बंद कर देना — बचे स्टॉक और अगले छोटे मौक़ों की उपेक्षा।\n\nत्योहार के हड़बड़ी भरे दिनों में भी ऑर्डर-पुष्टि और भुगतान-जाँच में जल्दबाज़ी न करें — यही समय है जब सबसे ज़्यादा COD-धोखे होते हैं (पाठ-70)।\n\n## 8. सुरक्षा-पत्रक\nत्योहार-offer में \"सीमित स्टॉक\" या \"सिर्फ़ आज\" जैसे दावे सिर्फ़ तभी लिखें जब सच हों (पाठ-92 का नियम यहाँ भी) — त्योहार में यह ग़लती सबसे ज़्यादा होती है और सबसे तेज़ी से पकड़ी जाती है। भीड़ में जल्दबाज़ी करते हुए COD-ऑर्डर की पुष्टि-कॉल/संदेश न छोड़ें, धोखे का जोखिम इसी समय बढ़ता है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। त्योहार-कैलेंडर व विज्ञापन-लागत के रुझान साल-दर-साल थोड़े बदलते हैं। 📎 मूल-कोर्स-कड़ी: Meta Ads — Seasonal Advertising गाइड — https://www.facebook.com/business/help/seasonal-advertising — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=seasonal-ad-planning · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं त्योहार-मूल्य-चक्र के तीन चरण बता सकता हूँ।\n- [ ] मैं COD और UPI-ग्राहक के व्यवहार में फ़र्क़ जानता हूँ।\n- [ ] मैं Ad fatigue (रचना-थकान) को पहचान सकता हूँ।\n- [ ] मैंने चार-हफ़्ते की त्योहार-योजना बनाई है।\n- [ ] मैं जानता हूँ झूठा \"सिर्फ़ आज\" दावा क्यों नहीं लिखना।",
 "98": "═\n# पाठ-98: AI से विज्ञापन-रचना — मसौदा AI, सच अपना, disclosure\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nपाठ-97 में रचना-ताज़गी के लिए कई creative चाहिए थे — AI यहाँ समय बचाता है। पाठ के बाद आप तीन बातें कर पाएँगे — AI से विज्ञापन-caption/फ़ोटो-सुझाव कैसे लें, समझ पाएँगे; \"मसौदा AI, सच अपना\" के सिद्धांत को लागू कर पाएँगे; और disclosure (AI-उपयोग की सूचना) के नियम जान पाएँगे।\n\n## 2. मुख्य बात\nहमने पाठ-15-16 में AI से फ़ोटो-सुधार और पाठ-90 में Reel-पटकथा में AI का उपयोग देखा। एक-वाक्य बात — **AI विज्ञापन-caption, वीडियो-पटकथा, यहाँ तक कि पूरी तस्वीर का मसौदा बहुत तेज़ी से बना सकता है — पर हर दावा, हर आँकड़ा, हर तस्वीर का सच आपकी अपनी ज़िम्मेदारी है, और अगर AI-निर्मित तस्वीर/वीडियो उपयोग करें तो disclosure (सूचना) ज़रूरी हो सकती है।**\n\n## मसौदा AI, सच अपना — पहले भी सीखा, यहाँ दोहराव क्यों\nपाठ-16 में हमने AI-निर्मित lifestyle-चित्र को कभी उत्पाद-दावे के तौर पर न इस्तेमाल करने का नियम सीखा था। विज्ञापन में यह जोखिम और बड़ा है — क्योंकि विज्ञापन पैसा देकर ज़्यादा लोगों तक पहुँचता है, इसलिए ग़लत दावे का असर भी बड़ा होता है, और Meta की नीति (पाठ-100) भी विज्ञापन-दावों पर सख़्त निगरानी रखती है। इसलिए यहाँ नियम दोहराना ज़रूरी है — AI caption लिख सकता है, पर उसमें लिखे \"सबसे सस्ता\", \"100% असली\", \"गारंटी\" जैसे शब्द तभी रहें जब आप उन्हें सच साबित कर सकें।\n\n## caption-लेखन में AI का सही उपयोग\nAI से तीन तरह की मदद उपयोगी है — **कई विकल्प:** एक ही उत्पाद के लिए पाँच अलग caption-शैली माँगना (मज़ेदार, गंभीर, सवाल-आधारित, कहानी-शैली) — फिर सबसे अच्छा चुनना या मिलाना। **भाषा-सुधार:** अपना लिखा हुआ मसौदा AI से व्याकरण/प्रवाह के लिए सुधरवाना, अर्थ बदले बिना। **छोटा करना:** लंबे विवरण को विज्ञापन-लायक़ छोटे, दमदार वाक्य में बदलना। जो AI कभी न करे — असली-न-मौजूद फ़ायदे, नक़ली ग्राहक-प्रशंसा (testimonial), या ग़लत आँकड़े जोड़ना — यह सब आपकी अपनी जाँच से गुज़रे बिना विज्ञापन में न जाए।\n\n## disclosure — AI-निर्मित सामग्री की सूचना कब चाहिए\nकुछ प्लेटफ़ॉर्म (Meta सहित) AI-निर्मित या AI-बदली गई फ़ोटो/वीडियो पर एक छोटा \"AI-सहायता से बना\" जैसा निशान (label) माँग सकते हैं, ख़ासकर अगर बदलाव बड़ा हो (जैसे पूरी तरह नक़ली दृश्य)। सादा text-caption के लिए आमतौर पर disclosure ज़रूरी नहीं होती, पर बड़े दृश्य-परिवर्तन (जैसे पूरी तरह AI-बनाई तस्वीर, असली फ़ोटो नहीं) के लिए Meta के advertising-नीति पन्ने ज़रूर जाँचें — यह नियम Δ है, तेज़ी से बदल रहा है क्योंकि AI-सामग्री हाल ही में बढ़ी है।\n\n## AI-रचना और unique-पन (originality) — क्यों ज़रूरी\nअगर AI से बना caption बिल्कुल किसी और दुकान के विज्ञापन जैसा लगे (क्योंकि वही AI, वही तरीक़े से पूछा गया), तो यह न सिर्फ़ पहचान कमज़ोर करता है बल्कि कभी-कभी नक़ल जैसा भी लग सकता है। इसलिए AI का मसौदा हमेशा अपनी दुकान की असली आवाज़ (अपने शब्द, अपना अंदाज़, अपने ग्राहक की भाषा) में ढालकर उपयोग करें — यह वही \"मसौदा AI, सच अपना\" सिद्धांत का विस्तार है, अब \"आवाज़ अपनी\" भी जुड़ता है।\n\n## सेवा-सहायक की आँख\n\"AI से पाँच caption-विकल्प + अपनी दुकान की आवाज़ में ढालना + सच्चाई-जाँच\" एक तेज़ और मूल्यवान सेवा है, ख़ासकर त्योहार-सीज़न में जब बहुत सारे creative चाहिए (पाठ-97)। AI तेज़ करता है, पर जाँच का काम इंसान का ही रहता है।\n\n## चित्र — AI-मसौदा से सच्चे विज्ञापन तक\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">AI से विज्ञापन-रचना — मसौदा AI, सच अपना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">तेज़ी AI से, ज़िम्मेदारी हमेशा आपकी</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><text x=\"150\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">कई विकल्प</text><text x=\"60\" y=\"190\">पाँच caption-शैली</text><text x=\"60\" y=\"216\">सबसे अच्छा चुनें</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"400\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">भाषा-सुधार</text><text x=\"310\" y=\"190\">व्याकरण-प्रवाह</text><text x=\"310\" y=\"216\">अर्थ न बदले</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"650\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">छोटा करना</text><text x=\"560\" y=\"190\">लंबा → दमदार</text><text x=\"560\" y=\"216\">विज्ञापन-लायक़</text>\n</g>\n<rect x=\"60\" y=\"300\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"335\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">AI कभी न जोड़े</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"370\">असली-न-मौजूद फ़ायदे · नक़ली ग्राहक-प्रशंसा</text>\n<text x=\"90\" y=\"400\">ग़लत आँकड़े — सब आपकी अपनी जाँच से गुज़रे</text>\n</g>\n<rect x=\"60\" y=\"470\" width=\"680\" height=\"120\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"505\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">disclosure — बड़े दृश्य-परिवर्तन पर सूचना ज़रूरी हो सकती है</text>\n<text x=\"400\" y=\"540\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">यह Δ-नियम है — Meta के advertising-नीति पन्ने पर जाँचें</text>\n<text x=\"400\" y=\"568\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">सादा text-caption में आमतौर पर ज़रूरी नहीं</text>\n<rect x=\"60\" y=\"610\" width=\"680\" height=\"80\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"650\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#2E7D32\">AI-मसौदे को अपनी दुकान की आवाज़ में ढालें — नक़ल न लगे</text>\n</svg>\n```\n\n## एक तुलना — AI-मसौदा बनाम अंतिम caption\nमान लो AI ने पहला मसौदा दिया — \"यह साड़ी दुनिया की सबसे सुंदर साड़ी है, हर कोई इसे पसंद करेगा, आज ही ऑर्डर करें वरना पछताएँगे!\" यह पढ़ते ही तीन झंडे उठते हैं — \"दुनिया की सबसे सुंदर\" गढ़ा दावा, \"हर कोई पसंद करेगा\" असंभव वादा, \"वरना पछताएँगे\" डर पैदा करने वाली भाषा। इसे अपनी आवाज़ में ढालकर सच्चा रूप बनता है — \"हाथ से बुनी नीली सूती साड़ी, ₹800 में। खगड़िया की हमारी दुकान से — WhatsApp पर पूछें।\" यह छोटा उदाहरण दिखाता है कि AI की रफ़्तार और इंसानी ईमानदारी का साथ मिलकर ही सही विज्ञापन बनता है — कोई एक अकेला काफ़ी नहीं।\n\n## 3. आज का काम «काम-कार्ड»\nअपने किसी उत्पाद के लिए AI से पाँच caption-विकल्प माँगिए (अलग-अलग शैली)। हर एक को पढ़कर जाँचिए — कोई गढ़ा दावा तो नहीं? फिर सबसे अच्छे को अपनी दुकान की भाषा में ढालकर अंतिम caption लिखिए। नीचे लिखिए — क्या इसमें कोई AI-निर्मित तस्वीर उपयोग होगी, अगर हाँ तो disclosure की ज़रूरत जाँची या नहीं। जाँच-सूची: ☐ पाँच AI-caption-विकल्प ☐ सच्चाई-जाँच हर एक पर ☐ अंतिम caption अपनी आवाज़ में ☐ disclosure-जाँच नोट ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — AI से माँगे caption की भाषा-शैली को समय-समय पर बदलते रहें (कभी सवाल-आधारित, कभी कहानी-शैली) ताकि दुकान का विज्ञापन-अंदाज़ नीरस न लगे और ग्राहक की दिलचस्पी बनी रहे।\n\n## 4. नाप\nसफल = अंतिम caption AI के मसौदे से अलग महसूस हो (अपनी आवाज़ में); कोई गढ़ा दावा न बचे। समय: 25 मिनट।\n\nजमा किए गए पाँच AI-मसौदे भी सुरक्षित रखें — भविष्य में किसी और उत्पाद के लिए भाषा-शैली दोबारा उपयोग करने के काम आ सकते हैं।\n\n## 5. सबूत\nसबूत-खाते में \"AI-caption मसौदा व अंतिम संस्करण\"। यह दिखाता है कि AI-सहायता के बावजूद अंतिम जाँच इंसानी थी।\n\nएक और उपयोगी सवाल — AI से पूछें 'यह caption किसी भी नामंज़ूरी-कारण से टकराता है क्या' — यह पाठ-100 के नियमों की एक शुरुआती जाँच के रूप में काम कर सकता है, अंतिम जाँच फिर भी अपनी।\n\n## 6. AI-सहायक\nयह पूरा पाठ ही AI-सहायक के उपयोग पर है — फिर भी याद रखें, AI से पूछते समय हमेशा असली उत्पाद-जानकारी (सच्चा दाम, सच्ची विशेषता) दें, ताकि मसौदा शुरू से भटका हुआ न हो।\n\n## पाँचवीं ग़लती और सुधार\nपाँचवीं आम ग़लती — AI से एक ही बार में पूरा \"अंतिम\" caption माँगना और उसे बिना विकल्प तुलना किए स्वीकार कर लेना। सबसे अच्छे नतीजे तब आते हैं जब पाँच-छह विकल्प माँगे जाएँ और उनमें से सबसे अच्छे हिस्से मिलाकर अंतिम संस्करण बनाया जाए — यह वैसा ही है जैसे कारीगर कई नमूनों में से सबसे अच्छा चुनता है, पहला ही स्वीकार नहीं करता।\n\n## 7. आम ग़लती\nपहली — AI का पहला मसौदा बिना पढ़े सीधे विज्ञापन में डाल देना। दूसरी — AI से मिला बढ़ा-चढ़ाया दावा (\"नंबर-1\", \"सबसे बेहतरीन\") बिना सबूत के रख लेना। तीसरी — सभी उत्पादों के caption एक ही AI-शैली में छोड़ देना — दुकान की अपनी पहचान खो जाती है। चौथी — बड़े दृश्य-परिवर्तन वाली AI-तस्वीर बिना disclosure-जाँच के उपयोग करना।\n\nAI-मसौदा-प्रक्रिया में अपनी दुकान की गोपनीय जानकारी (जैसे असली लागत, आपूर्तिकर्ता का नाम) कभी शामिल न करें, सिर्फ़ ग्राहक-सामने वाली जानकारी दें।\n\n## 8. सुरक्षा-पत्रक\nAI को कभी ग्राहक की निजी बातचीत या डेटा न दें (सिर्फ़ उत्पाद-जानकारी) — पाठ-51 का \"कभी-नहीं सूची\" नियम यहाँ भी। AI-निर्मित तस्वीर में कभी असली, पहचान-योग्य किसी वास्तविक इंसान का चेहरा न बनाएँ बिना उसकी सहमति के।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। AI-सामग्री disclosure-नियम तेज़ी से बदल रहे हैं (Δ)। 📎 मूल-कोर्स-कड़ी: Meta Advertising Policies — AI-Generated Content — https://www.facebook.com/policies/ads — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-assisted-ad-copywriting · platform=meta · level=S · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं \"मसौदा AI, सच अपना\" सिद्धांत को विज्ञापन पर लागू कर सकता हूँ।\n- [ ] मैंने पाँच AI-caption-विकल्प माँगकर एक चुना है।\n- [ ] मैं जानता हूँ disclosure कब ज़रूरी हो सकती है।\n- [ ] मैं जानता हूँ AI-मसौदे को अपनी आवाज़ में क्यों ढालना है।\n- [ ] मैं जानता हूँ AI को क्या जानकारी कभी नहीं देनी।",
 "99": "═\n# पाठ-99: नतीजा पढ़ना — CPM, CPC, ROAS, लौटा ग्राहक\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nविज्ञापन चलाना आधा काम है; बचा आधा — Ads Manager की रिपोर्ट पढ़ना। पाठ के बाद आप तीन बातें कर पाएँगे — चार बुनियादी नाप (CPM, CPC, ROAS, लौटा ग्राहक) समझ पाएँगे; अपनी दुकान के लिए इनकी असली गणना कर पाएँगे; और नतीजों से अगला फ़ैसला ले पाएँगे।\n\n## 2. मुख्य बात\nपाठ-97-98 में हमने योजना और सामग्री तैयार की; अब उसका असर नापने की बारी। एक-वाक्य बात — **CPM बताता है \"हज़ार बार दिखाने में कितना ख़र्च\", CPC बताता है \"एक क्लिक/चैट में कितना ख़र्च\", ROAS बताता है \"एक रुपये के विज्ञापन से कितने रुपये की बिक्री\", और लौटा ग्राहक बताता है कि आपकी असली सफलता सिर्फ़ पहली बिक्री नहीं, दोबारा आना है।**\n\n## चार नाप — सादी परिभाषा\n**CPM (Cost Per Mille) —** हज़ार बार विज्ञापन दिखाने की लागत। कम CPM का मतलब सस्ते में ज़्यादा लोगों तक पहुँच — त्योहार में यह बढ़ता है (पाठ-97)। **CPC/CPM-per-message —** एक क्लिक या एक चैट-शुरुआत की लागत — Click-to-WhatsApp विज्ञापन (पाठ-96) में यह \"प्रति-चैट लागत\" के रूप में दिखता है। **ROAS (Return on Ad Spend) —** विज्ञापन-ख़र्च के मुक़ाबले बिक्री — अगर ₹1,000 विज्ञापन में ख़र्च हुए और ₹4,000 की बिक्री हुई, ROAS = 4 (यानी हर रुपये पर चार रुपये वापस)। **लौटा ग्राहक (Repeat customer) —** जिसने पहली बार ख़रीदा, क्या वह दोबारा आया? यह attribution-रजिस्टर (पाठ-82) से हाथ से भी ट्रैक किया जा सकता है।\n\n## ROAS का सही पढ़ना — सिर्फ़ ऊँचा नंबर काफ़ी नहीं\nROAS = 4 अच्छा लगता है, पर पाठ-67 का unit-economics याद कीजिए — अगर उत्पाद का मार्जिन ही कम हो (मान लो बिक्री-मूल्य का 20%), तो ROAS = 4 का मतलब है विज्ञापन-ख़र्च मार्जिन का 25% खा गया, जो शायद ज़्यादा ही हो। **सही सवाल ROAS नहीं, बल्कि \"क्या असली मुनाफ़ा बचा\" है** — यह पाठ-101 में unit-economics के साथ पूरी तरह जुड़ेगा। अभी सिर्फ़ इतना याद रखिए — ROAS एक शुरुआती संकेत है, आख़िरी फ़ैसला नहीं।\n\n## Click-to-WhatsApp का ख़ास नाप — चैट-से-बिक्री दर\nसाधारण e-commerce में ROAS सीधे Meta दिखाता है (Pixel से)। WhatsApp-केंद्रित दुकान के लिए यह हाथ से जोड़ना पड़ता है — Ads Manager से \"कितनी चैट शुरू हुईं\" (और उनकी लागत) लीजिए, attribution-रजिस्टर (पाठ-82) से \"कितनी बिकीं\" लीजिए। **चैट-से-बिक्री दर = बिकी संख्या ÷ चैट संख्या × 100।** मान लो 40 चैट में 8 बिकीं — 20% दर। यह दर हफ़्ते-दर-हफ़्ते तुलना के लिए एक अच्छा नाप है, भले Meta सीधे ROAS न दिखाए।\n\n## नतीजों से फ़ैसला — तीन दिशा\n**बढ़ाएँ —** अगर चैट-से-बिक्री दर अच्छी हो और मुनाफ़ा बचता हो, बजट थोड़ा-थोड़ा बढ़ाएँ (एक साथ दुगना नहीं, धीरे-धीरे)। **बदलें —** अगर CPM ठीक हो पर चैट कम आएँ, creative/caption बदलें (पाठ-98)। अगर चैट तो आएँ पर बिक्री कम हो, DM/WhatsApp-जवाब की गुणवत्ता जाँचें (पाठ-91 जैसा) — शायद विज्ञापन का दोष नहीं, बातचीत का। **रोकें —** अगर लगातार दो-तीन हफ़्ते मुनाफ़ा न बने, विज्ञापन रोककर वापस मुफ़्त-सूचना-सीढ़ी (पाठ 86-92) पर टिकें, फिर नए सिरे से छोटे बजट से शुरू करें।\n\n## सेवा-सहायक की आँख\n\"हफ़्तावार नतीजा-रिपोर्ट — CPM, चैट-संख्या, चैट-से-बिक्री दर, अगला फ़ैसला\" एक सीधी, नंबर-आधारित सेवा है जो दुकानदार को साफ़ दिखाती है कि पैसा कहाँ जा रहा है। यह पाठ-84 के \"काम-कार्ड\" जैसा ही एक निरंतर अनुशासन है, बस विज्ञापन-केंद्रित।\n\n## चित्र — चार नाप, एक साथ पढ़ना\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">नतीजा पढ़ना — चार बुनियादी नाप</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">CPM · चैट-लागत · ROAS · लौटा ग्राहक</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"205\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">CPM</text><text x=\"60\" y=\"190\">हज़ार दिखावे की लागत</text><text x=\"60\" y=\"216\">त्योहार में बढ़ता है</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"120\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><text x=\"595\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">चैट-लागत</text><text x=\"450\" y=\"190\">एक चैट-शुरुआत की लागत</text><text x=\"450\" y=\"216\">Click-to-WhatsApp से</text>\n</g>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"260\" width=\"330\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"205\" y=\"295\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#1565C0\">ROAS</text><text x=\"60\" y=\"330\">ख़र्च के बदले बिक्री</text><text x=\"60\" y=\"356\">सिर्फ़ ऊँचा नंबर काफ़ी नहीं</text>\n<rect x=\"430\" y=\"260\" width=\"330\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"595\" y=\"295\" text-anchor=\"middle\" font-weight=\"bold\" fill=\"#2E7D32\">लौटा ग्राहक</text><text x=\"450\" y=\"330\">पहली नहीं, दोबारा आना</text><text x=\"450\" y=\"356\">असली सफलता का नाप</text>\n</g>\n<rect x=\"60\" y=\"410\" width=\"680\" height=\"130\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"445\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">चैट-से-बिक्री दर</text>\n<text x=\"400\" y=\"480\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">बिकी संख्या ÷ चैट संख्या × 100</text>\n<text x=\"400\" y=\"510\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">मान लो 8÷40×100 = 20% — हफ़्ते-दर-हफ़्ते तुलना</text>\n<rect x=\"60\" y=\"560\" width=\"680\" height=\"140\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"595\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">तीन दिशा-फ़ैसले</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"630\">बढ़ाएँ — दर अच्छी, मुनाफ़ा बचता है</text>\n<text x=\"90\" y=\"660\">बदलें — CPM ठीक पर चैट कम/बिक्री कम</text>\n<text x=\"90\" y=\"690\">रोकें — लगातार 2-3 हफ़्ते मुनाफ़ा नहीं</text>\n</g>\n</svg>\n```\n\n## एक पूरा हफ़्ते का हिसाब\nमान लो हफ़्ते भर में ₹350 ख़र्च हुए, विज्ञापन 20,000 बार दिखा (CPM ≈ ₹17.5 प्रति हज़ार), 45 चैट शुरू हुईं (लगभग ₹7.8 प्रति चैट), उनमें से 9 बिकीं (चैट-से-बिक्री दर 20%), हर बिक्री का औसत मूल्य ₹700 यानी कुल बिक्री ₹6,300 (ROAS ≈ 18)। यह आँकड़े दिखने में शानदार लगते हैं, पर पाठ-67 के मार्जिन-सूत्र से जाँचें — अगर मार्जिन 30% है, तो असली मुनाफ़ा ₹1,890 बचा, जिसमें से ₹350 विज्ञापन में गया — फिर भी सकारात्मक, पर उतना नाटकीय नहीं जितना ROAS=18 सुनकर लगता है। यही वजह है कि हर नंबर को अकेले नहीं, मार्जिन के साथ जोड़कर पढ़ना ज़रूरी है।\n\n## 3. आज का काम «काम-कार्ड»\nअगर कोई विज्ञापन चलाया हो (या काल्पनिक अंक लेकर), चार नाप निकालिए — CPM, चैट-संख्या व लागत, चैट-से-बिक्री दर, ROAS (सादा गणित से)। नीचे लिखिए — इन नतीजों से आप \"बढ़ाएँ/बदलें/रोकें\" में से कौन-सा फ़ैसला लेंगे, कारण सहित। जाँच-सूची: ☐ चार नाप गणना सहित ☐ चैट-से-बिक्री दर का सूत्र लगाया ☐ तीन-दिशा में से फ़ैसला कारण सहित ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — हर हफ़्ते के नतीजे एक ही तालिका-ढाँचे में लिखें (CPM-चैट-दर-ROAS एक पंक्ति में) ताकि हफ़्ते-दर-हफ़्ते तुलना करना आसान रहे, अलग-अलग ढंग से लिखे नोट्स की तुलना मुश्किल होती है।\n\n## 4. नाप\nसफल = गणना सही सूत्र से; फ़ैसला नतीजों से निकला, अंदाज़े से नहीं। समय: 30 मिनट।\n\nअगर लगातार कई हफ़्तों का डेटा जमा हो जाए, तो एक साधारण ग्राफ़/रेखा-चित्र (हाथ से भी) बनाकर रुझान देखना बहुत मददगार होता है।\n\n## 5. सबूत\nसबूत-खाते में \"नतीजा-पन्ना व फ़ैसला\"। यह पाठ-101 (unit-economics) व पाठ-102 (मासिक रख-रखाव) में हर बार दोहराया जाने वाला ढाँचा बनेगा।\n\nAI से पूछा जा सकता है 'मेरे इन नंबरों (CPM, चैट-संख्या, बिक्री) से यह campaign अच्छा चला या नहीं' — पर याद रखें, AI सिर्फ़ नंबर पढ़ता है, आपकी दुकान का मार्जिन और संदर्भ उसे नहीं पता जब तक आप न बताएँ।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Meta Ads के CPM, ROAS और चैट-से-बिक्री दर का सादा हिंदी में मतलब और सूत्र समझाओ।\" — जवाब मिलाइए अपनी गणना से।\n\n## पाँचवीं ग़लती और सुधार\nपाँचवीं आम ग़लती — CPM, चैट-लागत और ROAS को अलग-अलग, बिना जोड़े पढ़ना। असली समझ तब बनती है जब तीनों को एक साथ, एक कहानी की तरह पढ़ा जाए — \"CPM बढ़ा इसलिए चैट-लागत भी बढ़ी, फिर भी चैट-से-बिक्री दर स्थिर रही, तो असली समस्या विज्ञापन-लागत नहीं बल्कि सामान्य त्योहार-भीड़ है\" — यह जोड़कर सोचना अकेले-अकेले नंबर देखने से कहीं बेहतर फ़ैसला देता है।\n\n## 7. आम ग़लती\nपहली — सिर्फ़ ROAS का ऊँचा नंबर देखकर ख़ुश हो जाना, मार्जिन से न मिलाना। दूसरी — एक हफ़्ते के नतीजे से पूरा फ़ैसला ले लेना — कम-से-कम दो-तीन हफ़्ते का रुझान देखना बेहतर। तीसरी — CPM बढ़ने पर घबराकर तुरंत विज्ञापन बंद करना, बिना यह देखे कि चैट-से-बिक्री दर अभी भी अच्छी है या नहीं। चौथी — लौटा ग्राहक कभी न गिनना — यह लंबी अवधि की सबसे सस्ती बिक्री है, नज़रअंदाज़ करना नुक़सानदेह।\n\nनतीजा-रिपोर्ट में कभी किसी ग्राहक का नाम-पहचान न लिखें, ख़ासकर अगर रिपोर्ट किसी तीसरे व्यक्ति (जैसे accountant) से साझा हो।\n\n## 8. सुरक्षा-पत्रक\nनतीजा-रिपोर्ट में ग्राहक की निजी जानकारी नहीं, सिर्फ़ गिनतियाँ व राशियाँ। रिपोर्ट दुकानदार को नियमित दिखाएँ — पारदर्शिता सबसे बड़ा भरोसा है, ख़ासकर जब असली पैसा विज्ञापन में लगा हो।\n\nआगे पाठ-101 में यही नतीजे unit-economics के साथ जुड़कर पूरी तस्वीर बनाएँगे — विज्ञापन-सफलता का असली नाप सिर्फ़ नंबर नहीं, बचा हुआ मुनाफ़ा है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Ads Manager — Reporting व Metrics दस्तावेज़ — https://www.facebook.com/business/help/ads-reporting — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ad-performance-analysis · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं CPM, चैट-लागत, ROAS और लौटा-ग्राहक की सादी परिभाषा जानता हूँ।\n- [ ] मैं चैट-से-बिक्री दर का सूत्र लगा सकता हूँ।\n- [ ] मैं जानता हूँ ROAS क्यों सिर्फ़ शुरुआती संकेत है।\n- [ ] मैंने तीन-दिशा में से एक फ़ैसला लिया है।\n- [ ] मैं जानता हूँ लौटा ग्राहक क्यों महत्वपूर्ण नाप है।",
 "100": "═\n# पाठ-100: Meta नीति — अस्वीकृत विज्ञापन, नक़ली दावा, खाता-सुरक्षा\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nजैसे WhatsApp Platform पर ban का ख़तरा था (पाठ-83), Meta Ads का भी अपना नीति-ढाँचा है। पाठ के बाद आप तीन बातें कर पाएँगे — विज्ञापन नामंज़ूर होने के आम कारण पहचान पाएँगे; नक़ली/बढ़ा-चढ़ाकर दावों से बचना सीखेंगे; और अपने विज्ञापन-खाते को सुरक्षित रख पाएँगे।\n\n## 2. मुख्य बात\nपाठ-77 में हमने WhatsApp template-नामंज़ूरी के चार-कदम सुधार सीखे थे। एक-वाक्य बात — **Meta Ads की समीक्षा (review) हर विज्ञापन पर होती है — प्रतिबंधित/जोखिम-श्रेणी (पाठ-12), झूठा दावा, भड़काऊ भाषा, या ग़लत तस्वीर-टेक्स्ट अनुपात जैसे कारणों से नामंज़ूरी आम है, और बार-बार उल्लंघन पूरा विज्ञापन-खाता बंद करवा सकता है।**\n\n## नामंज़ूरी के आम कारण\n1. **प्रतिबंधित/जोखिम-श्रेणी** — पाठ-12 के प्रतिबंधित उत्पाद (शराब, हथियार, नशा, कुछ स्वास्थ्य-दावे) Meta Ads पर या तो पूरी तरह मना हैं या ख़ास अनुमति चाहिए। 2. **झूठे/असंभव दावे** — \"रातों-रात अमीर बनें\", \"100% गारंटी\", चिकित्सा-दावे बिना प्रमाण के। 3. **before-after तस्वीरें बिना संदर्भ** — ख़ासकर स्वास्थ्य/सौंदर्य उत्पादों में, भ्रामक लग सकती हैं। 4. **व्यक्तिगत विशेषताओं पर सीधा हमला** — \"क्या आप मोटे हैं?\" जैसी भाषा जो सीधे व्यक्ति की कमी की ओर इशारा करे, निषिद्ध है। 5. **तकनीकी कारण** — फ़ोटो पर बहुत ज़्यादा टेक्स्ट, धुंधली गुणवत्ता, ग़लत आकार-अनुपात।\n\n## नक़ली दावा — कहाँ रेखा खींचें\n\"बेहतरीन साड़ी\" जैसा राय-आधारित वाक्य समस्या नहीं है (यह स्वाभाविक विज्ञापन-भाषा है)। समस्या तब है जब दावा तथ्य जैसा लगे पर सच न हो — \"यह पूरे बिहार में सबसे सस्ता दाम है\" (बिना जाँचे), \"डॉक्टरों की पहली पसंद\" (बिना प्रमाण)। सरल परख — **\"क्या मैं यह दावा किसी को सबूत के साथ साबित कर सकता हूँ?\"** — नहीं, तो विज्ञापन से हटाएँ। यह पाठ-16 का \"गढ़ा दावा\" नियम है, विज्ञापन के बड़े मंच पर।\n\n## नामंज़ूरी आए तो — पाठ-77 जैसा ही चार-कदम\n1. कारण पढ़ें (Ads Manager में साफ़ बताया जाता है)। 2. अपने विज्ञापन में वह हिस्सा ढूँढें जो नियम से टकराता है। 3. सुधारकर दोबारा जमा करें (या पूरी तरह नया विज्ञापन बनाएँ अगर कारण गंभीर हो)। 4. बार-बार वही ग़लती न दोहराएँ — Meta पैटर्न पकड़ता है, बार-बार उल्लंघन खाता-सुरक्षा को प्रभावित करता है (नीचे विस्तार)।\n\n## खाता-सुरक्षा — Ads खाता कैसे बचाएँ\nBusiness Manager पर दो-कदम-सत्यापन (पाठ-10) अनिवार्य। भुगतान-विधि (कार्ड/UPI) सिर्फ़ दुकान-मालिक के नाम पर, कभी किसी \"एजेंसी\" को सीधे कार्ड-नंबर न दें — Business Manager के भीतर \"Partner Access\" से नियंत्रित पहुँच दें, यह किसी भी वक़्त हटाई जा सकती है। कोई भी email/SMS जो \"आपका Ads-खाता suspended है, यहाँ क्लिक करें\" कहे, सीधे क्लिक न करें — सीधे facebook.com/business में जाकर स्थिति जाँचें, यह धोखे की सबसे आम तकनीक है (2026 में बहुत बढ़ी हुई)।\n\n## सेवा-सहायक की आँख\n\"नामंज़ूरी-सुधार सेवा + खाता-सुरक्षा जाँच (हर महीने Partner Access, दो-कदम-सत्यापन)\" एक भरोसे की सेवा है। दुकानदार को धोखे वाले email/SMS की पहचान सिखाना भी आपकी ज़िम्मेदारी है — यह उनकी सुरक्षा और आपकी सेवा दोनों को मज़बूत करता है।\n\n## चित्र — नामंज़ूरी के कारण व खाता-सुरक्षा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta नीति — नामंज़ूरी व खाता-सुरक्षा</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">\"क्या मैं यह दावा साबित कर सकता हूँ?\"</text>\n<rect x=\"60\" y=\"120\" width=\"680\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">नामंज़ूरी के पाँच आम कारण</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"190\">1. प्रतिबंधित/जोखिम-श्रेणी</text>\n<text x=\"90\" y=\"220\">2. झूठे/असंभव दावे (\"गारंटी\", \"रातों-रात\")</text>\n<text x=\"90\" y=\"250\">3. before-after बिना संदर्भ</text>\n<text x=\"90\" y=\"280\">4. व्यक्तिगत कमियों पर सीधा हमला</text>\n<text x=\"90\" y=\"310\">5. तकनीकी — ज़्यादा टेक्स्ट, धुंधली फ़ोटो</text>\n</g>\n<rect x=\"60\" y=\"360\" width=\"680\" height=\"130\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"395\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">नामंज़ूरी पर चार-कदम (पाठ-77 जैसा)</text>\n<text x=\"400\" y=\"428\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">कारण पढ़ें → टकराव ढूँढें → सुधारें → दोहराव-रोकें</text>\n<text x=\"400\" y=\"458\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">बार-बार उल्लंघन खाता-सुरक्षा प्रभावित करता है</text>\n<rect x=\"60\" y=\"510\" width=\"680\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"545\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#2E7D32\">खाता-सुरक्षा</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"580\">दो-कदम-सत्यापन अनिवार्य</text>\n<text x=\"90\" y=\"610\">भुगतान-विधि मालिक के नाम, Partner Access से नियंत्रित</text>\n<text x=\"90\" y=\"640\">\"suspended\" email/SMS पर क्लिक नहीं — सीधे facebook.com/business जाएँ</text>\n</g>\n</svg>\n```\n\n## एक असली नामंज़ूरी-कहानी\nमान लो एक दुकान ने अपने आयुर्वेदिक तेल का विज्ञापन बनाया — \"यह तेल सिर दर्द को जड़ से ख़त्म करता है, डॉक्टर भी हैरान हैं!\" यह विज्ञापन नामंज़ूर हुआ — कारण: स्वास्थ्य-दावा बिना प्रमाण, और \"डॉक्टर हैरान\" जैसी अतिशयोक्ति। दुकानदार ने सुधारा — \"पारंपरिक नुस्ख़े से बना तेल, सिर की मालिश के लिए। असर व्यक्ति-अनुसार अलग हो सकता है।\" यह संस्करण मंज़ूर हुआ, क्योंकि अब कोई पक्का चिकित्सा-दावा नहीं, सिर्फ़ ईमानदार वर्णन। यही फ़र्क़ है — पहला विज्ञापन ग्राहक को गुमराह करने की कोशिश करता दिखा, दूसरा सिर्फ़ उत्पाद का सच्चा परिचय देता है।\n\nएक अतिरिक्त सोच — नीति-पालन को बोझ नहीं, बल्कि अपनी दुकान की गुणवत्ता का प्रमाण मानिए; जो दुकान सच्ची जानकारी देती है, उसके लिए Meta की नीति कोई रुकावट नहीं बनती, बल्कि प्रतियोगिता में उसे नक़ली-दावेदारों से अलग खड़ा करती है।\n\n## 3. आज का काम «काम-कार्ड»\nअपने पाठ-98 के caption/विज्ञापन-मसौदे को पाँच नामंज़ूरी-कारणों पर दोबारा जाँचिए — कोई टकराव तो नहीं? \"क्या मैं यह दावा साबित कर सकता हूँ?\" सवाल हर बड़े दावे पर लगाइए। खाता-सुरक्षा की एक चेक-सूची बनाइए — दो-कदम-सत्यापन, भुगतान-नियंत्रण, संदिग्ध email की पहचान। जाँच-सूची: ☐ पाँच-कारण जाँच पुराने मसौदे पर ☐ दावा-साबित-परख हर बड़े दावे पर ☐ खाता-सुरक्षा चेक-सूची ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — कोई भी बड़ा दावा लिखने से पहले ख़ुद से पूछें 'अगर कोई ग्राहक इसे चुनौती दे, तो मैं क्या सबूत दिखाऊँगा' — अगर जवाब न मिले, दावा हटा दें, यह सबसे तेज़ आत्म-जाँच है।\n\n## 4. नाप\nसफल = कोई भी दावा जो साबित न हो सके, हटाया/सुधारा गया; सुरक्षा-सूची पूरी। समय: 25 मिनट।\n\nयह जाँच-आदत हर नए विज्ञापन से पहले दोहराई जानी चाहिए, न कि सिर्फ़ नामंज़ूरी के बाद — रोकथाम इलाज से बेहतर है।\n\n## 5. सबूत\nसबूत-खाते में \"नीति-जाँच व सुरक्षा-सूची पन्ना\"। यह हर नए विज्ञापन से पहले दोहराई जाने वाली आदत बनेगी।\n\nAI से 'यह विज्ञापन-टेक्स्ट Meta की नीति से टकरा सकता है क्या' पूछना एक अच्छी पहली-जाँच है, पर आख़िरी भरोसा हमेशा Meta के आधिकारिक नीति-पन्ने और असली Ads Manager के review-नतीजे पर रखें।\n\nएक और उपयोगी अभ्यास — किसी पुराने विज्ञापन (अपने या किसी और के, सार्वजनिक रूप से देखे) को AI के सामने रखकर पूछें 'इसमें कोई नीति-टकराव दिख रहा है क्या' — यह असली उदाहरणों से सीखने का एक तेज़ तरीक़ा है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"Meta Ads पर आम तौर पर कौन-से विज्ञापन नामंज़ूर होते हैं और क्यों?\" — जवाब मिलाइए अपनी पाँच-कारण सूची से; असली नीति-पन्ना ज़्यादा भरोसेमंद है।\n\n## 7. आम ग़लती\nपहली — नामंज़ूरी को \"ग़लती से हुआ\" मानकर बार-बार वही विज्ञापन बिना सुधार दोबारा जमा करना — इससे खाता-सुरक्षा और बिगड़ती है। दूसरी — राय-वाक्य (\"बेहतरीन\") और तथ्य-दावा (\"सबसे सस्ता\") में फ़र्क़ न समझना। तीसरी — किसी \"agency\" या email को सीधे भुगतान-कार्ड नंबर दे देना। चौथी — suspended-चेतावनी वाले नक़ली email/SMS पर घबराकर तुरंत क्लिक करना।\n\n## 8. सुरक्षा-पत्रक\nBusiness Manager की Partner Access सूची हर महीने जाँचें — कोई पुराना/अनजान सहायक अभी भी पहुँच रखे हो तो हटाएँ। कभी भी अपना Facebook/Meta पासवर्ड किसी को SMS/email/फ़ोन पर न बताएँ, असली Meta कभी इस तरह नहीं माँगता।\n\nअगला पाठ-101 इसी नीति-समझ को मुनाफ़े के हिसाब से जोड़ेगा — एक सुरक्षित, मंज़ूर विज्ञापन भी तभी सार्थक है जब वह वाक़ई मुनाफ़ा लाए।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Advertising Policies पूरा दस्तावेज़ — https://www.facebook.com/policies/ads — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ad-policy-compliance-and-account-security · platform=meta · level=S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=02/2027)\n\nनिष्कर्ष यह है कि Meta की नीति कोई मनमानी रुकावट नहीं है — यह ग्राहकों को धोखे से बचाने के लिए है, और जो दुकान शुरू से ईमानदार रहती है, उसे नामंज़ूरी की चिंता कभी नहीं करनी पड़ती।\n\nखंड-7 के आख़िरी तीन पाठों (101-103) में हम इसी नीति-समझ को मुनाफ़े और मासिक-अनुशासन के साथ पूरी तरह जोड़ेंगे, ताकि खंड-7 का पूरा सफ़र एक ठोस, व्यावहारिक ढाँचे में बंध जाए।\n\n## 10. योग्यता-जाँच\n- [ ] मैं नामंज़ूरी के पाँच आम कारण बता सकता हूँ।\n- [ ] मैं \"दावा साबित कर सकता हूँ या नहीं\" की परख लगा सकता हूँ।\n- [ ] मैंने अपना पुराना caption पाँच-कारण से दोबारा जाँचा है।\n- [ ] मैं खाता-सुरक्षा के तीन ठोस क़दम जानता हूँ।\n- [ ] मैं जानता हूँ suspended-email पर क्लिक क्यों नहीं करना।",
 "101": "═\n# पाठ-101: Meta का unit-economics — विज्ञापन-ख़र्च बनाम मार्जिन\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nपाठ-99 में हमने ROAS को मार्जिन के बिना अधूरा बताया था; आज उसे पूरी तरह जोड़ने की बारी। पाठ के बाद आप तीन बातें कर पाएँगे — Meta-विज्ञापन-ख़र्च को पाठ-67 के unit-economics सूत्र में सही जगह बैठा पाएँगे; असली बचा हुआ मुनाफ़ा (न सिर्फ़ ROAS) निकाल पाएँगे; और यह तय कर पाएँगे कि विज्ञापन-ख़र्च कब बहुत ज़्यादा हो गया है।\n\n## 2. मुख्य बात\nपाठ-67 का सूत्र याद कीजिए — बिक्री-मूल्य से घटती-घटती परतें, आख़िर में Operating Profit। एक-वाक्य बात — **Meta-विज्ञापन-ख़र्च को प्रति-ऑर्डर या प्रति-बिक्री में तोड़कर, सीधे Contribution Margin से घटाना चाहिए — तभी पता चलता है कि विज्ञापन के बाद सचमुच कितना मुनाफ़ा बचा, ROAS का बड़ा नंबर देखकर ख़ुश होना काफ़ी नहीं।**\n\n## विज्ञापन-ख़र्च प्रति-ऑर्डर कैसे निकालें\nसादा गणित — **प्रति-ऑर्डर विज्ञापन-ख़र्च = हफ़्ते/महीने का कुल विज्ञापन-ख़र्च ÷ उसी अवधि में बिकी संख्या।** मान लो महीने में ₹3,000 विज्ञापन में ख़र्च हुए और 30 ऑर्डर बिके — प्रति-ऑर्डर विज्ञापन-ख़र्च = ₹100। अब यह ₹100 पाठ-67 के सूत्र में \"मार्केटिंग-लागत\" की जगह सीधे घटे — Contribution Margin में से।\n\n## एक पूरा उदाहरण — साड़ी का हिसाब\nमान लो साड़ी बिक्री-मूल्य ₹800। इसमें से लागत (कपड़ा-बुनाई) ₹400, मंच-कमीशन (अगर हो) ₹0 (WhatsApp पर सीधी बिक्री), भुगतान-गेटवे शुल्क ₹15 (लगभग 2%), पैकिंग-भाड़ा ₹50 — यहाँ तक Contribution Margin = 800-400-15-50 = ₹335। अब प्रति-ऑर्डर विज्ञापन-ख़र्च ₹100 घटाएँ — बचा ₹235। इसमें से अभी दुकान का किराया/बिजली जैसी स्थिर लागत (अलग से बँटी हुई) घटानी बाक़ी है, पर विज्ञापन के बाद का असली \"प्रति-साड़ी योगदान\" ₹235 है, ₹800 या ROAS का बड़ा नंबर नहीं।\n\n## कब विज्ञापन-ख़र्च \"बहुत ज़्यादा\" — एक सादा सीमा\nएक व्यावहारिक अंगूठा-नियम — **प्रति-ऑर्डर विज्ञापन-ख़र्च, Contribution Margin के 30% से ज़्यादा न हो** (यह सीमा दुकान-दुकान बदल सकती है, पर एक शुरुआती सोच के लिए उपयोगी)। ऊपर के उदाहरण में CM=₹335 का 30% ≈ ₹100 — यानी यह दुकान बिल्कुल सीमा पर है, थोड़ा भी बढ़ा तो नुक़सान की दिशा में जा सकता है। यह गणना हर हफ़्ते दोहराने से समय रहते चेतावनी मिल जाती है।\n\n## दो अलग सोच — नया ग्राहक बनाम लौटा ग्राहक\nपाठ-99 के \"लौटा ग्राहक\" की अहमियत यहीं गणित में दिखती है — पहली बार के ग्राहक पर विज्ञापन-ख़र्च ₹100 लगा हो, पर अगर वही ग्राहक अगले महीने दोबारा (बिना नए विज्ञापन-ख़र्च के) ख़रीदे, तो उस दूसरी बिक्री पर विज्ञापन-ख़र्च शून्य है, यानी Contribution Margin पूरा ₹335 बचता है। इसीलिए लौटा ग्राहक असली मुनाफ़े का सबसे बड़ा स्रोत है — पहली बिक्री विज्ञापन-ख़र्च से \"उधार\" चुकाती है, दूसरी बिक्री शुद्ध कमाई। यह ग्राहक-सेवा (पाठ-91 का DM-जवाब, पाठ-84 का रख-रखाव) को सीधे पैसे से जोड़ता है।\n\n## सेवा-सहायक की आँख\n\"विज्ञापन-ख़र्च प्रति-ऑर्डर + असली बचा मुनाफ़ा + 30%-सीमा जाँच\" — यह सेवा दुकानदार को वह सच दिखाती है जो सिर्फ़ ROAS का नंबर छुपा देता है। यही आपको उन \"ज़्यादा ROAS दिखाओ\" वाली agency से अलग करता है जो असली मार्जिन कभी नहीं जाँचतीं।\n\n## चित्र — विज्ञापन-ख़र्च का असली स्थान\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta का unit-economics — साड़ी का असली हिसाब</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बिक्री-मूल्य ₹800 से घटती परतें</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"115\" width=\"680\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"2\"/><text x=\"60\" y=\"150\">बिक्री-मूल्य ₹800</text>\n<rect x=\"40\" y=\"180\" width=\"680\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"2\"/><text x=\"60\" y=\"215\">− लागत ₹400 − gateway ₹15 − पैकिंग ₹50</text>\n<rect x=\"40\" y=\"245\" width=\"680\" height=\"55\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"60\" y=\"280\" font-weight=\"bold\">= Contribution Margin ₹335</text>\n<rect x=\"40\" y=\"310\" width=\"680\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"2\"/><text x=\"60\" y=\"345\">− विज्ञापन-ख़र्च प्रति-ऑर्डर ₹100</text>\n<rect x=\"40\" y=\"375\" width=\"680\" height=\"55\" rx=\"10\" fill=\"#2E7D32\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"60\" y=\"410\" font-weight=\"bold\" fill=\"#F5F7FA\">= असली \"प्रति-साड़ी योगदान\" ₹235</text>\n</g>\n<rect x=\"60\" y=\"450\" width=\"680\" height=\"110\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"485\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">30% अंगूठा-नियम</text>\n<text x=\"400\" y=\"520\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">प्रति-ऑर्डर विज्ञापन-ख़र्च, CM के 30% से ज़्यादा न हो</text>\n<text x=\"400\" y=\"548\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">इस उदाहरण में ठीक सीमा पर — सावधानी चाहिए</text>\n<rect x=\"60\" y=\"580\" width=\"680\" height=\"130\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"615\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">नया बनाम लौटा ग्राहक</text>\n<text x=\"400\" y=\"650\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">पहली बिक्री — विज्ञापन-\"उधार\" चुकाती है (₹235 बचा)</text>\n<text x=\"400\" y=\"680\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">दूसरी (लौटी) बिक्री — पूरा CM ₹335 शुद्ध कमाई</text>\n</svg>\n```\n\n## एक चेतावनी-कहानी — बिना जाँच के बढ़ता नुक़सान\nमान लो एक दुकान ने ROAS=8 देखकर उत्साहित होकर विज्ञापन-बजट तीन गुना बढ़ा दिया, बिना यह जाँचे कि प्रति-ऑर्डर विज्ञापन-ख़र्च क्या था। अगले महीने ऑर्डर तो 40% बढ़े, पर प्रति-ऑर्डर विज्ञापन-ख़र्च भी बढ़कर CM का 60% हो गया (क्योंकि ज़्यादा बजट में दर्शक कम-रुचि वाले भी शामिल हो गए, चैट-से-बिक्री दर गिर गई) — कुल मिलाकर मुनाफ़ा असल में घट गया, भले बिक्री-संख्या बढ़ी दिखी। यह कहानी दिखाती है कि \"बिक्री बढ़ना\" और \"मुनाफ़ा बढ़ना\" दो अलग चीज़ें हैं, और यह पाठ ठीक इसी फ़र्क़ को पकड़ने के लिए है।\n\n## 3. आज का काम «काम-कार्ड»\nअपने किसी उत्पाद पर पूरा गणित कीजिए — बिक्री-मूल्य, लागत, gateway-शुल्क, पैकिंग (पाठ-67 का सूत्र), Contribution Margin निकालिए। फिर पाठ-99 के अपने विज्ञापन-नतीजों से प्रति-ऑर्डर विज्ञापन-ख़र्च निकालिए और घटाइए। 30%-सीमा से तुलना कीजिए — सीमा के भीतर हैं या पार? जाँच-सूची: ☐ पूरा Contribution Margin सूत्र ☐ प्रति-ऑर्डर विज्ञापन-ख़र्च ☐ 30%-सीमा तुलना ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — इस हिसाब को हर बार बिल्कुल नए सिरे से न बनाएँ, बल्कि एक तय ढाँचा (spreadsheet या काग़ज़-साँचा) रखें जहाँ सिर्फ़ नए अंक भरने हों — इससे महीने-दर-महीने तुलना बहुत आसान हो जाती है।\n\n## 4. नाप\nसफल = हर अंक असली/यथार्थवादी अंदाज़े से (गढ़ा नहीं); 30%-तुलना का नतीजा साफ़ लिखा। समय: 30 मिनट।\n\nअगले महीने इसी हिसाब को दोबारा करें और पिछले महीने से तुलना करें — यह तुलना ही असली सीख है, एक बार का हिसाब सिर्फ़ शुरुआत है।\n\n## 5. सबूत\nसबूत-खाते में \"Meta unit-economics पूरा हिसाब\"। यह पाठ-102 के मासिक रख-रखाव में हर महीने दोहराया जाने वाला मुख्य खाना बनेगा।\n\nAI से यह भी पूछा जा सकता है — 'मेरे नए और लौटे ग्राहकों की बिक्री अलग-अलग गिनी जाए तो मासिक मुनाफ़ा-गणना कैसे बदलती है' — यह पाँचवीं ग़लती से बचने में मदद करेगा।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरे उत्पाद का बिक्री-मूल्य ₹(राशि), लागत ₹(राशि), और विज्ञापन-ख़र्च प्रति-ऑर्डर ₹(राशि) है — Contribution Margin और असली बचा मुनाफ़ा निकालो।\" — गणित AI से जँचवा सकते हैं, पर अंक अपने असली रिकॉर्ड से ही दें।\n\n## पाँचवीं ग़लती और सुधार\nपाँचवीं आम ग़लती — सिर्फ़ नए ग्राहकों पर विज्ञापन-ख़र्च का हिसाब रखना और लौटे ग्राहकों को पूरी तरह अनदेखा कर देना, जिससे असली मासिक मुनाफ़ा हमेशा कम दिखता है। हर महीने कुल Contribution Margin में नए-ग्राहक-बिक्री और लौटे-ग्राहक-बिक्री दोनों को अलग-अलग गिनकर जोड़ना असली तस्वीर देता है — यह भेद अक्सर अनुभवी दुकानदार को भी नए दुकानदार से अलग करता है।\n\n## 7. आम ग़लती\nपहली — ROAS का बड़ा नंबर देखकर बिना मार्जिन-जाँच के विज्ञापन-बजट बढ़ा देना। दूसरी — विज्ञापन-ख़र्च को unit-economics से बाहर, \"अलग खाता\" मानकर कभी न जोड़ना। तीसरी — 30%-सीमा पार होने पर भी नज़रअंदाज़ करना, \"बिक्री तो बढ़ रही है\" सोचकर। चौथी — लौटे ग्राहकों की गिनती न रखना, जिससे असली मुनाफ़े का सबसे बड़ा हिस्सा छुप जाता है।\n\nयह अंतर (नया बनाम लौटा ग्राहक) रिकॉर्ड में रखते समय भी ग्राहक की पहचान गुप्त रख सकते हैं — सिर्फ़ 'नया' या 'लौटा' टैग काफ़ी है, नाम-फ़ोन नहीं चाहिए।\n\n## 8. सुरक्षा-पत्रक\nयह गणित-पन्ना दुकान की आंतरिक जानकारी है — लागत-मार्जिन किसी बाहरी व्यक्ति (प्रतियोगी सहित) से साझा न करें, सिर्फ़ अपने भरोसेमंद सेवा-सहायक/परिवार के साथ।\n\nआगे पाठ-102 (मासिक रख-रखाव) में यह पूरा गणित हर महीने दोहराए जाने वाले अनुशासन का मुख्य हिस्सा बनेगा।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: पाठ-67 का Unit-Economics सूत्र (आंतरिक कड़ी) व Meta Ads Reporting दस्तावेज़ — https://www.facebook.com/business/help/ads-reporting — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ad-spend-in-unit-economics · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\nयह पाठ खंड-7 का गणित-केंद्र है — जो कुछ भी सीखा गया, वह सब अंततः इसी सवाल पर टिकता है: क्या असली मुनाफ़ा बचा या नहीं।\n\n## 10. योग्यता-जाँच\n- [ ] मैं प्रति-ऑर्डर विज्ञापन-ख़र्च का सूत्र लगा सकता हूँ।\n- [ ] मैंने अपने उत्पाद का पूरा unit-economics + विज्ञापन-ख़र्च हिसाब किया है।\n- [ ] मैं 30%-अंगूठा-नियम जानता हूँ।\n- [ ] मैं जानता हूँ नए बनाम लौटे ग्राहक का गणित क्यों अलग है।\n- [ ] मैं जानता हूँ ROAS अकेला काफ़ी क्यों नहीं है।",
 "102": "═\n# पाठ-102: Meta मासिक रख-रखाव काम-कार्ड\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड-7 के सभी औज़ार (Business Suite, कैटलॉग, Shop, Marketplace, Reel, DM, विज्ञापन, नीति, unit-economics) अब एक साथ चलने चाहिए। पाठ के बाद आप तीन बातें कर पाएँगे — रोज़/हफ़्ते/महीने के तीन-स्तर वाला Meta-रख-रखाव काम-कार्ड बना पाएँगे; इसे पाठ-84 के API-काम-कार्ड से जोड़ पाएँगे; और अपनी दुकान का पूरा \"बहु-मंच स्वास्थ्य-पन्ना\" तैयार कर पाएँगे।\n\n## 2. मुख्य बात\nपाठ-84 में हमने WhatsApp Platform का तीन-स्तर काम-कार्ड देखा था। एक-वाक्य बात — **Meta-मंच (Facebook, Instagram, Ads) के लिए भी वैसा ही तीन-स्तर काम-कार्ड चाहिए — बिना इसके Reel-Marketplace-DM-Ads जैसे कई औज़ार अलग-अलग बिखर जाते हैं और कोई भी ठीक से नहीं सँभलता।**\n\n## रोज़ का काम — दस मिनट\n1. Business Suite inbox में कोई अनुत्तरित DM/comment तो नहीं (पाठ-91)? 2. कल का कोई विज्ञापन नामंज़ूर तो नहीं हुआ (पाठ-100 के चार-कदम तुरंत)? 3. Marketplace-listing में कोई बिका उत्पाद अभी भी \"उपलब्ध\" तो नहीं दिख रहा (पाठ-89)?\n\n## हफ़्ते का काम — पैंतालीस मिनट\n1. content-कैलेंडर (पाठ-92) के अनुसार Channel-संदेश/Stories भेजे गए? 2. एक नया Reel तैयार व post हुआ (पाठ-90)? 3. चल रहे विज्ञापन के नतीजे — CPM, चैट-संख्या, चैट-से-बिक्री दर (पाठ-99) नोट किए? 4. रचना-ताज़गी जाँची — क्या creative पुराना पड़ने लगा है (पाठ-97)? 5. कैटलॉग (पाठ-87) में दाम-स्टॉक सही हैं?\n\n## महीने का काम — दो घंटे\n1. पूरा Meta unit-economics हिसाब (पाठ-101) — असली बचा मुनाफ़ा, 30%-सीमा जाँच। 2. Advantage+ का फ़ैसला (पाठ-95) दोबारा — क्या अब पर्याप्त डेटा जमा हुआ है? 3. Pixel-CAPI का फ़ैसला (पाठ-94) दोबारा — क्या दुकान इतनी बड़ी हो गई कि अब ज़रूरत है? 4. लौटे ग्राहकों की गिनती (पाठ-101) — कितने % बढ़े/घटे? 5. Business Manager सुरक्षा-जाँच (पाठ-100) — Partner Access, दो-कदम-सत्यापन।\n\n## दो काम-कार्ड, एक \"बहु-मंच स्वास्थ्य-पन्ना\"\nअब आपके पास दो काम-कार्ड हैं — WhatsApp-Platform (पाठ-84) और Meta (यह पाठ)। दोनों को एक ही पन्ने पर, दो अलग खंडों में रखें, नीचे साझा unit-economics (जो अब पाठ-67, पाठ-78, पाठ-101 तीनों का जोड़ है)। यही दुकान का पूरा \"बहु-मंच स्वास्थ्य-पन्ना\" है — एक जगह से पूरी दुकान की डिजिटल-सेहत दिखती है।\n\n## सेवा-सहायक की आँख\nयह जोड़ा हुआ पन्ना आपकी सबसे बड़ी, सबसे व्यापक सेवा-रूपरेखा है — \"मासिक बहु-मंच प्रबंधन सेवा\" के नाम से बेची जा सकती है। नए दुकानदार को दिखाइए कि बिना इस अनुशासन के, हर मंच अलग-अलग टूटता जाता है — और यही आपकी सेवा-फ़ीस को स्पष्ट रूप से सही ठहराता है।\n\n## चित्र — बहु-मंच स्वास्थ्य-पन्ना\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Meta मासिक रख-रखाव — बहु-मंच स्वास्थ्य-पन्ना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">रोज़-हफ़्ते-महीने — WhatsApp-काम-कार्ड से जुड़ा</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#2E7D32\">रोज़ — 10 मिनट</text>\n<text x=\"55\" y=\"190\">DM/comment जवाब</text><text x=\"55\" y=\"216\">विज्ञापन-नामंज़ूरी</text><text x=\"55\" y=\"242\">बिका-listing हटाना</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\">हफ़्ते — 45 मिनट</text>\n<text x=\"305\" y=\"188\">Channel/Stories</text><text x=\"305\" y=\"212\">नया Reel</text><text x=\"305\" y=\"236\">विज्ञापन-नतीजे</text><text x=\"305\" y=\"260\">रचना-ताज़गी</text><text x=\"305\" y=\"284\">कैटलॉग-जाँच</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"650\" y=\"155\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#1565C0\">महीने — 2 घंटे</text>\n<text x=\"555\" y=\"188\">unit-economics हिसाब</text><text x=\"555\" y=\"212\">Advantage+ फ़ैसला</text><text x=\"555\" y=\"236\">Pixel-CAPI फ़ैसला</text><text x=\"555\" y=\"260\">लौटे-ग्राहक गिनती</text><text x=\"555\" y=\"284\">सुरक्षा-जाँच</text>\n</g>\n<rect x=\"60\" y=\"330\" width=\"680\" height=\"150\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"365\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">दो काम-कार्ड, एक पन्ना</text>\n<text x=\"400\" y=\"400\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">WhatsApp-Platform (पाठ-84) + Meta (यह पाठ)</text>\n<text x=\"400\" y=\"430\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">नीचे साझा unit-economics (पाठ 67+78+101)</text>\n<rect x=\"60\" y=\"500\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"545\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">\"मासिक बहु-मंच प्रबंधन सेवा\" — आपकी सबसे व्यापक सेवा</text>\n</svg>\n```\n\n## एक व्यावहारिक नमूना-भरा पन्ना\nसमझने के लिए एक भरा नमूना — रोज़: \"आज दो DM का जवाब दिया, कोई नामंज़ूरी नहीं, एक बिका-Marketplace-listing हटाई\"। हफ़्ते: \"एक Stories-offer और एक Channel-संदेश गया, नया Reel post हुआ (250 views), CPM ₹18, चैट-से-बिक्री दर 22%, creative अभी ताज़ा है\"। महीने: \"unit-economics हिसाब — प्रति-ऑर्डर विज्ञापन-ख़र्च CM के 24% पर, सुरक्षित सीमा में; Advantage+ अभी नहीं, दो महीने और डेटा चाहिए; Pixel-CAPI अभी ज़रूरी नहीं; लौटे ग्राहक 15% से बढ़कर 19% हुए — अच्छी दिशा\"। यह नमूना दिखाता है कि हर स्तर पर सिर्फ़ दो-तीन ईमानदार पंक्तियाँ काफ़ी हैं।\n\n## 3. आज का काम «काम-कार्ड»\nएक पन्ने पर तीन कॉलम (रोज़/हफ़्ते/महीने) बनाइए, ऊपर की सूची से अपनी दुकान के लिए काम भरिए। पाठ-84 का पुराना WhatsApp-काम-कार्ड निकालकर इसी पन्ने पर जोड़िए — दो खंड, एक साझा नीचे-हिस्सा (unit-economics)। पन्ने को \"दुकान का बहु-मंच स्वास्थ्य-पन्ना\" नाम दीजिए। जाँच-सूची: ☐ तीनों स्तर पूरे ☐ WhatsApp-काम-कार्ड जोड़ा गया ☐ साझा unit-economics खंड ☐ फ़ोटो सबूत-खाते में।\n\nव्यावहारिक टिप — नमूना-पन्ने की भाषा जितनी छोटी और साफ़ रहे, उतना बेहतर; यह पाठ-84 में भी सीखा था — रख-रखाव जितना सरल, उतना निभाया जाएगा।\n\nव्यावहारिक टिप — पहला महीना यह काम-कार्ड शायद अधूरा या अनियमित लगे, यह सामान्य है; नई आदत बनने में तीन-चार हफ़्ते लगते हैं, हार न मानें।\n\n## 4. नाप\nसफल = तीनों स्तर पर कम-से-कम चार-चार काम, अपनी दुकान से जुड़े। समय: 30 मिनट।\n\nअगर काम-कार्ड को एक-दो हफ़्ते तक असली इस्तेमाल में लाकर परिणाम भी नोट करें, तो यह सबूत सिर्फ़ मसौदा नहीं, एक जीता-जागता प्रमाण बन जाएगा।\n\n## 5. सबूत\nसबूत-खाते में \"बहु-मंच स्वास्थ्य-पन्ना v1\"। पोर्टफ़ोलियो-10 (खंड-24) में यह आपकी सबसे संपूर्ण, उच्च-स्तरीय सेवा-रूपरेखा के रूप में जाएगा।\n\nएक याद रखने वाली बात — काम-कार्ड बनाने के बाद उसे किसी भरोसेमंद जगह (फ़ोन-फ़ोल्डर या दीवार) रखें जहाँ रोज़ नज़र पड़े, वरना सबसे अच्छा बनाया हुआ पन्ना भी भुला दिया जाता है।\n\nAI से पूछा जा सकता है — 'मेरे बहु-मंच स्वास्थ्य-पन्ने में कौन-सा खाना सबसे ज़रूरी है जो मैं भूल सकता हूँ' — यह एक ताज़ा नज़रिया दे सकता है, ख़ासकर जब पन्ना बहुत बड़ा लगने लगे।\n\n## 6. AI-सहायक\nAI से पूछिए — \"एक छोटी भारतीय दुकान के लिए Facebook-Instagram-Meta Ads का रोज़-हफ़्ते-महीने रख-रखाव काम-कार्ड बनाओ।\" — जवाब मिलाइए अपने ऊपर लिखे कामों से।\n\n## दो अलग दुकानों का तीन-महीने का असर\nमान लो दो दुकानें एक ही महीने खंड-7 पूरा करती हैं। दुकान-अ हर हफ़्ते ईमानदारी से काम-कार्ड भरती है — तीसरे महीने तक उसकी सभी listing ताज़ा, content-कैलेंडर नियमित, विज्ञापन-नतीजे सुधरते जाते हैं। दुकान-ब सेटअप के बाद काम-कार्ड कभी नहीं खोलती — दूसरे महीने में एक विज्ञापन नामंज़ूर होकर हफ़्तों बिना ध्यान दिए पड़ा रहता है, कैटलॉग में बिका उत्पाद अभी भी \"उपलब्ध\" दिखता रहता है, ग्राहक निराश होते हैं। दोनों दुकानों के पास एक जैसी तकनीक थी — फ़र्क़ सिर्फ़ अनुशासन का था।\n\n## 7. आम ग़लती\nपहली — WhatsApp और Meta के काम-कार्ड को अलग-अलग पन्नों पर रखना — भूलने की जड़। दूसरी — सिर्फ़ महीने का काम करना, रोज़-हफ़्ते टालना — छोटी समस्या बड़ी बनती है, ख़ासकर विज्ञापन-नामंज़ूरी। तीसरी — काम-कार्ड बनाकर कभी न खोलना (पाठ-84 की भी यही सबसे आम ग़लती)। चौथी — साझा unit-economics खंड को छोड़ देना और दोनों मंचों का हिसाब अलग-अलग, बिना जोड़े रखना।\n\nअगर दुकान में किसी नाबालिग सदस्य को Meta-प्रबंधन में मदद करनी हो, तो असली ख़ाता-नियंत्रण अभिभावक के नाम पर ही रहे — पाठ-8 और पाठ-86 के नियम यहाँ भी लागू।\n\n## 8. सुरक्षा-पत्रक\nकाम-कार्ड में ग्राहक-निजी जानकारी नहीं, सिर्फ़ प्रक्रिया व गिनती। जहाँ यह पन्ना रखा जाए, वहाँ दुकान-मालिक की जानकारी में हो; सेवा-अनुबंध ख़त्म होने पर मालिक को पूरा पन्ना (WhatsApp+Meta दोनों खंड) सौंप दिया जाए।\n\nअगला पाठ-103 इसी पूरे खंड-7 का दोहराव और परीक्षा है — वहाँ आप जाँच पाएँगे कि इस पन्ने की समझ कितनी मज़बूत है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। 📎 मूल-कोर्स-कड़ी: Meta Business Suite व Ads Manager — Best Practices — https://www.facebook.com/business/help — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=multi-platform-maintenance-routine · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\nअगले पाठ (103) में खंड-7 का समापन होगा, जहाँ यह पूरा काम-कार्ड और अभी तक सीखी हर चीज़ एक साथ जाँची जाएगी।\n\n## 10. योग्यता-जाँच\n- [ ] मैंने तीन-स्तर Meta-काम-कार्ड अपनी दुकान के लिए बनाया है।\n- [ ] मैंने इसे WhatsApp-काम-कार्ड (पाठ-84) से जोड़ा है।\n- [ ] मैं जानता हूँ रोज़-हफ़्ते-महीने में क्या-क्या देखना है।\n- [ ] मैं इस पन्ने को \"बहु-मंच स्वास्थ्य-पन्ना\" के रूप में समझता हूँ।\n- [ ] मैं जानता हूँ यह पन्ना दुकान-मालिक को सौंपा जाएगा।",
 "103": "═\n# पाठ-103: खंड-7 दोहराव व अभ्यास-परीक्षा\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-7 · generator-input मसौदा v1.0 · स्तर S · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड-7 (Meta Shops, Instagram व Facebook) समाप्त हुआ — यह सबसे बड़ा खंड था, 18 पाठ। पाठ के बाद आप तीन बातें कर पाएँगे — खंड-7 के अठारह पाठों को अपने शब्दों में जोड़कर बता पाएँगे; बिना पाठ खोले 20-प्रश्न परीक्षा दे पाएँगे; और अपनी \"दुकान का Meta काम-कार्ड\" पूरा भरा हुआ तैयार कर पाएँगे।\n\n## 2. मुख्य बात\nखंड-7 का सफ़र Business Suite जोड़ने से शुरू होकर मासिक रख-रखाव पर ख़त्म हुआ। एक-वाक्य बात — **Meta-मंच WhatsApp की तरह \"दुकान का मुख्य घर\" नहीं, बल्कि \"आकर्षण और पहुँच बढ़ाने का पुल\" है — मुफ़्त-सूचना पहले मज़बूत करें, फिर सोच-समझकर, छोटे बजट से विज्ञापन जोड़ें, और हर पैसे का हिसाब मार्जिन तक ले जाएँ।**\n\n## अठारह पाठों की कड़ी — एक नज़र में\n86 Business Suite (एक घर, तीन खिड़कियाँ) → 87 Commerce Manager कैटलॉग (एक कैटलॉग तीन जगह) → 88 Shop व checkout (भारत के लिए ईमानदार सलाह) → 89 Marketplace (मुफ़्त स्थानीय बिक्री) → 90 Reels (30-सेकंड ढाँचा) → 91 product-tag व DM (Instagram=आकर्षण, WhatsApp=लेन-देन) → 92 Broadcast Channel व Stories (24-घंटे झलकी बनाम टिकाऊ सूचना) → 93 Meta Ads मूल (तीन खंभे) → 94 Pixel-CAPI (नापने के दो रास्ते) → 95 Advantage+ (कब असरदार, कब बर्बाद) → 96 Click-to-WhatsApp व Catalog-ads (दो प्रकार, कौन कब) → 97 त्योहार-मूल्य-चक्र (तीन चरण) → 98 AI से विज्ञापन-रचना (मसौदा AI, सच अपना) → 99 नतीजा पढ़ना (CPM-ROAS-चैट-दर) → 100 Meta नीति (पाँच नामंज़ूरी-कारण, ख़ाता-सुरक्षा) → 101 unit-economics (असली बचा मुनाफ़ा) → 102 मासिक रख-रखाव (बहु-मंच स्वास्थ्य-पन्ना)।\n\n## बीस-प्रश्न परीक्षा — बिना पाठ खोले दीजिए\n1. Business Suite से तीन कौन-से खाते जुड़ते हैं? 2. Commerce Manager कैटलॉग तीन जगह कैसे दिखता है? 3. भारत में checkout का सबसे भरोसेमंद रास्ता कौन-सा है? 4. Marketplace किन उत्पादों के लिए सबसे उपयोगी है? 5. Reel के 30-सेकंड ढाँचे के तीन हिस्से क्या हैं? 6. Instagram और WhatsApp में काम कैसे बँटता है? 7. Broadcast Channel और Stories में क्या फ़र्क़ है? 8. Meta Ads के तीन खंभे कौन-से हैं? 9. Pixel और CAPI में क्या फ़र्क़ है? 10. Advantage+ कब असरदार होता है? 11. Click-to-WhatsApp और Catalog-ads में क्या फ़र्क़ है? 12. त्योहार-मूल्य-चक्र के तीन चरण क्या हैं? 13. \"मसौदा AI, सच अपना\" का मतलब क्या है? 14. CPM, ROAS, चैट-से-बिक्री दर क्या हैं? 15. विज्ञापन नामंज़ूरी के आम कारण क्या हैं? 16. Ads-ख़ाता कैसे सुरक्षित रखें? 17. प्रति-ऑर्डर विज्ञापन-ख़र्च कैसे निकालें? 18. 30%-अंगूठा-नियम क्या है? 19. लौटा ग्राहक मुनाफ़े में क्यों ज़्यादा जोड़ता है? 20. मासिक रख-रखाव के तीन स्तर कौन-से हैं?\n\n## अपनी दुकान का पूरा Meta काम-कार्ड\nअब सारे टुकड़े जोड़िए — पाठ-86 का Business Suite-जुड़ाव, पाठ-87 का कैटलॉग-फ़ीड, पाठ-88 का Shop-फ़ैसला, पाठ-89 का Marketplace-listing, पाठ-90-92 के content-नमूने, पाठ-93-96 के विज्ञापन-ढाँचे, पाठ-97 की त्योहार-योजना, पाठ-99-101 के नतीजा-हिसाब, पाठ-102 का बहु-मंच स्वास्थ्य-पन्ना — यह सब मिलाकर एक \"Meta काम-कार्ड\" बनता है, आपकी सबसे बड़ी सेवा-रूपरेखा। यह पोर्टफ़ोलियो (खंड-24) में एक पूरा दस्तावेज़ बनेगा।\n\n## सेवा-सहायक की आँख\nखंड-7 पूरा करने के बाद आप किसी भी दुकान को मुफ़्त-सूचना से लेकर भुगतान-विज्ञापन तक, पूरा Meta-सफ़र सँभाल सकते हैं — और सबसे ज़रूरी, हर पैसे को असली मार्जिन तक जोड़कर देख सकते हैं, जो कई \"digital marketing expert\" भी नहीं करते।\n\n## चित्र — खंड-7 का पूरा नक़्शा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">खंड-7 का पूरा नक़्शा — अठारह पाठ</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बुनियाद → मुफ़्त-सूचना → भुगतान-विज्ञापन → नाप-निगरानी</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"30\" y=\"115\" width=\"180\" height=\"140\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"120\" y=\"140\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"16\">बुनियाद</text><text x=\"45\" y=\"165\">86 Business Suite</text><text x=\"45\" y=\"188\">87 कैटलॉग</text><text x=\"45\" y=\"211\">88 Shop</text>\n<rect x=\"220\" y=\"115\" width=\"180\" height=\"140\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><text x=\"310\" y=\"140\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"16\">मुफ़्त-सूचना</text><text x=\"235\" y=\"165\">89 Marketplace</text><text x=\"235\" y=\"188\">90 Reels</text><text x=\"235\" y=\"211\">91-92 DM-Channel</text>\n<rect x=\"410\" y=\"115\" width=\"180\" height=\"140\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/><text x=\"500\" y=\"140\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"16\" fill=\"#1565C0\">भुगतान-विज्ञापन</text><text x=\"425\" y=\"165\">93-96 Ads-मूल</text><text x=\"425\" y=\"188\">97 त्योहार</text><text x=\"425\" y=\"211\">98 AI-रचना</text>\n<rect x=\"600\" y=\"115\" width=\"170\" height=\"140\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/><text x=\"685\" y=\"140\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"16\" fill=\"#2E7D32\">नाप-निगरानी</text><text x=\"615\" y=\"165\">99 नतीजा</text><text x=\"615\" y=\"188\">100 नीति</text><text x=\"615\" y=\"211\">101-102 मार्जिन</text>\n</g>\n<rect x=\"60\" y=\"290\" width=\"680\" height=\"120\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"325\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">एक-वाक्य सार</text>\n<text x=\"400\" y=\"360\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">Meta = आकर्षण-पुल, WhatsApp = मुख्य घर — मुफ़्त पहले,</text>\n<text x=\"400\" y=\"388\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">फिर छोटा-बजट विज्ञापन, हर पैसा मार्जिन तक जोड़ें</text>\n<rect x=\"60\" y=\"430\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"470\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">बीस-प्रश्न परीक्षा — बिना पाठ खोले दें</text>\n<text x=\"400\" y=\"500\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">अंक कमज़ोर-कड़ी दिखाएँ — वहीं पाठ दोबारा पढ़ें</text>\n<rect x=\"60\" y=\"540\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"580\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#2E7D32\">अगला — खंड-8: Google (Business Profile, Gemini, Merchant Center, Ads)</text>\n</svg>\n```\n\n## बचे हुए समय का उपयोग\nअगर परीक्षा और काम-कार्ड जल्दी पूरे हो जाएँ, तो बचे समय में पाठ-101 का अपना unit-economics हिसाब दोबारा खोलिए और जाँचिए — क्या पिछले हफ़्ते के नए विज्ञापन-नतीजों से यह हिसाब बदल गया है? यह छोटा अतिरिक्त अभ्यास खंड-7 की सबसे ज़रूरी सीख (हर पैसे को मार्जिन तक जोड़ना) को ताज़ा रखता है और आगे खंड-8 (Google) में इसी सोच को दोहराने के लिए तैयार करता है।\n\n## 3. आज का काम «काम-कार्ड»\nबीस-प्रश्न परीक्षा बिना कोई पाठ खोले दीजिए — कॉपी में नंबर-दर-नंबर जवाब लिखिए। इसके बाद ऊपर सूची से मिलाकर अपने अंक गिनिए और कमज़ोर सवालों के पाठ फिर से पढ़िए। फिर पाठ 86-102 के सारे पन्ने एक फ़ोल्डर में जोड़कर \"दुकान का Meta काम-कार्ड\" नाम दीजिए। जाँच-सूची: ☐ 20 प्रश्नों के जवाब बिना पाठ खोले ☐ अंक व कमज़ोर-कड़ी सूची ☐ सारे पन्ने एक जगह जोड़े ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = 20 में से कम-से-कम 14 सही (70%); कमज़ोर-कड़ी सूची ईमानदार। समय: 45 मिनट परीक्षा + 20 मिनट जोड़ना।\n\n## 5. सबूत\nसबूत-खाते में \"खंड-7 परीक्षा-अंक\" और \"पूरा Meta काम-कार्ड\"। यह पोर्टफ़ोलियो-10 (खंड-24) की एक अनिवार्य प्रविष्टि है।\n\nपरीक्षा के बाद, अगर कमज़ोर-कड़ी बहुत ज़्यादा हों, AI से कह सकते हैं — 'खंड-7 के इन पाँच विषयों (लिखें) को सरल कहानी-रूप में फिर से समझाओ' — कहानी-शैली अक्सर तकनीकी विवरण से ज़्यादा याद रहती है।\n\n## 6. AI-सहायक\nपरीक्षा पाठ खोलकर न दें — यह ख़ुद की याद्दाश्त परखने के लिए है। बाद में AI से पूछ सकते हैं — \"मेरे कमज़ोर जवाब (लिखें) पर आसान भाषा में फिर समझाओ।\"\n\n## अंतिम प्रोत्साहन\nअगर 20 में से कम अंक आएँ, याद रखें — खंड-7 इस पूरे कोर्स का सबसे बड़ा और सबसे विविध खंड था, अठारह पाठों में Business Suite से लेकर unit-economics तक की यात्रा। यही वजह है कि इसे r5 स्तर (कमाई-सीढ़ी, पाठ-5) की योग्यता माना गया है — तकनीकी गहराई और व्यावसायिक समझ दोनों चाहिए। कमज़ोर सवालों को दोबारा पढ़ना कोई असफलता नहीं, बल्कि इस स्तर पर सामान्य और अपेक्षित प्रक्रिया है।\n\n## 7. आम ग़लती\nपहली — परीक्षा पाठ खोलकर देना। दूसरी — काम-कार्ड में सामान्य/काल्पनिक जानकारी भरना, अपनी असली दुकान की नहीं। तीसरी — कम अंक पर हिम्मत हारना — खंड-7 सबसे बड़ा और तकनीकी खंड था, दोबारा पढ़ना सामान्य है। चौथी — काम-कार्ड बनाकर फिर कभी न देखना।\n\nअंतिम रूप से जोड़े गए काम-कार्ड में अगर किसी और सेवा-सहायक/परिवार के सदस्य की मदद ली हो, तो उनका सिर्फ़ नाम/भूमिका दर्ज करें, कोई निजी संपर्क-जानकारी नहीं, ताकि पन्ना सार्वजनिक-योग्य (पोर्टफ़ोलियो-लायक़) बना रहे।\n\n## 8. सुरक्षा-पत्रक\nकाम-कार्ड पन्ने में ग्राहकों के नाम-फ़ोन नहीं — सिर्फ़ आपकी अपनी दुकान की प्रक्रिया। खंड-8 (Google) में जाने से पहले याद रखें — Meta पर सीखी ईमानदारी और सतर्कता के नियम (सच्चे दावे, बजट-नियंत्रण, नीति-पालन) आगे हर मंच पर वैसे ही लागू होंगे।\n\nअगला खंड-8 (Google) उसी unit-economics सोच को Google Ads, Merchant Center और Business Profile की दुनिया में लेकर जाएगा — इस खंड में सीखा गणित-अनुशासन वहाँ भी उतना ही ज़रूरी रहेगा।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। बीस प्रश्न खंड-7 के पाठ 86-102 पर; हर प्रश्न का उत्तर उसी नंबर वाले पाठ में है। 📎 मूल-कोर्स-कड़ी: Meta for Business पूरा दस्तावेज़ — https://www.facebook.com/business — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=review-khand7 · platform=meta · level=S · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैंने 20-प्रश्न परीक्षा बिना पाठ खोले दी है।\n- [ ] मैंने अंक ईमानदारी से लिखे और कमज़ोर-कड़ी सूची बनाई है।\n- [ ] मेरा पूरा \"दुकान का Meta काम-कार्ड\" असली जानकारी से बना है।\n- [ ] मैं जानता हूँ Meta और WhatsApp की भूमिका में क्या फ़र्क़ है।\n- [ ] मैं खंड-8 (Google) के लिए तैयार हूँ।"
};
